window.KG_LJDRILL = [{"set": 101, "cat": "翻译推理", "title": "专项挑战 · 翻译推理", "date": "", "session": "", "items": [{"type": "翻译推理", "from": "2026年国家公务员录用考试《行测》题（副省级网友回忆版） 第31 题", "qid": 19526453, "level": "中等", "stem": "“三医”是医疗、医保、医药的简称，只有提高卫生事业发展水平，且相关部门密切合作、同向发力，才能促进“三医”协同发展和治理。只有深化医改领导体制和工作推进机制，才能促进“三医”协同发展和治理。深化医改领导体制和工作推进机制，必须强化区域医疗卫生规划和医疗机构设置规划的刚性约束。只有深化医改领导体制和工作推进机制，才能更好满足人民群众对美好生活的新期待，进而提高人民群众的获得感、幸福感和安全感。\n由此可以推出：", "options": ["只要提高卫生事业发展水平，就能使相关部门密切合作、同向发力", "只有强化区域医疗卫生规划和医疗机构设置规划的刚性约束，才能提高人民群众的获得感、幸福感和安全感", "要深化医改领导体制和工作推进机制，就必须促进“三医”协同发展和治理", "如果不能更好满足人民群众对美好生活的新期待，就不能促进“三医”协同发展和治理"], "answer": ["B"], "explain": "第一步：翻译题干。（1）促进“三医”协同发展和治理提高卫生事业发展水平 且 相关部门密切合作、同向发力；（2）促进“三医”协同发展和治理深化医改领导体制和工作推进机制；（3）深化医改领导体制和工作推进机制强化区域医疗卫生规划和医疗机构设置规划的刚性约束；（4）提高人民群众的获得感、幸福感和安全感更好满足人民群众对美好生活的新期待深化医改领导体制和工作推进机制；（2）和（3）可串联为：（5）促进“三医”协同发展和治理深化医改领导体制和工作推进机制强化区域医疗卫生规划和医疗机构设置规划的刚性约束；（3）和（4）可串联为：（6）提高人民群众的获得感、幸福感和安全感更好满足人民群众对美好生活的新期待深化医改领导体制和工作推进机制强化区域医疗卫生规划和医疗机构设置规划的刚性约束。第二步：逐一分析选项。A项：翻译为：提高卫生事业发展水平相关部门密切合作、同向发力，均是条件（1）的后半部分，二者为且关系，无法推出，排除；B项：翻译为：提高人民群众的获得感、幸福感和安全感强化区域医疗卫生规划和医疗机构设置规划的刚性约束，是对条件（6）的肯前，肯前必肯后，可以推出，当选；C项：翻译为：深化医改领导体制和工作推进机制促进“三医”协同发展和治理，是对条件（2）的肯后，肯后无必然结论，无法推出，排除；D项：翻译为：更好满足人民群众对美好生活的新期待促进“三医”协同发展和治理，是对条件（4）的否前，否前无必然结论，无法推出，排除。⇒ 正确答案为B。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2016年3月四川省选调优秀大学生到基层工作考试 行政职业能力测验试卷（精选） 第29 题", "qid": 2263062, "level": "中等", "stem": "有些男士吸烟，所有男士都喜欢运动。\n据此，可推出：", "options": ["有些吸烟的男士喜欢运动", "有些喜欢运动的男士不吸烟", "有些男士不吸烟，但喜欢运动", "有些男士吸烟，但不喜欢运动"], "answer": ["A"], "explain": "第一步：翻译题干。①有些男士吸烟 ②男士喜欢运动将条件①换位得到：有些吸烟男士可以递推出：③有些吸烟男士喜欢运动第二步：逐一分析选项。A项：翻译为有些吸烟的男士喜欢运动，有些吸烟的男士是对条件③的肯前，肯前必肯后，可以推出喜欢运动，当选；B项：翻译为有些喜欢运动的男士吸烟，有些喜欢运动的男士是对条件③的肯后，肯后无必然性结论，排除；C项：翻译为有些男士吸烟且喜欢运动，是对条件①和②的肯前，肯前必肯后，可以推出吸烟且喜欢运动，而非吸烟，排除；D项：翻译为有些男士吸烟 且 喜欢运动，是对条件①和②的肯前，肯前必肯后，可以推出吸烟且喜欢运动，而非喜欢运动，排除。⇒ 正确答案为A。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2026年广东省公务员录用考试《行测》题（网友回忆版） 第6 题", "qid": 18643984, "level": "中等", "stem": "如果一座城市采用集约高效的发展方式，那么其资源消耗量必然会减少。只要这种减少速度非常缓慢，就不会对城市经济发展造成负面影响。\n由此可以推出：", "options": ["如果资源消耗量没有减少，说明该城市没有采用集约高效的发展方式", "如果城市没有采用集约高效的发展方式，其资源消耗量必然没有减少", "如果资源消耗量减少，说明该城市采用了集约高效的发展方式", "如果资源消耗量减少的速度很快，必然会对该城市的经济发展造成负面影响"], "answer": ["A"], "explain": "第一步：翻译题干。①采用集约高效的发展方式资源消耗量减少；②减少速度缓慢对经济发展造成负面影响。第二步：逐一分析选项。A项：该项翻译为“资源消耗量减少采用集约高效的发展方式”，是对①的否后，否后必否前，可以推出，当选；B项：该项翻译为“采用集约高效的发展方式资源消耗量减少”，是对①的否前，否前得不到确定性的结论，不能推出，排除；C项：该项翻译为“资源消耗量减少采用集约高效的发展方式”，是对①的肯后，肯后得不到确定性的结论，不能推出，排除；D项：该项翻译为“减少速度缓慢对经济发展造成负面影响”，是对②的否前，否前得不到确定性的结论，不能推出，排除。⇒ 正确答案为A。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2023年吉林省公务员录用考试《行测》题（网友回忆版） 第21 题", "qid": 5509738, "level": "中等", "stem": "土地荒漠化是人为因素和自然因素综合作用的结果，想要在土地退化的地区恢复人与自然和谐共生的状态，必须提高土地荒漠化防治的科学性。一方面，把握积极作为和有所不为的平衡，即一手抓人工治理，一手抓自然修复；另一方面，提高防治精细化水平。如果同时做到上述两个方面，土地荒漠化防治的科学性自然得到了提高。\n由此可推出：", "options": ["只有在土地退化的地区恢复人与自然和谐共生的状态，才能提高土地荒漠化防治的科学性", "如果土地荒漠化防治的科学性得到了提高，则说明在土地退化的地区恢复了人与自然和谐共生的状态", "如果土地荒漠化防治的科学性没有得到提高，则说明或者没有把握积极作为和有所不为的平衡，或者没有提升防治精细化水平", "如果土地荒漠化防治的科学性得到了提高，则说明把握积极作为和有所不为的平衡，以及提升防治精细化水平一定同时得以实现"], "answer": ["C"], "explain": "第一步：翻译题干。①在土地退化的地区恢复人与自然和谐共生的状态提高土地荒漠化防治的科学性；②把握积极作为和有所不为的平衡 且 提高防治精细化水平提高土地荒漠化防治的科学性。第二步：逐一分析选项。A项：该项翻译为“提高土地荒漠化防治的科学性在土地退化的地区恢复人与自然和谐共生的状态”，是对①的肯后，肯后得不到确定性结论，无法推出，排除；B项：该项翻译为“提高土地荒漠化防治的科学性在土地退化的地区恢复了人与自然和谐共生的状态”，是对①的肯后，肯后得不到确定性结论，无法推出，排除；C项：该项翻译为“提高土地荒漠化防治的科学性把握积极作为和有所不为的平衡 或 提升防治精细化水平”，是对②的否后，否后必否前，可以推出，当选；D项：该项翻译为“提高土地荒漠化防治的科学性把握积极作为和有所不为的平衡 且 提升防治精细化水平”，是对②的肯后，肯后得不到确定性结论，无法推出，排除。⇒ 正确答案为C。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2016年江西省法检系统招录考试《行测》题 第26 题", "qid": 2255761, "level": "中等", "stem": "“不忘初心，方得始终”的意思是只有一直坚持最初的理想，不断努力，才能够最后获得成功，实现目标。论断必定正确的是：", "options": ["小李坚持理想，不断努力，但没有成功", "小李最后实现目标，因为他一直孜孜不倦地追求自己的理想", "小李坚持理想，不断努力，所以最后获得成功", "小李没有成功，因为他没有坚持理想和不断努力"], "answer": ["D"], "explain": "第一步：翻译题干。成功坚持理想且不断努力第二步：逐一分析选项。A项：翻译为坚持理想且不断努力成功，是对题干的肯后，肯后得不到必然性结论，排除；B项：翻译为坚持理想成功，是对题干的肯后，肯后得不到必然性结论，排除；C项：翻译为坚持理想且不断努力成功，是对题干的肯后，肯后得不到必然性结论，排除；D项：翻译为（坚持理想且不断努力）成功，是对题干的否后，否后必否前，当选。⇒ 正确答案为D。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2025年重庆市定向选调优秀大学生到基层工作考试《行测》题 第24 题", "qid": 18650027, "level": "中等", "stem": "推动特殊教育优质融合发展，需要多方位推进。特殊教育的发展必须以教育整体改革发展为前提，并且必将有利于教育整体改革发展。推动特殊教育优质融合发展，还需要持续扩优提质。资源是发展的保障，质量是永恒的话题，这两点对于当前特殊教育的发展都是必不可少、缺一不可的。\n由此可以推出的是（    ）。", "options": ["有了资源和质量必将推动当前特殊教育的发展", "没有教育整体改革发展就不会有特殊教育的发展", "有了多方位推进就能推动特殊教育优质融合发展", "没有持续扩优提质也能推动特殊教育优质融合发展"], "answer": ["B"], "explain": "第一步：翻译题干。（1）推动特殊教育优质融合发展多方位推进；（2）特殊教育的发展教育整体改革发展；（3）特殊教育的发展有利于教育整体改革发展；（4）推动特殊教育优质融合发展持续扩优提质；（5）特殊教育的发展资源 且 质量。第二步：逐一分析选项。A项：翻译为“资源 且 质量特殊教育的发展”，是对条件（5）的肯后，肯后推不出确定性结论，无法推出，排除；B项：翻译为“特殊教育的发展教育整体改革发展”，是对条件（2）的肯前，肯前必肯后，可以推出，当选；C项：翻译为“多方位推进推动特殊教育优质融合发展”，是对条件（1）的肯后，肯后推不出确定性结论，无法推出，排除；D项：翻译为“持续扩优提质 且 推动特殊教育优质融合发展”，与条件（4）矛盾，无法推出，排除。⇒ 正确答案为B。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "江西省2018年市县两级法院、检察院统一考录公务员笔试《行测》题（网友回忆版） 第26 题", "qid": 2256369, "level": "中等", "stem": "孟子曰：“离娄之明，公输子之巧，不以规矩，不能成方圆；师旷之聪，不以六律，不能正五音；尧舜之道，不以仁政，不能平治天下。今有仁心仁闻而民不被其泽，不可法于后世者，不行先王之道也。故曰，徒善不足以为政，徒法不能以自行。”\n下列选项与“不以规矩，不能成方圆”的逻辑推论不符的是：", "options": ["只有遵循合理的道德行为规范，社会才能正常运转", "若遵循合理的道德行为规范，社会则能正常运转", "除非遵循合理的道德行为规范，否则社会不能正常运转", "凡是能够正常运转的社会，它都应该是遵循合理的道德行为规范的"], "answer": ["B"], "explain": "第一步：翻译题干。成方圆规矩。第二步：逐一分析选项。A项：翻译为正常运转遵循合理的道德行为规范。正常运转的含义与成方圆相近，遵循合理的道德规范的含义与规矩相近，所以A项和题干逻辑推论相符，排除；B项：翻译为遵循合理的道德行为规范正常运转。遵循合理的道德规范的含义与规矩相近，正常运转的含义与成方圆相近，所以B项和题干逻辑推论不相符，当选；C项：翻译为正常运转遵循合理的道德行为规范。正常运转的含义与成方圆相近，遵循合理的道德规范的含义与规矩相近，所以C项和题干逻辑推论相符，排除；D项：翻译为正常运转遵循合理的道德行为规范。正常运转的含义与成方圆相近，遵循合理的道德规范的含义与规矩相近，所以D项和题干逻辑推论相符，排除。本题为选非题，⇒ 正确答案为B。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2021年北京市公务员录用考试《行测》题（区级及以上卷）（网友回忆版） 第11 题", "qid": 2742258, "level": "中等", "stem": "某文化用品市场正在推进市场的信息化和电子化，市场主管部门建议市场里的商家可以使用电子付款系统或者使用自动贩卖机。\n如果市场里的每家商户都落实了这一建议，那么以下哪项一定为真？\nⅠ.市场里的一些商户使用了自动贩卖机。\nⅡ.如果一家商店既没有使用自动贩卖机，也没有使用电子付款系统，那么这家商店一定不在该市场里。\nⅢ.如果一家文具店既使用了自动贩卖机，也使用了电子付款系统，这家商店一定在该市场里。", "options": ["只有Ⅰ", "只有Ⅱ", "只有Ⅰ和Ⅱ", "只有Ⅱ和Ⅲ"], "answer": ["B"], "explain": "第一步：翻译题干。市场里的商家使用电子付款系统 或 使用自动贩卖机。第二步：逐一分析结论。Ⅰ.题干中箭头后方是“或”关系，则无法确定市场里的商家使用的是电子付款系统还是自动贩卖机，因此无法推出市场里的一些商户使用了自动贩卖机，排除A、C两项；Ⅱ.翻译为：商店没有使用自动贩卖机且没有使用电子付款系统商店一定不在该市场里，是对题干翻译的否后，根据否后必否前，可以推出该商店一定不在该市场里，可以推出；Ⅲ.翻译为：一家文具店使用了自动贩卖机且使用了电子付款系统这家商店在该市场里，是对题干翻译的肯后，肯后得不到确定性结论，无法推出这家商店一定在该市场里，排除D项。⇒ 正确答案为B。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2022年国家公务员录用考试《行测》题（副省级网友回忆版） 第33 题", "qid": 4639345, "level": "中等", "stem": "一颗恒星足够大且经过超新星爆发，才会坍缩为一颗中子星并伴随磁场增强。在这些中子星中，只有拥有强大磁场和高自转速度才能成为磁星。一般认为，磁星的磁场是在恒星变成中子星的首十秒透过炽热内核物质的对流所产生的，只有在对流现象发生期间拥有高自转速度（周期约10毫秒左右），产生的电流才会传遍整颗天体。\n由此可以推出：", "options": ["能演变成磁星的星体一定是中子星", "拥有高自转速度的中子星会产生强大磁场", "如果不经历超新星爆发，大质量恒星是不会成为中子星的", "只要中子星的内核物质产生强烈对流，就会在整个星体内出现电流"], "answer": ["C"], "explain": "第一步：翻译题干。（1）坍缩为一颗中子星足够大 且 经过超新星爆发；（2）成为磁星的中子星中子星拥有强大磁场 且 高自转速度；（3）产生的电流传遍整颗天体在对流现象发生期间 且 拥有高自转速度。第二步：逐一分析选项。A项：选项翻译为“变成磁星中子星”，二者不存在逻辑关系，无法推出，排除；B项：选项指出拥有高自转速度的中子星会产生强大磁场，根据（2）可知，中子星拥有强大磁场和高自转速度为且关系的两项，二者不存在逻辑关系，无法推出，排除；C项：选项翻译为“经历超新星爆发成为中子星”，是对（1）且关系其中一项的否定，且关系其中一项为假，整个关系为假，因此是对（1）的否后，否后必否前，可以推出，当选；D项：选项翻译为“中子星的内核物质产生强烈对流在整个星体内出现电流”，“强烈对流”肯定了（3）后面“且关系”中的一项，另一项无法判断，无法推出星体内是否有电流，排除。⇒ 正确答案为C。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "河南省2019年统一考试录用司法所公务员《行测》题（网友回忆版） 第33 题", "qid": 2452862, "level": "中等", "stem": "许多成功的演员都是表演系专业毕业的，也有很多演员是草根出身，通过一些机遇走上了演艺之路，但没有一个不努力提升自己演艺水平的演员能够获得成功。\n如果以上陈述为真，那么以下选项一定为真的是：", "options": ["没有草根出身的演员会不努力提升自己演艺水平", "所有不成功的演员都不努力去提升自己演艺水平", "演员越努力提升自己演艺水平就越可能获得成功", "表演系专业毕业的演员会努力提升自己演艺水平"], "answer": ["C"], "explain": "第一步：翻译题干。①有的成功演员表演系毕业；②有的演员草根；③成功努力提升自己演艺水平；①换位后和③可得：④有的表演系毕业成功演员努力提升自己演艺水平。第二步：逐一分析选项。A项：翻译为草根努力提升自己演艺水平，草根与努力之间不构成推出关系，排除；B项：翻译为—成功努力提升自己演艺水平，对③的否前，否前推不出必然性结论，排除；C项：翻译为越努力提升自己演艺水平越可能成功，是对③的肯后，肯后得不到必然性结论，选项中说的是可能获得成功，当选；D项：翻译为表演系专业努力提升自己演艺水平，根据①③只能推出有的表演系毕业努力提升自己演艺水平，无法推出所有，排除。⇒ 正确答案为C。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第37 题", "qid": 13648296, "level": "中等", "stem": "在超大特大城市积极稳步实施城中村改造是改善民生、扩大内需、推动城市高质量发展的一项重要举措。落实这一重要举措的一个必备的战略思路是要坚持稳中求进、积极稳妥，优先对群众需求迫切、城市安全和社会治理隐患多的城中村进行改造。\n由此可以推出：", "options": ["如果不在超大特大城市积极稳步实施城中村改造，就不能改善民生、扩大内需、推动城市高质量发展", "如果要改善民生、扩大内需、推动城市高质量发展，就要在超大特大城市积极稳步实施城中村改造", "如果坚持稳中求进、积极稳妥，优先对群众需求迫切、城市安全和社会治理隐患多的城中村进行改造，就能够在超大特大城市积极稳步实施城中村改造", "如果不坚持稳中求进、积极稳妥，优先对群众需求迫切、城市安全和社会治理隐患多的城中村进行改造，就不能在超大特大城市积极稳步实施城中村改造"], "answer": ["D"], "explain": "第一步：翻译题干。落实这一重要举措（在超大特大城市积极稳步实施城中村改造）坚持稳中求进、积极稳妥，优先对群众需求迫切、城市安全和社会治理隐患多的城中村进行改造。第二步：逐一分析选项。A项：翻译为：在超大特大城市积极稳步实施城中村改造改善民生、扩大内需、推动城市高质量发展，二者不存在逻辑关系，无法推出，排除；B项：翻译为：改善民生、扩大内需、推动城市高质量发展在超大特大城市积极稳步实施城中村改造，二者不存在逻辑关系，无法推出，排除；C项：翻译为：坚持稳中求进、积极稳妥，优先对群众需求迫切、城市安全和社会治理隐患多的城中村进行改造在超大特大城市积极稳步实施城中村改造，是对题干推出关系的肯后，肯后得不到确定结论，无法推出，排除；D项：翻译为：坚持稳中求进、积极稳妥，优先对群众需求迫切、城市安全和社会治理隐患多的城中村进行改造在超大特大城市积极稳步实施城中村改造，是对题干推出关系的否后，否后必否前，可以推出，当选。⇒ 正确答案为D。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2020年黑龙江省公务员录用考试《行测》试题（网友回忆版） 第28 题", "qid": 2616032, "level": "中等", "stem": "在市场竞争十分激烈的时候，一个企业要是不激流勇进，创造出富有竞争力的产品，也不适时撤退、主动割爱，放弃没有前景的市场，那么这个企业最后一定会陷入危机之中。\n如果以上论断为真，下列说法正确的是（    ）。", "options": ["某企业未能创造出富有竞争力的产品，最后一定会惨遭淘汰", "某企业紧要关头急流勇退，转向其它市场，就可以避免危机", "某企业放弃已显颓势的产业，转向新产品的开发，它可能不会被淘汰", "某企业研发出了富有竞争力的产品，它最后一定不会陷入危机之中"], "answer": ["C"], "explain": "第一步：翻译题干。-（激流勇进，创造出富有竞争力的产品）且-（适时撤退，主动割爱，放弃没有前景的市场）→陷入危机第二步：逐一分析选项。A项：翻译为-创造出有市场竞争力的产品→淘汰，“-创造出有市场竞争力的产品”是对题干翻译前件“且”关系一部分的肯定，据此无法判断整个“且”关系的真假，进而无法得出确定性结论，不能推出，排除；B项：翻译为“急流勇退，转向其他市场陷入危机”，“急流勇退，转向其他市场”即“适时撤退、主动割爱，放弃没有前景的市场”，是对题干翻译前件“且”关系的一部分的否定，否前不能得到确定性结论，不能推出，排除；C项：翻译为放弃已显颓势的产业→可能不会被淘汰，放弃已显颓势的产业是否定题干翻译前件“且关系”的一部分，否前不能得到确定性结论，但是C选项后面说的是可能不会被淘汰，是一种可能性的表述，可以推出，当选；D项：翻译为富有竞争力的产品→-陷入危机，是否定题干翻译前件“且关系”的一部分，否前不能得到确定性结论，不能推出，排除。⇒ 正确答案为C。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2020年上海市公务员录用考试《行测》题（B类）（网友回忆版） 第30 题", "qid": 2453046, "level": "中等", "stem": "所有真正关心老百姓利益的领导干部，都会受到大家的尊敬；而真正关心老百姓利益的领导干部都特别重视如何解决住房、看病、教育和养老等民生问题。因此，那些不重视如何解决老百姓民生问题的领导干部，都不会受到大家的尊敬。\n为保证上述论证成立，必须增加下列      项作为前提。", "options": ["随着老龄化社会的来临，老百姓面临的看病、养老等问题越来越突出", "所有重视如何解决老百姓民生问题的领导干部，都会受到大家的尊敬", "住房、看病、教育和养老等民生问题，是事关老百姓利益的最为突出的问题", "所有受到大家尊敬的领导干部，都是真正关心老百姓利益的领导干部"], "answer": ["D"], "explain": "第一步：找出论点和论据。论点：不重视民生问题的领导干部不尊敬（根据逆否可以推出：尊敬重视民生问题的领导干部）；论据：关心老百姓利益的领导干部尊敬；关心老百姓利益的领导干部重视民生问题。第二步：逐一分析选项。A项：论点说的是不重视如何解决老百姓民生问题的领导干部，都不会受到大家的尊敬，该项说的是看病、养老等问题越来越突出，话题不一致，无法加强，排除；B项：简单翻译为重视解决民生问题的领导干部尊敬，将其补充到论据之上，无法得到论点，因此无法加强，排除；C项：论点说的是不重视如何解决老百姓民生问题的领导干部，都不会受到大家的尊敬，该项说的是民生问题是最为突出的话题，话题不一致，无法加强，排除；D项：简单翻译为：尊敬关心老百姓利益的领导干部，将其补充到论据，可以得到：尊敬关心老百姓利益的领导干部重视民生问题，因此可以得到论点，可以加强，当选。⇒ 正确答案为D。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2017年湖北省选调生行测题（精选） 第17 题", "qid": 2261881, "level": "中等", "stem": "“城归”，有学者解释为，从农村出去打工、经商的农民，或从农村走出的读书人、退役士兵等，经过多年在城市打拼，累积了经验，获得技术和资金。如今又重回乡村生产生活。据国务院公布的数据，目前“城归”已超过450万人。在新农村建设中，需要大量人才和资金支持，而“城归”群体的迅速壮大是提供人才和资金的必要条件。\n据此可以推出：", "options": ["如果没有“城归”群体的发展壮大，那么就不能实现新农村建设目标", "只要有人才和资金支持，就能实现新农村建设目标", "一旦有人才就会有资金", "倘若有资金支持，就能实现新农村建设目标"], "answer": ["A"], "explain": "第一步：翻译题干。①新农村建设人才和资金；②人才和资金“城归”群体壮大；将①和②串联得出：③新农村建设人才和资金“城归”群体壮大。第二步：逐一分析选项。A项：翻译为“城归”群体壮大新农村建设，是对③的否后推否前，可以推出，当选；B项：翻译为人才和资金新农村建设，是对①的肯后，肯后无必然结论，无法推出，排除；C项：翻译为人才资金，题干未提及人才和资金之间的关系，无关项，无法推出，排除；D项：翻译为资金新农村建设，新农村建设不仅需要资金还需要人才，无法推出，排除。⇒ 正确答案为A。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}, {"type": "翻译推理", "from": "2019年重庆市选调优秀大学生到基层工作考试《行测》题 第12 题", "qid": 2670602, "level": "中等", "stem": "来自公安机关的资料显示，娱乐圈中有人赌博，高级知识分子中也有人赌博。赌博中有些人是女性，而抢劫犯中有些人是赌博者。\n由此可以推出：", "options": ["高级知识分子中也有抢劫犯", "抢劫犯中赌博者占了大多数", "有些抢劫犯可能是女性", "有些抢劫犯不是女性"], "answer": ["C"], "explain": "第一步：翻译题干。①有的娱乐圈的人赌博②有的高级知识分子赌博③有的赌博者女性④有的抢劫犯赌博第二步：逐一分析选项。A项：翻译为“有的高级知识分子抢劫犯”，根据条件②和条件④，两个“有的”推不出必然结论，不能推出，排除；B项：由条件④可知有些抢劫犯也是赌博者，但是赌博者是否占了大多数，无法判断，排除；C项：由条件③和条件④可以推出：有些抢劫犯是赌博者，而赌博者中有女性，所以有些抢劫犯中可能有女性，可以推出，当选；D项：由条件③和条件④可以推出C项中“有些抢劫犯可能是女性”的结论，但不能得到确定结论抢劫犯不是女性，无法推出，排除。⇒ 正确答案为C。", "point": "考的是把日常语言翻译成逻辑符号（→、且、或、非）再做推理。核心是四组翻译规则：「如果…那么…」前推后、「只有…才…」后推前（B→A）、「除非…否则…」否前推后，以及逆否等价（A→B 等价于 ¬B→¬A）。", "method": "第一步先把题干“翻译”成箭头式（A→B）；第二步看选项哪个与题干同一个推理形式。肯前必肯后、否后必否前；肯后、否前都不必然成立。", "tip": "最容易错的是把「只有A才B」当成 A→B（实际是 B→A），以及误用「否前推否后」。"}]}, {"set": 102, "cat": "真假推理", "title": "专项挑战 · 真假推理", "date": "", "session": "", "items": [{"type": "真假推理", "from": "2016年河南省公务员录用考试《行测》题 第32 题", "qid": 2033398, "level": "中等", "stem": "甲乙丙丁四个人高考前对英语成绩进行预测。当时，甲说：“我再怎么努力也考不了90分。”乙说：“不知道自己能考多少分，但是我知道丙能考90分。”丙说：“不会考到80分。”丁说：“乙不会考的比60分还低。”事实上只有一个人猜对了。\n以下哪个结论不支持乙猜对了？", "options": ["丁考得比甲好", "乙考得不是最差的", "甲和丙考得一样高", "丙和丁考得一样高"], "answer": ["B"], "explain": "本题为真假推理题。经过老师们的一致教研，粉笔认为本题题干信息不充分，根据题干已知信息并结合选项推不出答案，而丙的话按照正常语句构成来说少了一个主语。发现题干信息均未涉及丁，而选项中反复出现丁，故认为此处丙的话可能是“丁不会考到80分”，将此条件补齐进行推理可知：\n第一步：分析题干。\n列出题干已知信息：\n甲：甲＜90分，乙：丙≥90分，丙：丁＜80分，丁：乙≥60分。\n提问方式中明确指出不支持乙猜对，那么，我们根据乙说的为真话，又只有一个人猜对，可知其余人都说假话，可以得出如下结论：甲≥90分、丙≥90分、丁≥80分、乙＜60分。\n第二步：分析选项。\n本题采用代入法，假设A、C、D三项为真代入题干，均与题干无冲突。代入B项，乙考的不是最差的，与上一步推出的结论乙＜60分，是四个人中成绩最差的有冲突，因此B项不能支持乙的猜测。\n本题为选非题，⇒ 正确答案为B。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2020年上海市公务员录用考试《行测》题（A类）（网友回忆版） 第31 题", "qid": 2453060, "level": "中等", "stem": "某大学哲学系三年级本科生参加了一次国家英语六级考试。关于考试成绩，四位同学做出了如下猜测：\n甲：所有同学都及格了。\n乙：小张没有及格。\n丙：肯定不会全部同学都及格。\n丁：也不会所有同学都不及格。\n如果只有一位同学猜错了，则下列                    项为真。", "options": ["甲猜错了，小张及格了", "甲猜错了，小张没有及格", "乙猜错了，小张及格了", "丙猜错了，小张及格了"], "answer": ["B"], "explain": "本题属于真假推理题。\n第一步：找出题干矛盾关系。\n甲说“所有同学都及格”和丙说“肯定不会全部同学都及格”（即有的同学不会及格）是矛盾关系，必有一真必有一假。\n第二步：看其余。\n已知只有一句是假话，则乙和丁说的是真话，即小张没有及格，也不会所有同学都不及格（即有的同学会及格），因此甲说的是假话，丙说的是真话。\n⇒ 正确答案为B。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2016年天津选调生选拔考试 综合知识试卷（精选） 第8 题", "qid": 2255651, "level": "中等", "stem": "某法院对某刑事案件有以下四种说法：①有证据表明赵刚没有作案；②作案者或者是赵刚，或者是王强，或者是李明；③也有证据表明王强没有作案；④电视画面显示，案发时李明在远离案发现场的一个足球赛的观众席上。\n下列各项是对四种说法的不同描述，其中正确的一项是：", "options": ["从上述说法中可以推出，只有一个人作案", "上述说法中至少有一个是假的", "从这几种说法中可以推出，表明王强没有作案的证据是假的", "李明肯定不在该足球赛的观众席上"], "answer": ["B"], "explain": "第一步：找出题干矛盾关系。\n本题突破口为“三个人都有证据表明没有作案”与“他们至少有一个人作案”之间的矛盾关系。\n第二步：判断真假。\n由“三个人都有证据表明没有作案”与“他们至少有一个人作案”之间的矛盾关系可知二者必有一假，故上述说法至少有一个是假的，但不能具体判断谁真谁假。\n⇒ 正确答案为B。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2021年黑龙江公务员录用考试《行测》题（网友回忆版） 第32 题", "qid": 3522385, "level": "中等", "stem": "某科学家在一个宇宙科学网站上刊载了一项成果，该成果宣称找到了地球生命来自彗星的“证据”，引发了广泛关注。他声称在一块坠落到斯里兰卡的陨石里找到了微观硅藻化石，该石头有着疏松多孔的结构，密度比在地球上找到的所有东西都低。他推断这是一颗彗星的一部分，并指出样本中找到的微观硅藻化石与恐龙时代留存下来的化石中的微观有机体类似，从而为彗星胚种论提供了强有力的证据。\n以下哪项如果为真，最能反驳该科学家的观点？", "options": ["发表该成果的网站缺乏可信性，所载论文良莠不齐，有些曾沦为笑柄", "该科学家是彗星胚种论的狂热支持者，曾宣称SARS和流感来自彗星", "该成果配图中被标示成“丝状硅藻”的东西实际上只是硅藻细胞断片", "该成果根本无法证明该石头是碳质球粒陨石，甚至难以确定其是陨石"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：地球生命来自彗星。\n论据：一块坠落到斯里兰卡的陨石里找到了微观硅藻化石，该石头有着疏松多孔的结构，密度比在地球上找到的所有东西都低。他推断这是一颗彗星的一部分，并指出样本中找到的微观硅藻化石与恐龙时代留存下来的化石中的微观有机体类似，从而为彗星胚种论提供了强有力的证据。\n本题的论据说的是陨石找到的微观硅藻化石与恐龙时代留存下来的化石中的微观有机体类似，同时该研究还推断该陨石是一颗彗星的一部分，即说明该陨石（彗星的一部分）与生命有关系，而论点说的是地球生命来自彗星，所以，二者讨论话题一致，削弱可以考虑削弱论点，也可以考虑削弱论据。\n第二步：逐一分析选项。\nA项：该成果的网站缺乏可信性，所载论文良莠不齐，代表不了这次实验成果的可靠性，属于无关项，排除；\nB项：只是说该科学家是彗星胚种论的狂热支持者，支持者说的话无法辨别真假，同时即便SARS和流感来自彗星，也无法判断生命是否来源于彗星，不明确选项，排除；\nC项：选项是说配图中的东西本质是硅藻细胞断片，一定程度上质疑了题干研究成果的可信性，可能削弱论据，保留；\nD项：该成果根本无法证明该石头是陨石，直接质疑了论据的研究成果，直接削弱论据，保留。\n对比C、D两项：C项为可能削弱论据，D项为直接削弱论据，D项当选。\n⇒ 正确答案为D。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2018年国家公务员录用考试《行测》题（副省级网友回忆版） 第34 题", "qid": 2133744, "level": "中等", "stem": "某省游泳队进行了为期一个月的高原集训，集训最后一日所有队员进行了一次队内测试，几位教练预测了一下队员的成绩：\n张教练说：这次集训时间短，没人会达标。\n孙教练说：有队员会达标。\n王教练说：省运会冠军或国家队队员可达标。\n测试结束后，只有一位教练的预测是正确的。\n由此可以推出：", "options": ["没有人达标", "全队都达标了", "省运会冠军达标", "国家队队员未达标"], "answer": ["D"], "explain": "本题属于真假推理题。第一步：找出题干矛盾命题。张教练说“没有人会达标”和孙教练说“有队员会达标”是矛盾关系，必有一真必有一假。已知只有一句是对的，说明真话一定在张教练和孙教练中，所以王教练说的是假的。第二步：看其余。已知王教练说的是假的，可知：（省冠军达标或国家队队员达标），即“省冠军达标 且 国家队队员达标”，D项可以推出。⇒ 正确答案为D。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2018年浙江省公务员录用考试《行测》题（B类）（网友回忆版） 第35 题", "qid": 2144605, "level": "中等", "stem": "有专家指出，判断名优白酒的真伪有简单的办法：价格低得离谱的名优白酒肯定都是假的，凡是打着某一名优白酒旗号在外公开销售的定制酒都是假的。而消费者如果从正规渠道购买，就能买到真的好酒，这些渠道一是正规超市或大卖场；二是名优白酒品牌授权的旗舰店；三是名优白酒企业的官网电商。\n以下哪项如果为真，最能质疑专家的观点？", "options": ["有些大卖场对进场商品的把关并不严格，销售假冒伪劣商品的情况时有发生", "现今网络诈骗案件屡屡发生，假冒名优白酒企业官网销售的白酒肯定是假的", "某电视促销节目主持人声称，他们销售的名优白酒虽然只有市价的一半，但绝对不是假酒", "某名优白酒企业生产的定制酒只用于企业内部接待，但它是真的"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：判断名优白酒的真伪有简单的办法：价格低得离谱的名优白酒肯定是假的，凡是打着某一名优白酒旗号在外公开销售的定制酒都是假的。在正规渠道购买的就能买到真的好酒。\n论据：无。\n第二步：逐一分析选项。\nA项：指出有些大卖场对进场商品把关不严格，会出现假冒伪劣商品，那就是在正规渠道购买的名优白酒，也会出现假酒的情况，否定论点，当选；\nB项：指出假冒名优白酒企业官网销售的白酒是假酒，但没办法证明专家说的三种判断白酒真假的方法是不对的，不能削弱，排除；\nC项：某电视促销节目主持人声称，价格低于市价一半的名优白酒绝对不是假酒，只是主持人说是真酒，但是并不能保证这种酒的真假，属于不明确选项，排除； \nD项：指出某名优白酒企业生产的定制酒只用于企业内部接待，但它是真的，表明这种酒并没有在外公开销售，说明打着该企业旗号在外公开销售的定制酒都是假的，有加强的力度，排除。\n⇒ 正确答案为A。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2017年422联考《行测》题（江西卷） 第27 题", "qid": 2050858, "level": "中等", "stem": "有四个人，他们分别是小偷、强盗、法官、警察。第一个人说：“第二个人不是小偷。”第二个人说：“第三个是警察。”第三个人说：“第四个人不是法官。”第四个人说：“我不是警察，而且除我之外只有警察会说实话。”如果第四个人说的是实话，那么以下说法正确的是：", "options": ["第一个人是警察，第二个人是小偷", "第一个人是小偷，第四个人是法官", "第三个人是警察，第四个人是法官", "第二个人是强盗，第三个人是小偷"], "answer": ["D"], "explain": "分析题干已知信息。\n①第二个人不是小偷\n②第三个人是警察\n③第四个人不是法官\n④第四个人不是警察，且只有第四个人和警察说真话\n通过④可知①②③中，只有一个人说真话，故本题为真假推理题。因为三句话中，没有矛盾和反对关系，故可考虑代入排除。\nA项：第一个人是警察，代入题干，即“第二个人不是小偷”为真，那么与A“第二个人是小偷”矛盾，排除；\nB项：第一个人是小偷，那么他说的话是假话，代入题干，“第二个人不是小偷”为假，即第二个人是小偷，而小偷只有一个，不能两人都是小偷，排除；\nC项：第三个人是警察，那么第三个人说真话，而题干第二个人说：“第三个是警察。”即两个人说了真话，排除。\n⇒ 正确答案为D。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2018年421联考《行测》题（山东卷）（网友回忆版） 第34 题", "qid": 2187877, "level": "中等", "stem": "美国幼儿教育注重培养孩子的“批判式思维”，其中重要一点就是区分事实陈述与观点陈述，事实陈述是可被验证的，有“真假”，无“好坏”；观点陈述则多为主观体验，受价值观等影响。\n以下广告语中，兼顾事实与观点的是：", "options": ["金牌巧克力，唤醒你的甜蜜回忆", "量牌65英寸无边框全玻璃超薄电视，给您海一般视野", "喜酒沁人心脾，滴滴难舍，回味无穷", "水平对置发动机，左右对称全时四驱，成就捷牌汽车"], "answer": ["B"], "explain": "逐一分析选项。\nA项：唤醒你的甜蜜回忆是主观体验，属于观点陈述，该广告只体现了观点陈述而无事实陈述，排除；\nB项：65英寸无边框全玻璃，是可被验证的，有“真假”，无“好坏”，属于事实陈述。海一般视野是主观体验，属于观点陈述，该广告语兼顾事实与观点，当选；\nC项：沁人心脾，滴滴难舍，回味无穷是主观体验，属于观点陈述，该广告只体现了观点陈述而无事实陈述，排除；\nD项：水平对置发动机，左右对称全时四驱是可被验证的，有“真假”，无“好坏”，属于事实陈述，该广告只体现了事实陈述而无观点陈述，排除。\n⇒ 正确答案为B。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2018年广西选调生考试《行测》试题（网友回忆版） 第34 题", "qid": 2184701, "level": "中等", "stem": "课间休息时，一位同学帮老师擦了黑板，老师回到教室后询问是谁擦的黑板。\n他问了四位同学，得到以下回答：\n（1）或者班长擦了，或者学习委员擦了\n（2）如果纪律委员没擦，那么班长也没擦\n（3）如果卫生委员没擦，那么班长擦了\n（4）班长和学习委员都没擦\n实际上，四位同学的回答中只有一句是假的。据此可以推出擦黑板的是：", "options": ["纪律委员", "学习委员", "卫生委员", "班长"], "answer": ["C"], "explain": "第一步：整理题干信息。（1）班长 或 学习委员；（2）纪律委员班长；（3） 卫生委员班长；（4）班长 且 学习委员。第二步：分析题干。由提问可知，本题为真假推理，先找矛盾关系，（1）和（4）为矛盾关系，必有一真一假，结合提问，只有一句为假，说明（2）（3）为真，对条件（2）进行逆否等价可知：班长纪律委员，假设班长擦了黑板，则纪律委员也擦了黑板，不符合题干中的只有一位同学擦了黑板，故班长没有擦黑板，对（3）进行逆否等价，可知：班长卫生委员，故班长没有擦黑板，可以推出卫生委员擦了黑板。⇒ 正确答案为C。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2016年重庆市公务员录用考试《行测》题（下半年） 第25 题", "qid": 2015396, "level": "中等", "stem": "当小张、小李、小王和小贾在公园里打棒球时，田老师家的玻璃恰好被人打破了。田老师怀疑这与他们有关，于是分别找他们询问，四人的回答如下：\n小张说：“您家的玻璃不是我们打破的，和我们压根无关。”\n小王说：“小李和小贾中，至少有一个肯定是无辜的。”\n小李说：“我只能告诉您，打破您家玻璃的人肯定在我们之中。”\n小贾说：“田老师，您千万要相信我啊，真的不是我打破的。”\n如果四个人中，有两个人说的是假话，两个人说的是真话，可以推出：", "options": ["说真话的是小张和小王", "说真话的是小贾和小张", "说真话的是小贾和小李", "说真话的是小李和小王"], "answer": ["D"], "explain": "第一步：真假推理题，找矛盾。\n小张：四人中不存在打破玻璃者；\n小王：不是小李或不是小贾；\n小李：四人中存在打破玻璃；\n小贾：不是小贾。\n第二步：分析题干。\n小张和小李两个人说的矛盾了，矛盾必有一真一假。条件中“两个人说假话，两个人说真话”，即共有两真两假，那么剩下的小王和小贾中也必有一真一假。这时候，我们可以用假设法，假设小贾说的是真话，即不是小贾打破的，那小王说的也就是真话了，因为或命题有一项为真即为真，这很明显不符合题意。所以小贾说的是假话，即玻璃是小贾打破的，也间接证明了小张说了假话。综上所述：小张说了假话；小王说了真话；小李说了真话；小贾说了假话。\n⇒ 正确答案为D。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2021年北京市公务员录用考试《行测》题（区级及以上卷）（网友回忆版） 第9 题", "qid": 2742272, "level": "中等", "stem": "某高校准备选派2021年第一批出国访学的中青年学者，选派分为高级访问学者以及青年骨干教师两类，选派的条件分别为：前者要求是教师或者科研人员，年龄在40周岁以上且具有高级职称；后者要求是具有博士学位的近三年新进校的教师。\n关于该校选派出的2021年第一批出国访学人员，以下哪项判断一定为真？", "options": ["选派为青年骨干教师的都不具有高级职称", "没有博士学位的都在40周岁以上", "科研人员都不是近三年新进校的", "具有博士学位的都是近三年新进校的"], "answer": ["B"], "explain": "第一步：翻译题干。①2021年第一批出国访学人员分为两种：高级访问学者与青年骨干教师；②高级访问学者（教师或者科研人员）且40周岁以上且具有高级职称；③青年骨干教师具有博士学位且是近三年新进校的教师。第二步：逐一分析选项。A项：该项中的“青年骨干教师”是对条件③的肯前，由于肯前可以推出肯后，可以得出“具有博士学位且是近三年新进校的教师”为真，但据此无法判断其是否具有高级职称，故无法确定该选项的真假性，排除；B项：该项中的“没有博士学位”是对条件③的否后，由于否后可以推出否前，可以得出“青年骨干教师”为假。再结合条件①可知，“高级访问学者”为真，则是对条件②的肯前，由于肯前可以推出肯后，则可以得出“（教师或者科研人员）且40周岁以上且具有高级职称”为真，进而可知“40周岁以上”为真，即该选项一定为真，当选；C项：根据该项中的“科研人员”无法判断条件②后面部分的真假性，所以无法据此进行进一步的推理，故无法确定该选项的真假性，排除；D项：根据该项中的“具有博士学位”无法判断条件③后面部分的真假性，所以无法据此进行进一步的推理，故无法确定该选项的真假性，排除。⇒ 正确答案为B。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2019年北京市公务员录用考试《行测》题（网友回忆版） 第14 题", "qid": 2274573, "level": "中等", "stem": "某次足球比赛前，甲、乙、丙、丁四位运动员猜测他们的上场情况。\n甲：我们四人都不会上场；\n乙：我们中有人会上场；\n丙：乙和丁至少有一人上场；\n丁：我会上场。\n四人中有两人猜测为真两人猜测为假，则以下哪项断定成立？", "options": ["猜测为真的是乙和丙", "猜测为真的是甲和丁", "猜测为真的是甲和丙", "猜测为真的是乙和丁"], "answer": ["A"], "explain": "本题属于真假推理题。\n第一步：找出题干矛盾命题。\n甲：我们四人都不会上场；\n乙：我们中有人会上场；\n丙：乙或丁；\n丁：丁。\n甲说“我们四人都不会上场”和乙说“我们中有人会上场”是矛盾关系，则必有一真必有一假。已知四人中有两人猜测为真两人猜测为假，说明丙和丁的猜测也必然是一真一假。\n第二步：看其余。\n假设丁的猜测为真，则丁会上场，而“丁”为“乙或丁”的其中一项，此时丙的猜测也一定为真，那么丙、丁的猜测均为真，与题干要求的一真一假矛盾，故丁的猜测一定为假，即丁不会上场，则丙的猜测为真，说明乙或丁会上场，既然丁不会上场，那么上场的为乙，也就是说四个人中有人会上场，则乙的猜测为真，甲的猜测为假，即猜测为真的是乙和丙。\n⇒ 正确答案为A。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2026年黑龙江公务员录用考试《行测》题（网友回忆版） 第6 题", "qid": 15833767, "level": "中等", "stem": "动词可以分为以下几类：断言类，表示说话人对某事做出一定程度上的表态，对话语所表达的命题内容做出真假判断；指令类，表示说话人不同程度地指使听话人做某事；承诺类，指说话人对未来的行为做出不同程度的承诺；表达类，指说话人在表达话语命题内容的同时所表达的某种心理状态；宣告类，指话语所表达的命题内容与客观现实之间的一致。\n根据上述内容，下列选项表述错误的是：", "options": ["“否认”是断言类，“要求”是指令类", "“保证”是承诺类，“宣布”是宣告类", "“请求”“敦促”“命令”都是指令类", "“道歉”“夸耀”“通知”都是表达类"], "answer": ["D"], "explain": "第一步：找出定义关键词。\n断言类：“表态”、“真假判断”；\n指令类：“指使”；\n承诺类：“对未来的行为做出承诺”；\n表达类：“表达某种心理状态”；\n宣告类：“话语所表达的命题内容与客观现实之间的一致”。\n第二步：逐一分析选项。\nA项：“否认”指不承认，符合“表态”、“真假判断”，属于断言类；“要求”指提出具体愿望或条件，希望得到满足或实现，符合“指使”，属于指令类，说法正确，排除；\nB项：“保证”指确保既定的要求和标准，不打折扣，符合“对未来的行为做出承诺”，属于承诺类；“宣布”指向听众宣读某个决定、信息，符合“话语所表达的命题内容与客观现实之间的一致”，属于宣告类，说法正确，排除；\nC项：“请求”指提出要求，希望得到满足，“敦促”指催促，“命令”指上级对下级有所指示，均符合“指使”，均属于指令类，说法正确，排除；\nD项：“道歉”指表示歉意，特指认错，“夸耀”指向他人显示自己的长处或优势，均符合“表达某种心理状态”，均属于表达类；“通知”指把事项告诉人知道，符合“话语所表达的命题内容与客观现实之间的一致”，属于宣告类，并非表达类，说法错误，当选。\n本题为选非题，⇒ 正确答案为D。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "2016年广州市公务员录用考试《行测》题 第12 题", "qid": 2062738, "level": "中等", "stem": "女性不都爱化妆，但男性都不爱化妆。如果上述第一个判断为真，第二个判断为假，则以下哪项据此可以确定真假？\n（1）女性都爱化妆，有的男性也爱化妆\n（2）有的女性爱化妆，有的男性不爱化妆\n（3）女性都不爱化妆，男性都爱化妆", "options": ["只有（1）", "只有（2）", "只有（3）", "（1）（3）"], "answer": ["A"], "explain": "第一步：分析题干信息。\n“女性不都爱化妆”即“有的女性不爱化妆”，这是真判断；\n“男性都不爱化妆”是假判断，则它的矛盾项“有的男性爱化妆”是真判断。\n因此题干结论就是：\n①有的女性不爱化妆；\n②有的男性爱化妆。\n第二步：逐一分析3个结论。\n（1）女性都爱化妆与条件①有的女性不爱化妆相矛盾，故该说法一定为假，而根据结论②可知，有的男性也爱化妆为真，故该项可以确定真假；\n（2）\n有的女性爱化妆，有的男性不爱化妆，可能为真，也可能为假，根据已知结论无法确定真假；\n\n（3）女性都不爱化妆，男性都爱化妆，可能为真，也可能为假，根据已知结论无法确定真假。\n能确定真假的只有（1）。\n⇒ 正确答案为A。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}, {"type": "真假推理", "from": "天津市选调2018年应届优秀大学毕业生到基层培养锻炼考试题（网友回忆版） 第6 题", "qid": 2166019, "level": "中等", "stem": "有一天，甲、乙、丙、丁、戊五个外国商人坐在一起聊天。甲说：“我们五人中有一个人在撒谎”；乙说：“我们五人中有两个人在撒谎”；丙说：“我们五人中有三个人在撒谎”；丁说：“我们五人中有四个人在撒谎”；戊说：“我们五个人全都在撒谎”。由此，可推出他们之中说真话的是：", "options": ["甲和戊", "丁", "乙和丙", "戊"], "answer": ["B"], "explain": "第一步：翻译题干信息。\n甲：有一个人在撒谎，其他四个说的是真话；\n乙：有两个人在撒谎，其他三个说的是真话；\n丙：有三个人在撒谎，其他两个说的是真话；\n丁：有四个人在撒谎，有一个说的是真话；\n戊：五个人都在撒谎。\n甲乙丙丁戊说的话真假存在相关性，假设甲说的是真话，那么乙丙丁戊说的都是假话，与甲矛盾，排除A项；假设乙说的是真话，那么甲丙丁戊说的都是假话，与乙矛盾，排除C项；假设戊说的是真话，那么甲乙丙丁说的都是假话，与戊矛盾，排除D项；只有当丁说的是真话，那么甲乙丙戊说的都是假话，与丁相符，B项当选。\n⇒ 正确答案为B。", "point": "考矛盾关系与推出关系：题干给若干断定、告知有几真几假，用「矛盾命题必一真一假」先锁定范围。", "method": "先找矛盾命题（如「所有是」vs「有些不是」、「A且B」vs「非A或非B」）；矛盾之外的信息定真假；再逐一代入验证。", "tip": "别忘了「只有一真」这类硬条件；矛盾关系的两个命题必然一真一假，其余依此推断，不要一上来就假设。"}]}, {"set": 103, "cat": "分析推理", "title": "专项挑战 · 分析推理", "date": "", "session": "", "items": [{"type": "分析推理", "from": "2019年福建省选调生考试《行政职业能力测验》 第28 题", "qid": 4705741, "level": "中等", "stem": "汉斯、亚瑟、古力三个学生来自美国、德国和意大利，其中一个学法律，一个学经济，一个学管理。\n已知：\n1.汉斯不是学法律的，亚瑟不是学管理的；\n2.学法律的不是来自德国；\n3.学管理的来自美国；\n4.亚瑟不是来自意大利。\n以上条件成立，以下哪项为真？", "options": ["汉斯学管理，亚瑟学经济，古力学法律", "汉斯学经济，亚瑟学管理，古力学法律", "汉斯学法律，亚瑟学经济，古力学管理", "汉斯学管理，亚瑟学法律，古力学经济"], "answer": ["A"], "explain": "第一步：分析题干条件。\n（1）汉斯不学法律，亚瑟不学管理；\n（2）学法律的不来自德国；\n（3）学管理的来自美国；\n（4）亚瑟不来自意大利。\n第二步：根据题干条件进行推理。\n选项信息充分，优先考虑排除法。\n根据条件（1）可知，汉斯不学法律，亚瑟不学管理，排除B、C两项；\n结合条件（1）（3）可知，亚瑟不来自美国，再结合条件（4）可知，亚瑟也不来自意大利，故亚瑟只能来自德国；然后结合条件（2）可知，来自德国的不学法律，因此，亚瑟不学法律，排除D项。\n⇒ 正确答案为A。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2020年国家公务员录用考试《行测》题（副省级网友回忆版） 第33 题", "qid": 2448587, "level": "中等", "stem": "小张这个夏天如果去新疆，就要游吐鲁番和喀纳斯，否则就不去；只有与小李同游，小张才会游吐鲁番或天池；如果与小李同游，小张一定要与小李做约定；如果小张与小李做约定，则小李这个夏天一定要有时间。遗憾的是，这个夏天小李单位来了一项紧急任务，相关人员一律不得请假，小李也不例外。\n由此可以推出：", "options": ["小张这个夏天未去新疆", "小张这个夏天去游喀纳斯", "小张这个夏天去游天池", "小张这个夏天去游吐鲁番"], "answer": ["A"], "explain": "第一步：翻译题干。① 去新疆游吐鲁番和喀纳斯；② 游吐鲁番或天池与李同游；③ 与李同游小张与小李做约定；④ 小张与小李做约定小李这个夏天有时间；⑤ 小李没时间；②③④可以递推出⑥：游吐鲁番或天池与李同游小张与小李做约定小李这个夏天有时间。第二步：根据题干条件进行推理。从确定信息条件⑤入手，小李没时间是对条件⑥的否后，否后必否前，可以得出：—（游吐鲁番或天池），根据德摩根定律，等价于—吐鲁番且—天池，—吐鲁番是对条件①的否后，否后必否前，可以得出：张没去新疆，对应A项。⇒ 正确答案为A。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2021年四川下半年公务员录用考试《行测》试题（网友回忆版） 第30 题", "qid": 4658595, "level": "中等", "stem": "某物业公司为住户提供24小时全年无休的门卫保安服务，门卫保安每日分为白班和夜班，每班均有一名保安人员上班。三名保安人员每3天排一轮班，已知本轮排班中，甲、乙、丙的上班情况如下：①没有人连续上一整天班；②甲、乙、丙在本轮排班中都有一个整天在休息；③没有人被全部安排白班或夜班；④为确保员工充足休息，刚排完夜班之后不能接着排白班。则在本轮排班中，以下情况可能发生的是：", "options": ["某住户已经连续两天看到乙上班", "某住户连续两天都看到甲和乙在上班", "某住户前天白天出门和今天夜晚回家时都看见丙在上班", "某住户已经连续三天晚上下班回家都没有看见丙在上班"], "answer": ["A"], "explain": "第一步：分析题干条件。本轮排班中，上班情况如下：①没有人连续上一整天班；②每人都有一个整天在休息；③没有人被全部安排白班或夜班；④刚排完夜班之后不能接着排白班。第二步：根据题干条件进行推理。提问为“可能”，优先考虑代入法。代入A项，该项说连续两天看到乙上班，假设第一天白班排乙，根据条件③可知，第二天夜班可以排乙。若第一天夜班排给丙，则根据条件①②③和④，可得出如下表所示的情况：此时满足题干所有条件，可能为真，当选；代入B项，若满足连续两天看到甲和乙均上班，则第一天和第二天只能都排给甲和乙，那么第三天只能都排给丙，与条件①不符，不可能为真，排除；代入C项，若满足前天白天出门和今天夜晚回家时都能看到丙上班，则第一天的白班和第三天的夜班都必须排给丙，根据条件①④可知，无论第一天夜班排甲还是乙，此人第二天只能上夜班，此时就会有人全都被排夜班，与条件③不符，不可能为真，排除；代入D项，若满足连续三天没有看到丙上夜班，则三天的夜班均只能排甲和乙，而丙在这一轮排班中只能上白班，与条件③不符，不可能为真，排除。⇒ 正确答案为A。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2017年上海市行政执法类考试《行测》试题（网友回忆版） 第23 题", "qid": 5690297, "level": "中等", "stem": "蔡骏建立了“茶香江左”微信群，被陈灵拉进该群并通过该群和蔡骏建立了互信联系的人都是茶叶经销商，陈灵的一个客户黎阳通过该群和蔡骏建立了互信联系，但是陈灵的客户都不是茶叶经销商。\n根据以上信息，可以得出下列        项。", "options": ["蔡骏是茶叶经销商", "陈灵不曾将黎阳拉进“茶香江左”微信群", "黎阳和陈灵通过“茶香江左”微信群建立了互信联系", "陈灵通过“茶香江左”微信群和蔡骏建立了互信联系"], "answer": ["B"], "explain": "第一步：分析题干条件。（1）被陈灵拉进该群 且 通过该群和蔡骏建立了互信联系茶叶经销商；（2）黎阳是陈灵的客户；（3）黎阳通过该群和蔡骏建立了互信联系；（4）陈灵的客户茶叶经销商。第二步：根据题干条件进行推理。根据条件（2）和条件（4）可知，黎阳不是茶叶经销商，根据条件（1）否后必否前可知，被陈灵拉进该群 或 通过该群和蔡骏建立了互信联系，再根据条件（3）可知，黎阳通过该群和蔡骏建立了互信联系，则否一推一可推出：黎阳没有被陈灵拉进该群，B项当选。A、C、D三项均无法推出，排除。⇒ 正确答案为B。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2022年湖北省选调生招录考试综合知识和行政职业能力测验试卷（网友回忆版） 第16 题", "qid": 4808817, "level": "中等", "stem": "进入21世纪后，中国经济总量逐步上升到世界第二位。由此，有人认为：“加入WTO对一个国家的经济增长具有明显的加速作用。”\n以下各项如果为真，最能质疑上述观点的是：", "options": ["中国进入经济高增长轨道与加入WTO几乎同时发生", "中国的大国基础结构对经济增长具有十分重要作用", "印度、巴西在加入WTO前后经济增速无明显变化", "中国有较低劳动成本和较高技能结合的竞争优势"], "answer": ["C"], "explain": "第一步：找出论点和论据。\n论点：加入WTO对一个国家的经济增长具有明显的加速作用。\n论据：进入21世纪后，中国经济总量逐步上升到世界第二位。\n论点讨论的是加入WTO可以让国家经济增长加快，论据讨论的是进入21世纪后，中国经济总量逐步上升，论点论据讨论的话题一致，削弱优先考虑削弱论点，即说明加入WTO无法让国家经济增长加快。（注：中国于2001年12月11日加入WTO，故题干中“进入21世纪”包括加入WTO前。）\n第二步：逐一分析选项。\nA项：说明中国进入经济高增长轨道与加入WTO几乎同时发生，但几乎同时发生并不能明确加入WTO是否能加速经济增长，为不明确项，无法削弱，排除；\nB项：说明中国的大国基础结构对经济增长有重要作用，但与论点讨论的加入WTO是否能加速经济增长无关，为无关项，无法削弱，排除；\nC项：说明印度和巴西加入WTO后经济增速没变，举例说明加入WTO并不能让一个国家的经济增长加速，举例削弱论点，可以削弱，当选；\nD项：说明中国具有竞争优势，但是否有竞争优势与论点讨论的加入WTO是否能加速经济增长无关，为无关项，无法削弱，排除。\n⇒ 正确答案为C。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2025年四川省考-选调公务员录用考试《行测》试题（网友回忆版） 第30 题", "qid": 10297447, "level": "中等", "stem": "老高、老胡、老杨、老陈围坐在一张方桌前，相对而坐的两人均是夫妻。这4人穿的上衣颜色各不相同，有蓝色、黄色、粉色和红色。其中，坐在老杨左手边的老陈上衣不是蓝色，穿蓝色上衣的人右手边是老胡，穿黄色上衣的人坐在老杨对面，穿黄色上衣的不是老胡。\n由此可以推出：", "options": ["穿红色和穿粉色上衣的是夫妻", "老陈和穿黄色上衣的相对而坐", "穿红色上衣的人是老胡", "老高和老杨相邻而坐"], "answer": ["A"], "explain": "第一步：分析题干条件。（1）老高、老胡、老杨、老陈围坐在一张方桌前，相对而坐的两人均是夫妻；（2）4人上衣颜色各不相同，有蓝色、黄色、粉色和红色；（3）坐在老杨左手边的老陈上衣不是蓝色；（4）穿蓝色上衣的人右手边是老胡；（5）穿黄色上衣的人坐在老杨对面，穿黄色上衣的不是老胡。第二步：根据题干条件进行推理。条件（3）和（5）都涉及关于老杨的确定信息，故可从老杨入手推理。由条件（3）可知，老陈坐在老杨的左手边，再结合条件（5）可知，坐在老杨对面的人既不是老陈、也不是老胡，则只能是老高，进而可知坐在老杨右手边的人是老胡，如下图所示（只表示四人之间的左右手关系，不明确四人东南西北的位置）：根据条件（4）和上图可知，老杨的右手边是老胡，所以老杨穿蓝色上衣；根据条件（5）和上图可知，老高坐在老杨对面，所以老高穿黄色上衣。老陈和老胡谁穿粉色谁穿红色根据题干条件无法推出，如下图所示：由条件（1）和上图可知，A项正确。⇒ 正确答案为A。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2024年深圳市考公务员录用考试《行测》试题（网友回忆版） 第11 题", "qid": 10718178, "level": "中等", "stem": "某景区漂流项目的工作人员用扩音器循环播放注意须知：“除非年龄在55岁以下，并且穿上救生衣，否则不能漂流。”同时，出于安全考虑，有高血压或心脏病的游客不能漂流。老王穿上了救生衣，但最后工作人员没允许他去漂流。\n由此可推知，以下选项一定为真的是（    ）。", "options": ["如果老王年满55岁，则他一定有高血压或心脏病", "老王有高血压或心脏病", "老王年满55岁，且有高血压或心脏病", "老王要么年满55岁，要么有高血压或心脏病"], "answer": ["D"], "explain": "第一步：翻译题干。①能漂流55岁以下 且 穿上救生衣②有高血压 或 心脏病漂流第二步：根据题干条件进行推理。如果老王年满55岁，是对条件①的否后，根据“否后必否前”可以得出老王不能漂流；如果老王有高血压或心脏病，是对条件②的肯前，根据“肯前必肯后”可以得出老王不能漂流。综上，只要满足其一，那么老王就不能漂流。⇒ 正确答案为D。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2024年江苏名校优生选调素质测试（网友回忆版） 第11 题", "qid": 19591537, "level": "中等", "stem": "农忙时节，甲、乙、丙、丁、戊五人帮助收割庄稼，一周之内，五人均只休息一天，周六周日不休息，恰好五天均有人休息。并且已知：\n（1）丙周四休息\n（2）甲和丁休息日相邻\n（3）甲乙丁三人共同连续工作四天\n问以下哪项正确？", "options": ["甲周一休息", "乙周二休息", "丁周三休息", "戊周五休息"], "answer": ["D"], "explain": "第一步：分析题干条件。（1）丙周四休息；（2）甲和丁休息日相邻；（3）甲乙丁三人共同连续工作四天；（4）一周之内，五人均只休息一天，周六周日不休息，恰好五天均有人休息。第二步：根据题干条件进行推理。根据条件（1）（4）可知，丙周四休息且周六周日无人休息，此时休息日只剩下周一、周二、周三和周五4天（如下表所示）。结合条件（3）可知，甲乙丁3人共同连续工作4天，说明7天中有连续4天甲乙丁3人都不能休息（即连续4天3人均不出现在休息表内），再结合条件（4）可知，每人都要有一天休息，故甲乙丁3人要在周一、周二、周三、周五中选3天休息，且保证有连续4天这三人都不休息。此时只有甲乙丁在周一、周二和周三休息才能保证3人在周四至周日这4天连续工作（即连续4天不出现在休息表内），此时无法确定甲乙丁休息日的具体顺序，只需保证甲丁在周一周二或周二周三休息即可满足条件（2），结合条件（1）（4）可知，此时剩下的戊只能在周五休息，对应D项。⇒ 正确答案为D。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2017年422联考《行测》题（江西卷） 第30 题", "qid": 2050890, "level": "中等", "stem": "所有刑事侦查专业的大四学生毕业后都当警察了，有的警察是党员，刑事侦查专业的大四学生都不是警察，由此可以推出的是：", "options": ["有的党员是刑事侦查专业的大学毕业生", "有的党员不是刑事侦查专业的大四学生", "有的刑事侦查专业的大四学生是党员", "有的刑事侦查专业的大四学生不是党员"], "answer": ["B"], "explain": "第一步：翻译题干。①刑事侦查专业的大四学生毕业后警察；②有的警察党员；③刑事侦查专业的大四学生-警察。第二步：逐一分析选项。A项：翻译为有的党员刑事侦查专业的大学毕业生，从题干条件②有的警察党员，无法推出其是否是刑事侦查专业的大学毕业生，无法推出，排除；B项：翻译为有的党员-刑事侦查专业的大四学生，由题干条件②有的警察是党员，可知有的党员是警察，根据条件③刑事侦查专业的大四学生-警察，可以推出有的党员-刑事侦查专业的大四学生，可以推出，当选；C项：翻译为有的刑事侦查专业的大四学生党员，根据条件③刑事侦查专业的大四学生-警察，无法得知其是否是党员，无法推出，排除；D项：翻译为有的刑事侦查专业的大四学生-党员，根据条件③刑事侦查专业的大四学生-警察，无法得知其是否是党员，无法推出，排除。⇒ 正确答案为B。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2022年深圳市考公务员录用考试《行测》试题（网友回忆版） 第12 题", "qid": 4651890, "level": "中等", "stem": "某赛事的参赛者信息如下：\n（1）3人是围棋选手；\n（2）4人来自广东；\n（3）2人来自深圳；\n（4）5人是女生；\n（5）来自深圳的参赛者都是男生。\n若以上信息涉及了所有参赛者，则该赛事的参赛者（    ）。", "options": ["最多14人，最少8人", "最多14人，最少7人", "最多12人，最少7人", "最多12人，最少8人"], "answer": ["C"], "explain": "第一步：分析题干条件。\n（1）3人是围棋选手；\n（2）4人来自广东；\n（3）2人来自深圳；\n（4）5人是女生；\n（5）来自深圳的参赛者都是男生。\n第二步：根据题干条件进行推理。\n已知题干信息涉及了所有参赛者，且来自广东的4人当中包括来自深圳的2人。当条件（1）、（2）、（4）涉及的参赛者互不重复时，参赛人数最多，此时有3+4+5共计12位参赛者； 结合条件（3）、（5）可知，来自深圳的2人是男生，再结合条件（4）可知，至少有2+5共计7人参赛，此时条件（1）、（2）和条件（3）、（4）、（5）涉及的参赛者恰好重复（例如某参赛者可以既是女生又是围棋选手），参赛人数最少。\n⇒ 正确答案为C。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2024年广东省公务员录用考试《行测》题（网友回忆版） 第13 题", "qid": 16593254, "level": "中等", "stem": "甲、乙、丙、丁4人每人都会演奏钢琴、小提琴、二胡和古筝4种乐器中的2种，且每种乐器都有2人会演奏。已知：\n①甲不会演奏钢琴；\n②丁不会演奏古筝；\n③丙不会演奏钢琴和小提琴；\n④乙和丙会演奏的乐器中有且仅有1种相同。\n由此可以推出（    ）。", "options": ["甲会演奏小提琴", "甲不会演奏二胡", "乙会演奏古筝", "甲和丁会演奏的乐器完全不同"], "answer": ["A"], "explain": "第一步：分析题干条件。①甲不会演奏钢琴；②丁不会演奏古筝；③丙不会演奏钢琴和小提琴；④乙和丙会演奏的乐器中有且仅有1种相同；⑤每人都会演奏钢琴、小提琴、二胡和古筝中的2种，每种乐器都有2人会演奏。第二步：根据题干条件进行推理。根据条件①③可知，甲、丙不会演奏钢琴，结合条件⑤“每种乐器都有2人会演奏”可知，乙、丁会演奏钢琴。根据条件③⑤可知，丙会演奏二胡、古筝，结合条件④“乙和丙会演奏的乐器中有且仅有1种相同”可知，乙会演奏二胡或古筝，又已知乙会演奏钢琴，且每人只会演奏2种乐器，那么乙一定不会演奏小提琴，结合条件③“丙不会演奏钢琴和小提琴”，那么甲、丁会演奏小提琴。确定可推出的信息如下表所示：⇒ 正确答案为A。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2023年重庆市选调优秀大学生到基层工作考试《行测》题 第29 题", "qid": 13871466, "level": "中等", "stem": "三个小朋友坐成一排做游戏，坐在男生左边的两个人中至少有一个人是女生，坐在女生右边的两个人中恰好有一个也是女生，手持气球小朋友的右边两个人中至少有一个人手持鲜花，手持鲜花小朋友的左边两人中也恰好有一个手持鲜花。\n根据以上叙述，可以推出三位小朋友分别是（    ）。", "options": ["手持气球的女生、手持气球的女生，手持鲜花的男生", "手持气球的女生、手持鲜花的男生，手持鲜花的男生", "手持气球的女生、手持鲜花的女生、手持鲜花的男生", "手持鲜花的女生、手持鲜花的女生、手持气球的男生"], "answer": ["C"], "explain": "第一步：分析题干条件。（1）坐在男生左边的两个人中至少有一个人是女生；（2）坐在女生右边的两个人中恰好有一个也是女生；（3）手持气球小朋友的右边两个人中至少有一个人手持鲜花；（4）手持鲜花小朋友的左边两人中也恰好有一个手持鲜花。第二步：根据题干条件进行推理。根据条件（1）和（2）可以推出，右边的小朋友为男生，左边和中间的小朋友为女生，排除B项；根据条件（3）和（4）可以推出，左边的小朋友手持气球，中间和右边的小朋友手持鲜花，排除A、D两项，C项当选。⇒ 正确答案为C。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2023年浙江省公务员录用考试《行测》题（C类）（网友回忆版） 第27 题", "qid": 5430353, "level": "中等", "stem": "关于小张、小李书法学习的情况，有如下判断：（1）如果小张学习魏碑，那么小李学习汉隶；（2）小张既没有学习秦篆，也没有学习魏碑；（3）小张或者学习秦篆，或者学习魏碑。结果发现，上述判断有两项是错误的。\n根据以上信息，可以得出以下哪项结论？", "options": ["小张学习魏碑，小李学习汉隶", "小张没有学习魏碑，小李学习汉隶", "小张学习魏碑，小李没有学习汉隶", "小张没有学习魏碑，小李没有学习汉隶"], "answer": ["C"], "explain": "第一步：找出题干矛盾命题。（1）小张学习魏碑小李学习汉隶；（2）小张学习秦篆 且 小张学习魏碑；（3）小张学习秦篆 或 小张学习魏碑。分析题干条件，（2）与（3）为矛盾关系，必有一真一假。第二步：根据题干条件进行推理。根据题干条件可知，3个条件中有2个是错误的，故（1）一定错误，因此其矛盾命题“小张学习魏碑 且 小李学习汉隶”一定为真，即小张学习魏碑，小李没有学习汉隶，对应C项。⇒ 正确答案为C。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2025年浙江省公务员录用考试《行测》题（C类）（网友回忆版） 第27 题", "qid": 10297302, "level": "中等", "stem": "小贾、小易、小白、小单4人参加夏令营，每人先从雏鹰行动营、精英成长营、综合素质营3类中选择1类，再从该类别中选择1-3个夏令营。已知：\n（1）小贾和小单选择的夏令营种类和数量均不同；\n（2）有1人选择了1个夏令营，有2人选择了2个夏令营；\n（3）小白选择综合素质营中的3个夏令营；\n（4）每类夏令营都有人选择，小易和小单选择了雏鹰行动营。\n由此可以推出：", "options": ["小易选择了2个夏令营", "小贾和小白选择了同一类夏令营", "有人与小白选择了相同的类别或数量", "小单选择了雏鹰行动营中的2个夏令营"], "answer": ["A"], "explain": "第一步：分析题干条件。\n（1）小贾和小单选择的夏令营种类和数量均不同；\n（2）有1人选择了1个夏令营，有2人选择了2个夏令营；\n（3）小白选择综合素质营中的3个夏令营；\n（4）每类夏令营都有人选择，小易和小单选择了雏鹰行动营；\n（5）每人先从3类夏令营中选择1类，再从该类别中选择1-3个夏令营。\n第二步：根据题干条件进行推理。\n根据条件（2）（3）可知，小白选择了3个夏令营，则小贾、小易、小单中有1人选择了1个夏令营，有2人选择了2个夏令营；结合条件（1）可知，小贾和小单中有1人选择了1个夏令营，有1人选择了2个夏令营，则小易只能选择2个夏令营，对应A项。\n⇒ 正确答案为A。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}, {"type": "分析推理", "from": "2023年青海省公务员录用考试《行测》题（网友回忆版） 第35 题", "qid": 5509579, "level": "中等", "stem": "周末，甲、乙、丙、丁在商场偶遇，一阵寒暄过后得知，他们几人在商场要么只看了电影，要么只购了物：\n①丁有购物\n②如果甲有购物，那么乙去看了电影\n③如果丁没有购物，那么丙去看了电影\n④甲和乙都有购物\n如果以上陈述只有一项为真，可以推出：", "options": ["乙有购物，甲看了电影", "丙有购物，乙看了电影", "丙有购物，丁看了电影", "甲和乙都看了电影"], "answer": ["C"], "explain": "第一步：找出题干矛盾命题。①丁购物；②甲购物乙电影；③丁购物丙电影；④甲购物 且 乙购物。根据题干条件甲、乙、丙、丁四人要么只看电影，要么只购物可知，条件④等价于“甲购物 且 乙电影”，与条件②为矛盾关系，必有一真一假。第二步：根据题干条件进行推理。根据题干条件可知，四个条件中只有一项为真，故条件①和条件③为假；根据条件①和条件③为假可知，其矛盾命题“丁购物”和“丁购物 且 丙电影”为真，因此丁看了电影，丙有购物，对应C项。⇒ 正确答案为C。", "point": "考把零散条件组织成有序对应（谁是谁、谁坐哪儿），常用列表法、假设法、代入排除法。", "method": "信息确定的先排定；信息不确定（真假不明）就用假设法或直接代入选项验证。", "tip": "选项给出完整对应时，优先「代入排除」，比正向硬推快得多。"}]}, {"set": 104, "cat": "加强论证", "title": "专项挑战 · 加强论证", "date": "", "session": "", "items": [{"type": "加强论证", "from": "2022年深圳市考公务员录用考试《行测》试题（网友回忆版） 第13 题", "qid": 4651892, "level": "中等", "stem": "三孩政策引发民众热议。有人认为，三孩政策将加剧性别不公，影响女性的职业发展，加重家庭经济负担，因此夫妻应当合休产假，男女共担育儿义务，这一建议如果被采纳实施，将有效降低生育对女性职业发展的负面影响，提高女性生育意愿，推动三孩政策落实。\n以下选项如果为真，最能支持上述结论的是：", "options": ["某集团的人力资源负责人表示，考虑到产假因素，业内招聘普遍倾向于录用男性", "已有国家正在实行类似的夫妻合休全薪产假政策，受到该国国民的大力支持", "夫妻合休产假可以优化家庭教育结构，有利于儿童身心健康成长", "调查显示，不考虑生育三孩的女性中，大多数对生育三孩将影响其职业发展有较大顾虑"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：夫妻合休产假的建议如果被采纳实施，将有效降低生育对女性职业发展的负面影响，提高女性生育意愿，推动三孩政策落实。\n论据：三孩政策将加剧性别不公，影响女性的职业发展，加重家庭经济负担。\n本题论点讨论的是实施合休产假后三孩政策不会影响女性职业发展，论据讨论的是三孩政策对女性职业发展的影响，论点论据话题一致。所以加强可以优先考虑补充论据，可以举例子，也可以解释原因。\n第二步：逐一分析选项。\nA项：指出目前女性产假是影响女性录用情况的因素，而论点讨论的是夫妻合休产假这一政策与女性职业发展以及三孩政策落实间的关系，话题不一致，无法加强，排除；\nB项：指出其他国家实行夫妻合休全薪产假政策后受到了国民的支持，而论点讨论的是该政策在我国实施可能会带来的积极影响，主体不一致，无法加强，排除；\nC项：指出夫妻合休产假政策有利于儿童身心健康成长，而论点讨论的是该政策与女性职业发展以及三孩政策落实间的关系，话题不一致，无法加强，排除；\nD项：指出有些女性因生育三孩确实会影响其职业发展而选择不生三孩，而该政策的实施可以降低生育为女性职业发展带来的负面影响，因此该项解释了这项政策如何降低女性职业发展负面影响，进而推动三孩政策落实，可以加强，当选。\n⇒ 正确答案为D。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2025年青海省公务员录用考试《行测》题（网友回忆版） 第22 题", "qid": 13504470, "level": "中等", "stem": "在长期的进化过程中，蝙蝠（狐蝠除外）获得了对夜间飞行十分有利的回声定位能力，可以将喉咙和鼻子处生成的超声波以短脉冲形式发射到周围，并且能用耳朵接收反射回的声波，以此来确定自身到物体的距离、物体所在方向以及物体形状等。一般来说，蝙蝠的寿命比其他相同体型的哺乳类动物要长3.5倍，有科学家推测，蝙蝠的夜行性和飞行能力可以降低它们被捕食的风险，这可能对其寿命的延长有所帮助。\n以下哪项如果为真，最能加强上述科学家的推测：", "options": ["在夜间飞行时，如果蝙蝠的耳朵被堵住，它们就无法顺利地躲避障碍物", "倒挂姿势不仅有助于蝙蝠起飞，还可以使它们睡在洞穴顶部等隐蔽场所", "黑暗中蝙蝠能够正确识别周围环境，这有助于它们成功躲避天敌的侵扰", "蝙蝠体内抑制病毒感染和增殖的蛋白质较多，即使感染病毒也不会发病"], "answer": ["C"], "explain": "第一步：找出论点和论据。\n论点：蝙蝠的夜行性和飞行能力可以降低它们被捕食的风险，这可能对其寿命的延长有所帮助。\n论据：在长期的进化过程中，蝙蝠（狐蝠除外）获得了对夜间飞行十分有利的回声定位能力，可以将喉咙和鼻子处生成的超声波以短脉冲形式发射到周围，并且能用耳朵接收反射回的声波，以此来确定自身到物体的距离、物体所在方向以及物体形状等。一般来说，蝙蝠的寿命比其他相同体型的哺乳类动物要长3.5倍。\n本题论点和论据均在讨论蝙蝠的夜行性、飞行能力及其寿命，论点和论据话题一致，加强优先考虑补充论据。\n第二步：逐一分析选项。\nA项：选项说的是在夜间飞行时，如果蝙蝠的耳朵被堵住，它们就无法顺利地躲避障碍物，说明蝙蝠的耳朵对其顺利地躲避障碍物的重要性，是在重复论据，与论点讨论的蝙蝠的夜行性和飞行能力是否可以降低它们被捕食的风险，以及这是否可能对其寿命的延长有所帮助无关，无关项，无法加强，排除；\nB项：选项说的是倒挂姿势不仅有助于蝙蝠起飞，还可以使它们睡在洞穴顶部等隐蔽场所，是在讨论蝙蝠倒挂姿势的好处，但论点讨论的是蝙蝠的夜行性和飞行能力是否可以降低它们被捕食的风险，以及这是否可能对其寿命的延长有所帮助，话题不一致，无法加强，排除；\nC项：选项说的是黑暗中蝙蝠能够正确识别周围环境，这有助于它们成功躲避天敌的侵扰，是在解释为什么蝙蝠的夜行性可以降低它们被捕食的风险，补充论据，可以加强，当选；\nD项：选项说的是蝙蝠体内抑制病毒感染和增殖的蛋白质较多，即使感染病毒也不会发病，但论点讨论的是蝙蝠的夜行性和飞行能力是否可以降低它们被捕食的风险，以及这是否可能对其寿命的延长有所帮助，话题不一致，无法加强，排除。\n⇒ 正确答案为C。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2024年山西省县级纪委监委公务员录用考试《行测》题（网友回忆版） 第32 题", "qid": 17097277, "level": "中等", "stem": "电池及充电速度对于电动汽车至关重要。据报道，研究人员开发出一种突破性技术，将电动汽车电池的充电时间缩短为仅10分钟。有专家认为，这将大大加速电动汽车取代内燃汽车的进程。\n以下哪项如果为真，最能支持上述结论？", "options": ["现阶段电动汽车的续航里程问题，是其进一步普及的重大障碍", "限制或禁止销售内燃汽车，使得对电动汽车的需求比以往任何时候都要大", "新技术可以让电池变得更小、充电更快、成本更低，还可大大减少驾驶员的里程焦虑", "新技术使用一种新的电池结构，添加的超薄镍箔可自我调节电池的温度和反应性"], "answer": ["C"], "explain": "第一步：找出论点和论据。\n论点：这将大大加速电动汽车取代内燃汽车的进程。\n论据：研究人员开发出一种突破性技术，将电动汽车电池的充电时间缩短为仅10分钟。 \n本题论点讨论的是一种突破性技术可以加速电动汽车取代内燃汽车的进程，论据讨论的是该技术将电动汽车电池的充电时间缩短为仅10分钟，二者讨论的均是电动汽车及其充电技术在汽车行业的发展，话题一致，加强优先考虑补充论据。\n第二步：逐一分析选项。\nA项：该项指出现阶段电动汽车进一步普及的重大障碍是续航里程问题，但无法说明解决这一问题就可以加速电动汽车取代内燃汽车的进程，话题不一致，无法加强，排除；\nB项：该项指出通过限制或禁止销售内燃汽车，可以大大提高电动汽车的需求，而论点讨论的是新技术能否加速电动汽车取代内燃汽车的进程，话题不一致，无法加强，排除；\nC项：该项指出新技术可以让电池变得更小、充电更快、成本更低，还可减少驾驶员的里程焦虑，以上优势会让电动汽车更具竞争力，可以解释为什么该技术可以加速电动汽车取代内燃汽车的进程，解释原因，可以加强，当选；\nD项：该项指出新技术的优点，但并未提及这些优点能否加快电动汽车取代内燃汽车的进程，话题不一致，无法加强，排除。\n⇒ 正确答案为C。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2021年湖北省选调生招录考试综合知识和行政职业能力测验试卷（网友回忆版） 第12 题", "qid": 5518416, "level": "中等", "stem": "政府债券是投资者寻求收益和有效对冲股市普遍下跌的工具。国内外媒体报道说，2020年，中国政府债券表现出避风港的效用，在美国、欧洲和日本等主要经济体政府债券收益率普遍下跌的情况下，外国投资人持有的中国债券规模激增至创纪录的1.79万亿元人民币。媒体预测，未来3年内，中国政府债券都是外国投资人首选的投资产品。\n以下各项如果为真，最能支持媒体预测的是？", "options": ["中国人民银行不会跟随发达国家央行全面实施货币宽松政策以贬值货币", "中国央行不是像其他国家那样压低收益率，而是限制抛售并提供稳定性", "中国债券相对其他主权债券处于有利地位，可以提供正收益和风险对冲", "国外许多有影响的投资者2020年都卖了其他政府债券，转投中国债券"], "answer": ["C"], "explain": "第一步：找出论点和论据。\n论点：未来3年内，中国政府债券都是外国投资人首选的投资产品。\n论据：2020年，中国政府债券表现出避风港的效用，在美国、欧洲和日本等主要经济体政府债券收益率普遍下跌的情况下，外国投资人持有的中国债券规模激增至创纪录的1.79万亿元人民币。\n论点和论据都在讨论“外国投资人选择投资中国政府债券”，二者话题一致，加强优先考虑补充论据。\n第二步：逐一分析选项。\nA项：该项指出中国人民银行不会全面实施货币宽松政策以贬值货币，即中国政府债券的收益率不会走低，但投资者投资政府债券的主要目的是寻求收益和有效对冲股市风险，该项无法确定未来3年内中国政府债券是否为外国投资人首选的投资产品，无法加强，排除；\nB项：该项指出中国央行不会压低收益率，而会限制抛售并提供稳定性，但投资者投资政府债券的主要目的是寻求收益和有效对冲股市风险，该项无法确定未来3年内中国政府债券是否为外国投资人首选的投资产品，无法加强，排除；\nC项：该项指出中国债券相对其他主权债券处于有利地位，可以提供正收益和风险对冲，这符合投资者投资政府债券的主要目的，并且中国债券比其他主权债券有优势，解释了未来3年内中国政府债券是外国投资人首选投资产品的原因，补充论据，可以加强，当选；\nD项：该项指出国外许多有影响的投资者2020年都卖了其他政府债券，转投中国债券，说的是2020年的情况，无法说明未来3年内中国政府债券是否会成为外国投资人首选的投资产品，无法加强，排除。\n⇒ 正确答案为C。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2019年重庆市选调优秀大学生到基层工作考试《行测》题 第15 题", "qid": 2670610, "level": "中等", "stem": "美国三位传播学者在1970年提出了“知识沟假设”，认为随着大众传媒向社会传播的信息日益增多，处于不同社会经济地位的人获得媒介知识的速度是不同的，社会经济地位较高的人将比社会经济地位较低的人以更快的速度获取这类信息。因此，这两类人之间的知识差距将呈扩大之势。\n对上述“知识沟假设”能够做出合理解释的不包括：", "options": ["社会经济地位较高的人往往受教育程度高，具有更强的信息处理能力，这会有助于他们对知识的获取", "在特定的时间范围内，经媒介大量报道的话题上，人们获取信息和知识的速度与受教育程度有着很高的相关性", "传播有一定深度的科学知识的媒介主要是印刷媒介，它们的受众主要是社会经济地位较高的人", "社会经济地位较高的人日常交际圈更大，能参与更多的社会团体，拥有更多与他人进行深度讨论的机会，理解和接受知识的能力更强"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：社会经济地位较高与社会经济地位较低这两类人之间的知识差距将呈扩大之势。\n论据：随着大众传媒向社会传播的信息日益增多，处于不同社会经济地位的人获得媒介知识的速度是不同的，社会经济地位较高的人将比社会经济地位较低的人以更快的速度获取这类信息。\n本题论点和论据话题一致，加强优先考虑补充论据。\n第二步：逐一分析选项。\nA项：该项说明社会经济地位较高的人因具有更强的信息处理能力会有助于对知识的获取，通过解释原因补充了论据，可以加强，排除；\nB项：该项说明获取信息和知识的速度与受教育程度有相关性，但并没有说明社会经济地位较高和社会经济地位较低的这两类人之间的知识差距将呈扩大之势，无关选项，无法加强，当选；\nC项：该项说明社会经济地位较高的人更容易获取有一定深度的科学知识，通过解释原因补充了论据，可以加强，排除；\nD项：该项说明社会经济地位较高的人理解和接受知识的能力更强，通过解释原因补充了论据，可以加强，排除。\n本题为选非题，⇒ 正确答案为B。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2026年天津市公务员录用考试《行测》题（网友回忆版） 第30 题", "qid": 18643673, "level": "中等", "stem": "作为一种在全球范围内广泛使用的非生物降解塑料，聚苯乙烯在日常生活中极为常见。为了研究聚苯乙烯对动物的影响，科研人员对斑马鱼进行了试验，发现长期暴露于聚苯乙烯环境中，斑马鱼会表现出视动反应、趋光行为的迟缓，并出现视力下降。这让科研人员认为：长期接触聚苯乙烯会干扰视觉功能，造成动物的视力损伤。\n以下哪项如果为真，最能支持上述科研人员的结论？", "options": ["试验结果显示，聚苯乙烯浓度越高，斑马鱼的视网膜色素上皮受到的结构性损伤就越显著", "500nm的聚苯乙烯会影响光传导信号通路，使动物视觉感知失调并影响晶状体发育", "荧光观察发现，聚苯乙烯在视网膜层积累后，视神经细胞转录因子减少，视力障碍开始出现", "试验同时评估了80、200、500nm的聚苯乙烯对斑马鱼行为的影响，并测量了它们的游泳距离"], "answer": ["C"], "explain": "第一步：找出论点和论据。\n论点：长期接触聚苯乙烯会干扰视觉功能，造成动物的视力损伤。\n论据：长期暴露于聚苯乙烯环境中，斑马鱼会表现出视动反应、趋光行为的迟缓，并出现视力下降。\n本题论点和论据都在讨论长期接触聚苯乙烯会造成动物视力损伤，二者话题一致，加强优先考虑补充论据。\n第二步：逐一分析选项。\nA项：该项指出聚苯乙烯浓度越高，斑马鱼的视网膜色素上皮受到的结构性损伤就越显著，说明聚苯乙烯会损伤斑马鱼的视力，举例子补充论据，可以加强，保留；\nB项：该项指出500nm的聚苯乙烯会影响光传导信号通路，使动物视觉感知失调并影响晶状体发育，说明500nm的聚苯乙烯的确会损伤动物的视力，举例子补充论据，可以加强，保留；\nC项：该项指出聚苯乙烯在视网膜层积累后，视神经细胞转录因子减少，视力障碍开始出现，说明长期接触聚苯乙烯会减少视神经细胞转录因子，出现视力障碍，解释了为何长期接触聚苯乙烯会造成动物视力损伤，解释原因补充论据，可以加强，保留；\nD项：该项指出试验同时评估了80、200、500nm的聚苯乙烯对斑马鱼行为的影响，并测量了它们的游泳距离，告知了试验的具体条件和过程，而论点讨论的是长期接触聚苯乙烯会造成动物视力损伤，二者话题不一致，无法加强，排除。\n对比A、B、C三项，C项为解释原因，加强的力度大于A、B两项的举例子，C项当选。\n⇒ 正确答案为C。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2023年青海省公务员录用考试《行测》题（网友回忆版） 第26 题", "qid": 5509581, "level": "中等", "stem": "“饿怒”是“饥饿”和“愤怒”两个词的合成词。最近，研究人员在欧洲招募了64位自愿受试者，在21天里，对他们在日常工作和生活环境中，处于饥饿状态时的情绪变化数据进行了收集整理分析。得出的结论是，愤怒和易恼等情绪与饥饿之间存在被诱导的关系，也就是说，饥饿会使人们“饿怒”。\n以下哪项如果为真，最能支持上述结论?", "options": ["受试者在饥饿状态下，能保持情绪愉悦的只有不到10%", "饥饿与更强烈的愤怒和易恼情绪以及更低的愉悦感有关", "饥饿状态下的受试者，47%出现易恼情绪，44%出现愤怒情绪", "科学家早已知道饥饿会影响人的情绪，但才发现会导致“饿怒”"], "answer": ["C"], "explain": "论点：愤怒和易恼等情绪与饥饿之间存在被诱导的关系，也就是说，饥饿会使人们“饿怒”。\n论据：无。\n本题只有论点，没有论据，加强优先考虑补充论据，即解释原因或举例子。\nA项：该项说的是饥饿很难使人保持情绪愉悦，而论点说的是饥饿会使人们“饿怒”，话题不一致，无法加强，排除；\nB项：该项说的是饥饿与愤怒和易恼情绪以及更低的愉悦感有关，与论点表述一致，可以加强，保留；\nC项：该项说的是饥饿状态下的受试者出现易恼、愤怒情绪的概率，说明饥饿会导致愤怒和易恼，补充了题干的实验数据，可以加强，保留；\nD项：该项说的是科学家才发现饥饿会导致“饿怒”，科学家发现的时间早晚与论点讨论的饥饿会使人们“饿怒”无关，无法加强，排除。\n对比B、C两项，B项只说了饥饿和愤怒的情绪相关，属于重复论点，而C项在原有论证的基础上补充了明确的实验数据来支持论点，故C项的力度更强。\n⇒ 正确答案为C。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2018年黑龙江省公务员考试（乡镇）题（网友回忆版） 第28 题", "qid": 2188608, "level": "中等", "stem": "婴儿的幼年特征可以唤起成年人的慈爱和养育之心，许多动物的外形和行为具有人类婴儿的特征。因此，人们容易被这样的动物所吸引，将它们养成宠物。\n以下哪项如果为真，最能支持上述结论？", "options": ["很多空巢老人喜欢饲养宠物", "体态庞大且凶猛的动物很少成为宠物", "有的家庭在生育儿女后就不会再养宠物", "父母喜欢养宠物的，子女也喜欢养宠物"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：人们容易被这样的动物所吸引，将它们养成宠物。\n论据：婴儿的幼年特征可以唤起成年人的慈爱和养育之心，许多动物的外形和行为具有人类婴儿的特征。\n第二步：逐一分析选项。\nA项：该项说的是很多空巢老人喜欢饲养宠物，但宠物的外形和行为是否具有人类婴儿特征不明确，无法加强，排除；\nB项：该项说的是体态庞大且凶猛的动物很少成为宠物，说明人们更喜欢养体态较小且无害的动物，具有婴儿的特征，补充论据，当选；\nC项：论点说的是人们容易被外形和行为具有人类婴儿特征的动物所吸引，将它们养成宠物，该项说的是有的家庭在生育儿女后就不会再养宠物，话题不一致，无法加强，排除；\nD项：论点说的是人们容易被外形和行为具有人类婴儿特征的动物所吸引，将它们养成宠物，该项说的是父母喜欢养宠物的，子女也喜欢养宠物，话题不一致，无法加强，排除。\n⇒ 正确答案为B。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2022年北京市公务员录用考试《行测》题（网友回忆版） 第19 题", "qid": 4652298, "level": "中等", "stem": "研究人员对1971年到2008年间的36400名某国公民的膳食数据和1984年到2006年间的该国14419人的运动数据进行分析和整合。他们发现，生活在2000年代和1980年代的同龄人，摄入同样的热量、同样质量的蛋白和脂肪，做同样多的运动，2000年代的人还是会比1980年代的人在体重指数上高2.3%。换句话说，即使我们遵循同样的饮食和锻炼计划，今天的人也要比上世纪80年代的人重10%。研究者认为，这种情况可能和科技的发展有关。\n以下哪项如果为真，不能支持以上观点？", "options": ["近年来，越来越多的新型化工产品应用于日常生活，这些物质可能改变人体的荷尔蒙进程，让人体调整和维持体重的机制发生变化", "90年代后，新型的抗抑郁药被研发出来，成为了很多国家最常用的处方药之一，而这些药物都有让人变得虚胖的副作用", "近年来，科技发展使得人类的工作和生活方式发生了很大转变，体力劳动的比例显著下降，即使维持日常运动，总的体能支出也明显降低", "现代人吃的肉比几十年前的人多得多，需要新的肠道菌群来消化，肠道菌群的变化可能让人的食欲大增从而体重增长"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：同样的饮食和锻炼条件下，如今的人比上世纪80年代的人体重更重的情况可能和科技的发展有关。\n论据：无。\n本题只有论点，没有论据，可以考虑补充论据来加强，解释或者举例说明为什么如今的人们体重更重和科技发展有关，选非题排除加强项即可。\n第二步：逐一分析选项。\nA项：近年来，新型化工产品的应用会让人体调整和维持体重的机制发生变化，新型化工产品越来越多证明了科技的发展，科技产品影响人们的体重调节机制，解释了为什么如今的人们体重更重与科技发展有关，补充论据，可以加强，排除；\nB项：90年代后，最常用的抗抑郁药被研发出来，而这些药会让人变得虚胖，新型药品的研发证明了科技的发展，药物让人变得虚胖解释了为什么如今的人们体重更重与科技发展有关，补充论据，可以加强，排除；\nC项：近年来，科技发展让人们总的体能支出明显降低，而总的体能支出降低意味着人体能量消耗变少，会导致如今的人们体重更重，解释了为什么如今的人们体重更重与科技发展有关，补充论据，可以加强，排除；\nD项：现代人吃的肉更多，造成肠道菌群的变化，进而体重增长，这在说明如今的人们体重更重与肠道菌群有关，与论点讨论的科技发展无关，无法加强，当选。\n本题为选非题，⇒ 正确答案为D。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2025年湖北省选调生招录考试综合知识和行政职业能力测验试卷（网友回忆版） 第26 题", "qid": 15419143, "level": "中等", "stem": "在一项研究中，将睡眠不足定义为每晚睡眠时间少于7小时。研究者选择存在这种情况的受试者19816名，14年后随访，发现周末补偿性睡眠的受试者比没有补偿性睡眠的受试者患心血管疾病的可能性低19%，这一比率不存在男女差异。可见，充足的补偿性睡眠与罹患心血管疾病风险的降低有关。\n以下各项如果为真，最能支持上述结论的是：", "options": ["另一项有90903名受试者参与的研究也得出了相同的结论", "每天平均睡眠时间少于7小时，确实会增加患心血管疾病的风险", "充足的补偿性睡眠对心血管健康至关重要，也对整个机体健康至关重要", "每天平均睡眠时间7小时以上，能有效保护心脏生理机制的复杂平衡"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：充足的补偿性睡眠与罹患心血管疾病风险的降低有关。\n论据：研究者选择存在这种情况的受试者19816名，14年后随访，发现周末补偿性睡眠的受试者比没有补偿性睡眠的受试者患心血管疾病的可能性低19%，这一比率不存在男女差异。\n本题论点和论据讨论的都是“充足的补偿性睡眠”和“罹患心血管疾病风险”之间的关系，话题一致，加强优先考虑补充论据。\n第二步：逐一分析选项。\nA项：该项指出另一项研究也得出了相同的结论，通过补充其他研究的结果来证明“充足的补偿性睡眠与罹患心血管疾病风险的降低有关”，补充论据，可以加强，保留；\nB项：该项指出每天平均睡眠时间少于7小时，确实会增加患心血管疾病的风险，但并没有提到是否有充足的补偿性睡眠，而论点讨论的是充足的补偿性睡眠是否与罹患心血管疾病风险的降低有关，话题不一致，不能加强，排除；\nC项：该项指出充足的补偿性睡眠对心血管健康至关重要，也对整个机体健康至关重要，与论点表述的意思一致，可以加强，保留；\nD项：该项指出“平均”每天睡眠时间7小时以上对心脏的好处，根据题干第一句可知“睡眠不足指每晚睡眠时间少于7小时”，那么“充足的”补偿性睡眠应当指“平均到”每晚睡眠时间不少于7小时， 而每天平均睡眠时间7小时以上是能有效保护心脏生理机制的，所以需要通过周末的补偿性睡眠，来使“平均睡眠”达到7小时以上，这就解释了为什么“充足的”补偿性睡眠可以降低罹患心血管疾病的风险，补充论据，可以加强，保留；\n对比A、C、D三项，A项通过补充另外一个例子来证明论点成立，C项只是在重复论点，D项设置的很巧妙， 解释了为什么睡得少时要补偿性睡眠，因为当补到每天“平均”睡眠时间达到7小时时，能降低患心血管疾病的风险，解释了论点成立的原因，对比之后，D项解释原因的力度>A项举例子>C项重复论点，因此，D项加强力度更大，当选。\n⇒ 正确答案为D。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2022年福建省公务员录用考试《行测》题（网友回忆版） 第35 题", "qid": 5101618, "level": "中等", "stem": "日前，某区物价管理部门修改了停车费收费方案和标准，将机动车停车位收费价格上调了50%，并把部分原来免费的车位也纳入了收费管理，同时对新能源车免收停车费，这样能够增加车位的流动性，根治部分车主久占车位的乱象，有效缓解交通压力。\n以下哪项如果为真，最能支持上述方案？", "options": ["该方案通过网络征求了广大市民的意见和建议", "停车费收费方案调整后大大提升了车位空置率", "增加后的停车费标准仅与相邻城市的标准持平", "提高燃油机动车使用成本市民会购买新能源车"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：某区物价管理部门修改了停车费收费方案和标准，这样能够增加车位的流动性，根治部分车主久占车位的乱象，有效缓解交通压力。\n论据：无。\n本题只有论点，没有论据，加强优先考虑补充论据，即通过解释原因或举例子的方式来说明通过“修改停车费收费方案和标准”确实能“增加车位流动性”。\n第二步：逐一分析选项。\nA项：该项指出此方案征求了市民的意见和建议，但是市民同意该方案不代表该方案就可以增加车位流动性，为无关项，无法加强，排除；\nB项：该项指出调整方案后大大提升了车位空置率，车位空置率的提升可以增加车位的流动性，解释了为什么修改停车费收费方案和标准后，可以增加车位流动性，解释原因，可以加强，当选；\nC项：该项是拿本市的停车费标准与相邻城市的停车费标准进行比较，但本市与相邻城市的收费标准持平不代表可以增加车位流动性，为无关项，无法加强，排除； \nD项：该项指出提高燃油机动车使用成本，市民会购买新能源车，但市民购买了新能源车不代表可以增加车位流动性，无法加强，排除。\n⇒ 正确答案为B。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2016年北京市公务员录用考试《行测》题 第14 题", "qid": 1752876, "level": "中等", "stem": "某科学家批评了人们对化学添加剂的恐惧。“食品标签上如果出现很多添加剂就会让人心生恐惧，但其实添加剂和防腐剂是受到严格控制和计量的，真正应该关注的是食品中糖和脂肪的含量。防腐剂是有益的，显然，我们都愿意吃到一个保存良好的罐头，而不希望因为摄入肉毒杆菌而死亡。”\n下列陈述如果为真，哪项无法支持该科学家的观点？", "options": ["很多药物也是化学制剂，是药三分毒，用药要谨慎", "纯天然无添加的原生态食品很难储存，而且价格更高", "防腐剂可以有效防止食品腐败变质、滋生细菌", "食品安全关键在于食品添加剂种类与量的严格控制"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：不需要恐惧添加剂。\n论据：添加剂和防腐剂是受到严格控制和计量的，是有益的。\n第二步：逐一分析选项。\nA项：题干中说的是防腐剂和添加剂，而A选项说的是化学制剂，无关项，当选；\nB项：无添加的食品难储存，说的是没有防腐剂和添加剂时不好的地方，可以加强，排除；\nC项：防腐剂可以防止滋生细菌，是说的好的地方，可以加强，排除；\nD项：说的是添加剂的种类和用量是严格控制的，可以加强，排除。\n本题为选非题，⇒ 正确答案为A。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2022年国家公务员录用考试《行测》题（副省级网友回忆版） 第37 题", "qid": 4637581, "level": "中等", "stem": "熊蜂是一类多食性昆虫，与蜜蜂相比，熊蜂体型更大且多毛，颜色各异，大多有着经典的黄黑条纹，黑身红尾。人们发现，由于密集管理型农业系统的推广，熊蜂在这些地方开始衰落，有的种类已经灭绝，相对而言，普通蜜蜂的数量并没有明显减少。因此，相比普通蜜蜂，农田利用方式的改变对熊蜂的生存威胁更大。\n以下哪项如果为真，最能支持上述结论？", "options": ["蜜蜂采食会派出“侦查员”，回来后通过一种“摆动舞”告知蜂群食源在哪里，而熊蜂不会跳舞，因此大多独自采食", "蜜蜂会在蜂巢内储藏大量食物，熊蜂的蜂巢储存食物量较少，一旦出现食物短缺，熊蜂就会处于劣势", "蜜蜂属于大型化社群，而熊蜂属于小型化社群，这会导致基因分异度降低，更易受到寄生虫感染而大量死亡", "密集型农田往往种植单一植物，如果植物不是处于花期，熊蜂就会因无法如蜜蜂般进行远距离飞行而岌岌可危"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：相比普通蜜蜂，农田利用方式的改变对熊蜂的生存威胁更大。\n论据：由于密集管理型农业系统的推广，熊蜂在这些地方开始衰落，有的种类已经灭绝，相对而言，普通蜜蜂的数量并没有明显减少。\n论点和论据都在讨论熊蜂生存情况和农田利用方式的关系，话题一致，加强优先考虑补充论据。\n第二步：逐一分析选项。\nA项：该项讨论蜜蜂和熊蜂的采食方式，与题干论点讨论的话题无关，无法加强，排除；\nB项：该项讨论蜜蜂和熊蜂储存食物的习惯不同，出现食物短缺时熊蜂更容易受到影响，但农田利用方式的改变是否会出现食物短缺情况文段并未提及，与题干论点讨论的话题无关，无法加强，排除；\nC项：该项讨论熊蜂因基因分异度降低更易受到寄生虫感染，但农田利用方式的改变是否会有寄生虫感染的风险文段并未提及，与题干论点讨论的话题无关，无法加强，排除；\nD项：该项指出密集型农田对熊蜂影响更大，熊蜂无法远距离飞行而岌岌可危，解释农田利用方式的改变为什么更能威胁熊蜂的生存，解释原因，可以加强，当选。\n⇒ 正确答案为D。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "广东省2019年选调优秀大学毕业生笔试 思维能力测验（网友回忆版） 第2 题", "qid": 2262043, "level": "中等", "stem": "新时代对党员干部提出了更高的要求。在现实中，由于一些党员干部理论学习不足，“本领恐慌”问题越来越突出。因此，只要广大党员干部切实加强理论学习，就可以避免出现“本领恐慌”。\n上述论证最可能的潜在假设是（  ）。", "options": ["解决“本领恐慌”问题必须依靠党员干部自身努力", "理论学习不足是出现“本领恐慌”的唯一原因", "广大党员干部都存在理论学习不足的问题", "只有加强学习才能达到新时代的更高要求"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：只要广大党员干部切实加强理论学习，就可以避免出现“本领恐慌”。\n论据：在现实中，由于一些党员干部理论学习不足，“本领恐慌”问题越来越突出。\n第二步：逐一分析选项。\nA项：论点说的是通过党员干部加强理论学习能不能避免出现“本领恐慌”，该项说的是依靠干部自身努力，干部自身努力是否指的是加强理论学习，以及结果是否能避免出现“本领恐慌”并不明确，不是论证成立的假设，排除；\nB项：理论学习不足是出现“本领恐慌”的唯一原因，说明只要解决了唯一原因就可以解决问题，那么只要广大党员干部切实加强理论学习，就可以避免出现“本领恐慌”，是论证成立的假设，当选；\nC项：论点说的是通过党员干部加强理论学习能不能避免出现“本领恐慌”，该项说的是党员干部是否存在理论学习不足的问题，话题不一致，不是论证成立的假设，排除；\nD项：该项说的是加强学习能达到新时代的更高要求，但是能不能避免出现“本领恐慌”是不明确的，不是论证成立的假设，排除。\n⇒ 正确答案为B。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}, {"type": "加强论证", "from": "2018年新疆生产建设兵团面向社会招录公务员考试《行测》题（网友回忆版） 第25 题", "qid": 2247201, "level": "中等", "stem": "我国北方地区沙漠相比2.6万年至1.6万年前的末次盛冰期有较大幅度的收缩，而相比9000年至5000年前的全新世大暖期又有明显扩大。因此，研究者认为，气候的变化，乃至北半球高纬地区冰量变化，是影响我国沙漠和沙地的地表环境变化的主要因素。\n如果以下各项为真，最能加强上述论证的是：", "options": ["利用生物措施和工程措施构筑防护体系的做法有助于控制沙漠化", "西北某干旱地区，因为常年有风，所以形成了一个个新月形沙丘", "撒哈拉沙漠位于北回归线两侧，受副热带高气压带控制，气候炎热干燥", "某段时期，中国北部气温上升，降雨增加，流沙面积比之前收缩了一半"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：气候的变化，乃至北半球高纬地区冰量变化，是影响我国沙漠和沙地的地表环境变化的主要因素。\n论据：我国北方地区沙漠相比2.6万年至1.6万年前的末次盛冰期有较大幅度的收缩，而相比9000年至5000年前的全新世大暖期又有明显扩大。\n第二步：逐一分析选项。\nA项：该项说的是如何能控制沙漠化，题干讨论的是气候变化和冰量变化与我国沙漠、沙地地表环境变化之间的关系，话题不一致，无法加强，排除；\nB项：该项说的是西北某干旱地区因常年有风形成沙丘，题干探讨的主题是气候变化和冰量变化，而非风的变化，偷换概念，话题不一致，无法加强，排除；\nC项：该项说的是撒哈拉沙漠气候干燥炎热的原因，题干探讨的是气候变化对沙漠地表环境的影响，话题不一致，无法加强，排除； \nD项：气温上升降雨增加导致流沙面积比之前收缩了一半，说明气候变化对沙地的地表环境变化有影响，补充论据支持，可以加强，当选。\n⇒ 正确答案为D。", "point": "考论点与论据之间的推理能不能立住；加强 = 让结论更可能成立。最强的手段是「搭桥」——在论据和论点之间建立必然联系。", "method": "先找论点和论据；看选项是搭桥、补充论据还是举例：搭桥 > 补充论据 > 举例。", "tip": "话题跑偏的一律是无关项；「有些」的力度弱于「所有」。"}]}, {"set": 105, "cat": "削弱论证", "title": "专项挑战 · 削弱论证", "date": "", "session": "", "items": [{"type": "削弱论证", "from": "2025年黑龙江公务员录用考试《行测》题（网友回忆版） 第22 题", "qid": 13504624, "level": "中等", "stem": "在一项对小鼠的研究中，对被诱导患上2型哮喘的小鼠注射一种基因改造细胞CAR-T细胞，就能在实验持续时间中阻止哮喘症状继续出现。研究人员认为该CAR-T细胞可以杀死引发哮喘发作的无赖免疫细胞。因此，CAR-T细胞将大规模用于治疗哮喘。\n以下哪项如果为真，最能削弱上述结论？", "options": ["大多数哮喘患者用吸入器就够了，但每年都有约25万人死于严重哮喘", "在上述治愈哮喘的实验过程中，小鼠身上并没有产生明显的副作用", "哮喘作为一种慢性疾病，其病因复杂，市面上的药物都无法根治", "生成CAR-T细胞的费用极其昂贵，预计治疗费用将在三百万元左右"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：CAR-T细胞将大规模用于治疗哮喘。\n论据：在一项对小鼠的研究中，对被诱导患上2型哮喘的小鼠注射一种基因改造细胞CAR-T细胞，就能在实验持续时间中阻止哮喘症状继续出现。研究人员认为该CAR-T细胞可以杀死引发哮喘发作的无赖免疫细胞。\n本题的论点讨论的是CAR-T细胞会大规模用于治疗哮喘，论据是通过对小鼠的研究实验讨论CAR-T细胞可以杀死引发哮喘发作的无赖免疫细胞，从而治疗哮喘，论点与论据话题一致，削弱可优先考虑削弱论点。\n第二步：逐一分析选项。\nA项：该项指出大多数哮喘患者虽用吸入器即可，但每年仍然有大量患者死于严重哮喘，但论点讨论的是CAR-T细胞是否可大规模用于治疗哮喘，话题不一致，无关项，无法削弱，排除；\nB项：该项指出在实验过程中小鼠未出现明显副作用，但没有提及是否对哮喘有治疗作用，而论点讨论的是CAR-T细胞是否可大规模用于治疗哮喘，无关项，无法削弱，排除；\nC项：该项指出市面上的药物无法根治哮喘，而论点讨论的是CAR-T细胞是否可大规模用于治疗哮喘，话题不一致，无关项，无法削弱，排除；\nD项：该项指出生成CAR-T细胞的费用“极其昂贵”，治疗费用将在三百万元左右，因此很多患者可能会由于其治疗成本高而无法接受该治疗，故CAR-T细胞无法“大规模”用于治疗哮喘，直接削弱论点，可以削弱，当选。\n⇒ 正确答案为D。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2016年河南省公务员录用考试《行测》题 第33 题", "qid": 2033400, "level": "中等", "stem": "某市多年来一直存在人才外流的现象，但自从大学城搬迁到该市后，出现了名校毕业生在该市就业难的现象，因此有人认为该市就业难是大学城搬迁带来的。\n以下哪项如果为真，最能支持上述结论？", "options": ["周围其他市依旧存在人才外流现象", "本市的企业在2年内增长了3倍", "本市大学城搬迁前也存在就业难的现象", "本市政府出台政策鼓励学生自主创业"], "answer": ["B"], "explain": "第一步：找到论点论据。\n论点：该市就业难是大学城搬迁带来的。\n论据：某市多年来一直存在人才外流的现象，但自从大学城搬迁到该市后，出现了名校毕业生在该市就业难的现象。\n第二步：逐一分析选项。\nA项：周围其他市也存在人才外流的情况，与该市是因为什么原因导致就业难是两件不同的事情，无关选项，排除；\nB项：就业涉及到就业人员与企业双方面的因素，本市企业增多说明不是企业少的因素导致就业难，即就业人员增加是就业难的原因，大学城搬迁可以导致就业人数增加，补充论据，加强，当选；\nC项：搬迁之前也有这种情况，说明搬迁没有导致就业难，削弱题干论点，排除；\nD项：政府鼓励自主创业，但是否有成效并不确定，对毕业生的影响也无法判断，且毕业生就业的情况并未提及，无关选项，排除。\n⇒ 正确答案为B。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2016年江西省法检系统招录考试《行测》题 第29 题", "qid": 2255772, "level": "中等", "stem": "近来有报道称，大多数自来水厂的水质由于使用的漂白物质中都含有亚硝酸类的致癌物质，因此，目前自来水厂对人体会带来严重威胁。最能质疑上述观点的是：", "options": ["大多数自来水厂的水含亚硫酸铵的含量没有超标，不会对人体健康产生明显影响", "有些自来水厂的水亚硝酸胺的含量很低", "自来水厂处理水质过程中不使用漂白物质是不可能的", "自来水厂改变水处理方式可以有效降低亚硝酸胺的含量"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：目前自来水厂对人体会带来严重威胁。\n论据：大多数自来水厂的水质使用的漂白物质中都含有亚硝酸类的致癌物质。\n第二步：逐一分析选项。\nA项：指出这些水虽然含亚硫酸铵，但不会对人体健康产生明显影响，直接否定论点，当选；\nB项：指出有些自来水厂的水亚硝酸胺的含量很低，不能说明目前所有自来水厂的情况，无法削弱，排除；\nC项：指出自来水厂处理水质过程中一定会使用漂白物质，与论点讨论的是否会对人体带来危害无关，无法削弱，排除； \nD项：指出可以降低亚硝酸胺的含量，与论点讨论的是否会对人体带来危害无关，无法削弱，排除。\n⇒ 正确答案为A。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2023年山东省公务员录用考试《行测》试题（网友回忆版） 第29 题", "qid": 5510394, "level": "中等", "stem": "校园欺凌是当今社会高度关注的现象。为了防止校园欺凌，有人建议在校园内显著位置张贴公布校园欺凌的求助电话，学生遭遇欺凌后，可以拨打求助电话，获得老师帮助。\n以下哪项如果为真，最能削弱上述建议实施效果?", "options": ["很多教师面对实施欺凌的学生，缺乏有效教育训诫手段", "校园欺凌多发生在夜间，求助电话无人接听", "欺凌者会恐吓被欺凌者，不要试图向教师或家长求助", "部分受害者认为“告状”可耻，不愿寻求成人的帮助"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：在校园内显著位置张贴公布校园欺凌的求助电话，学生遭遇欺凌后，可以拨打求助电话，获得老师帮助，从而防止校园欺凌。\n论据：无。\n本题只有论点，没有论据，优先考虑削弱论点，即在校园内显著位置张贴公布求助电话不能防止校园欺凌。\n第二步：逐一分析选项。\nA项：该项说的是教师面对实施欺凌的学生，缺乏有效教育训诫手段，与在校园内显著位置张贴公布求助电话能否防止校园欺凌无关，为无关项，无法削弱，排除；\nB项：该项说的是校园欺凌多发生在夜间，求助电话无人接听，说明在校园内显著位置张贴公布求助电话不能防止校园欺凌，削弱论点，当选；\nC项：该项说的是欺凌者会恐吓被欺凌者，不要试图向教师或家长求助，但被欺凌者是否会拨打求助电话向老师求助不明确，为不明确项，无法削弱，排除；\nD项：该项说的是部分受害者不愿寻求成人的帮助，说明有受害者愿意寻求成人的帮助，那么张贴求助电话这一建议是有效的，可以帮助受害者获得老师帮助，从而防止校园欺凌，为加强项，无法削弱，排除。\n⇒ 正确答案为B。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2024年山东省公务员录用考试《行测》试题（网友回忆版） 第39 题", "qid": 13648295, "level": "中等", "stem": "欧洲晴雨表网站的调查表明，英国民众对欧盟的支持是波动的，苏格兰和威尔士的支持程度一直稳定且偏高，在法国和德国拒绝入侵伊拉克之后，英国对欧盟的总体支持达到最低点，英国政府推迟了涉及多数表决的新宪法的所有提议。然而，英国政府支持进一步扩大欧盟——为了削弱法国和德国的主导地位。\n由此可以推出：", "options": ["法德两国在欧盟的地位影响了英国政府的某些决策", "英国政府此前对“扩大欧盟”的支持与法德两国有关", "苏格兰对欧盟的支持程度一直高于英国", "苏格兰和威尔士并不担忧法德两国在欧盟的地位"], "answer": ["A"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干最后一句指出英国政府为了削弱法国和德国的主导地位支持进一步扩大欧盟，证明了法德两国在欧盟的地位影响了英国政府的某些决策，可以推出，当选；\nB项：题干中没有涉及“此前”英国政府的情况，无中生有，无法推出，排除；\nC项：题干只是指出“苏格兰和威尔士的支持程度一直稳定且偏高”，并没有与英国比较，无法推出，排除；\nD项：题干未提及苏格兰和威尔士是否担忧法德两国在欧盟的地位，无中生有，无法推出，排除。\n⇒ 正确答案为A。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2022年天津市公务员录用考试《行测》试题（网友回忆版） 第23 题", "qid": 5102644, "level": "中等", "stem": "某流行病的差异研究中发现男性和女性之间的结果存在差异。研究人员注意到，虽然男性和女性感染该疾病的比例相似，但男性似乎更容易死于这种病毒诱发的肝炎。专家据此认为，免疫功能的性别差异可能是导致不同性别出现临床表现差异的原因。\n以下哪项为真，最能削弱上述观点？", "options": ["男性患者住院的概率比女性高20%左右，一旦住院接受治疗，男性患者更有可能需要进入重症监护室，而且入院后的死亡概率更高", "随着该疾病患病人群的数据集不断扩大，支持存在差距的证据不断出现", "近十年来与该疾病致病原理类似的病毒暴发的数据也显示在确诊的病例中，男性患者的死亡风险高于女性", "参与研究的大多数男性都有酗酒抽烟的不良生活习惯，会容易引起其他疾病"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：免疫功能的性别差异可能是导致不同性别出现临床表现差异的原因。\n论据：某流行病的差异研究中发现男性和女性之间的结果存在差异。研究人员注意到，虽然男性和女性感染该疾病的比例相似，但男性似乎更容易死于这种病毒诱发的肝炎。\n本题论点论据说的都是不同性别对某流行病的临床表现存在差异，话题一致，削弱优先考虑削弱论点，且论点中存在因果关系，还可以考虑因果倒置和他因削弱。\n第二步：逐一分析选项。\nA项：该项说男性患者住院概率和死亡概率更高，但未说明男女之间出现差异的“原因”，而论点讨论的是导致不同性别出现临床表现差异的“原因”，话题不一致，无法削弱，排除；\nB项：该项说不断出现支持存在差距的证据，对论据有补充的效果，有加强的作用，无法削弱，排除；\nC项：该项说与该疾病致病原理类似的病例中男性的死亡风险高于女性，但“类似”疾病与“该疾病”不能划等号，且该项未说明男女之间出现差异的“原因”，而论点讨论的是导致不同性别出现临床表现差异的“原因”，话题不一致，无法削弱，排除；\nD项：该项说参与研究的大多数男性有不良的生活习惯，容易引起其他疾病，说明该流行病不同性别的临床表现差异不一定是免疫功能的性别差异导致的，也有可能是这部分男性的不良生活习惯导致的，他因削弱，可以削弱，当选。\n⇒ 正确答案为D。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2025年青海省公务员录用考试《行测》题（网友回忆版） 第25 题", "qid": 13504503, "level": "中等", "stem": "大蚕蛾具有其他昆虫无法比拟的巨大翅膀，长度可达28cm，是自然界中最为绚丽灿烂的昆虫之一。在自然界中，为了吸引异性，许多动物都拥有鲜艳美丽的外形，因此，科学家认为，大蚕蛾的“锦衣华服”是用于吸引异性，从而增加交配繁殖的几率。\n以下哪项如果为真，最能削弱上述结论：", "options": ["绝大部分种类的大蚕蛾生存繁衍于群山密林之中，昼伏夜出，无法看清同类的翅膀", "大蚕蛾翅膀的绚丽来自于鳞片的密集排布，能折射和衍射光线，从而让天敌分心或疑惑", "大蚕蛾头顶的触角是重要的感觉器官，主要起到嗅觉和触觉作用，可以通过触角进行信息交流", "大蚕蛾雌雄两性的色泽不同，雄性大体呈橘黄色，翅膀以杏黄色为主，雌性为青白色，翅膀以淡绿色为主"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：大蚕蛾的“锦衣华服”是用于吸引异性，从而增加交配繁殖的几率。\n论据：在自然界中，为了吸引异性，许多动物都拥有鲜艳美丽的外形。\n本题论点和论据均在讨论“外形”和“吸引异性”的关系，二者话题一致，削弱优先考虑削弱论点。\n第二步：逐一分析选项。\nA项：该项指出绝大部分种类的大蚕蛾生存繁衍于群山密林，无法看清同类的翅膀，说明大蚕蛾无法依靠外形吸引异性，增加交配繁殖的几率，削弱论点，可以削弱，当选；\nB项：该项指出大蚕蛾翅膀绚丽的原因，绚丽的翅膀能让天敌分心或疑惑，但并未提及绚丽翅膀能否吸引异性，增加交配繁殖的几率，话题不一致，无法削弱，排除；\nC项：该项指出大蚕蛾头顶的触角能起到哪些作用，而论点讨论的是大蚕蛾的绚丽翅膀能否吸引异性，增加交配繁殖的几率，话题不一致，无法削弱，排除；\nD项：该项指出大蚕蛾雌雄两性的色泽区别，而论点讨论的是大蚕蛾的绚丽翅膀能否吸引异性，增加交配繁殖的几率，话题不一致，无法削弱，排除。\n⇒ 正确答案为A。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2021年国家公务员录用考试《行测》题（副省级网友回忆版） 第40 题", "qid": 2719410, "level": "中等", "stem": "近日，有研究团队通过对44个反刍动物物种的基因组测序研究，创建了一个反刍动物的系统进化树，从而解释大量反刍动物的演化史。结果揭示，在近10万年前，反刍动物种群发生大幅衰减，而这些种群数的减少与人类向非洲之外迁徙的时间相符。有人据此认为，这佐证了早期人类活动造成了反刍动物种群的衰减。\n以下哪项如果为真，最能质疑上述结论？", "options": ["反刍动物种群衰减后，植被愈加茂盛，为人类提供了更多食物", "反刍动物通常有角，在遇到人类攻击时能发挥一定的防御作用", "同一时期的马、驴等奇蹄目动物的种群也出现大幅衰减的现象", "同一时期大型猫科动物繁盛，它们大规模捕杀反刍动物"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：这佐证了早期人类活动造成了反刍动物种群的衰减。\n论据：在近10万年前，反刍动物种群发生大幅衰减，而这些种群数的减少与人类向非洲之外迁徙的时间相符。\n论点论据都在讨论早期人类活动和反刍动物种群之间的关系，论点论据话题一致，论点中存在因果关系，可优先考虑因果倒置和他因削弱。\n第二步：逐一分析选项。\nA项：该项说的是反刍动物衰减后给人类的影响，论点说的是早期人类活动造成了反刍动物种群的衰减，话题不一致，无法削弱，排除；\nB项：该项说的反刍动物对人类攻击有一定的防御作用，那到底是否是人类活动造成的反刍动物种群衰减不是十分明确，属于不确定选项，无法削弱，排除；\nC项：该项说的是同一时期奇蹄目动物的种群也大幅度衰减，论点说的是早期人类活动造成反刍动物种群的衰减，主体不一致，无法削弱，排除；\nD项：该项说的是同一时期，还有另外一个原因也就是猫科动物大规模捕杀反刍动物也造成反刍动物种群的衰减，属于他因削弱，当选。\n⇒ 正确答案为D。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2020年广东省公务员录用考试《行测》试题（县级卷）（网友回忆版） 第17 题", "qid": 2604274, "level": "中等", "stem": "有人认为，十二生肖起源于动物崇拜。这是因为在原始社会中，人类的生产力水平很低，猪、牛、羊等牲畜与农事活动关系密切，动物崇拜也就随之而生。除此之外，虎、蛇等动物可能威胁到人类的自身安全，往往被视为强大的象征，人们也会因为感到恐惧而形成动物崇拜。\n以下选项如果为真，最能反驳上述判断的是（    ）。", "options": ["十二生肖中只有龙不是现实中存在的动物", "“过街老鼠人人喊打”，但它是十二生肖之首", "鸡、鸭、鹅与农事活动关系密切，但只有鸡属于十二生肖", "牛和猪都与农事相关，但他们在十二生肖中的位置相距很远"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：十二生肖起源于动物崇拜。\n论据：因为在原始社会中，人类的生产力水平很低，猪、牛、羊等牲畜与农事活动关系密切，动物崇拜也就随之而生。除此之外，虎、蛇等动物可能威胁到人类的自身安全，往往被视为强大的象征，人们也会因为感到恐惧而形成动物崇拜。\n本题的论点在说十二生肖起源于动物崇拜，论据在说人类会对与农事活动关系密切还有可能威胁人类自身安全的动物产生动物崇拜，可以用与农事活动关系密切的动物不会令人产生动物崇拜，或者用强大的象征动物也不会令人产生动物崇拜进行削弱。\n第二步：逐一分析选项。\nA项：选项讨论的是龙不是现实中存在的动物，但是无法判断人们对龙是否存在动物崇拜，话题不一致，无法削弱，排除；\nB项：“过街老鼠人人喊打”，但它是十二生肖之首，说明老鼠是人们痛恨并且人人喊打的动物，而不是与农事活动关系密切或强大到令人恐惧的动物，为举反例削弱论点，当选；\nC项：鸡、鸭、鹅与农事活动关系密切，但只有鸡属于十二生肖，无法否定十二生肖起源于动物崇拜，因为三种动物虽然都与农事活动紧密相关，但是三者与农事活动的密切程度，以及其他方面可能有差异，因此无法削弱，排除；\nD项：选项讨论的是牛和猪的排位问题，论点讨论的是动物崇拜的问题，二者讨论的话题不一致，无法削弱，排除。\n⇒ 正确答案为B。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2021年江苏省公务员录用考试《行测》题（C类）（网友回忆版） 第30 题", "qid": 2741976, "level": "中等", "stem": "2020年疫情肆虐，但电商直播逆势崛起，一季度全国电商直播超过400万场，“万物可播、全民可播”成为一个响亮的口号。一项针对消费者和商家的调查显示，在电商直播中，许多消费者能以优惠的价格购买到心仪的商品，商家也能提升其销售额。有专家据此推断，电商直播的商业模式在疫情过后仍会受到商家和消费者的追捧。\n以下各项如果为真，则除哪项外均能削弱上述专家的观点？", "options": ["低价促销已经成为当前直播带货的常态，这种价格竞争让商家无利润可赚", "直播带货往往造成线上线下的价格不一致，不利于商家维护企业品牌形象", "许多消费者购买直播销售的商品后遇到了以次充好、售后维权困难等情况", "个别带货主播为了利益常常夸大自己的销售数据，而消费者对此并不知情"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：电商直播的商业模式在疫情过后仍会受到商家和消费者的追捧。\n论据：在电商直播中，许多消费者能以优惠的价格购买到心仪的商品，商家也能提升其销售额。\n第二步：逐一分析选项。\nA项：该项讨论的是商品低价促销让商家无利润可赚，说明对于消费者来说是利好的，但是商家赚不到钱，对于商家来说是不利的，所以电商直播不能受到商家的追捧，可以削弱，排除；\nB项：该项讨论的是商品线上线下的价格不一致，不利于商家维护企业品牌形象，说明直播带货不会受到商家的追捧，可以削弱，排除；\nC项：该项讨论的是消费者通过直播购买商品后发现商品质量有问题和售后维权困难，说明直播带货有弊端，所以不会受到消费者的追捧，可以削弱，排除；\nD项：该项讨论的是主播夸大销售数据，而消费者对此并不知情，但是题干论点讨论的是电商直播这种商业模式是否会被商家和消费者追捧，与论点讨论的话题无关，为无关选项，无法削弱，当选。\n本题为选非题，⇒ 正确答案为D。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2021年重庆市选调优秀大学生到基层工作考试《行测》题 第16 题", "qid": 4675379, "level": "中等", "stem": "目前认为造成白垩纪末期（约6600万年前）包括恐龙在内的大量生物灭绝的原因是，一颗直径约10千米的巨大陨石撞击了地球。1991年，陨石撞击的重要证据——陨石坑在墨西哥尤卡坦半岛附近发现。有学者提出假说如下：陨石撞击地球后，岩石等产生的尘埃造成植物无法进行光合作用，气候变得寒冷，恐龙等生物无法适应这种环境变化，从而灭绝。\n以下说法最能有力驳斥上述恐龙灭绝原因的是：", "options": ["陨石撞击产生的岩石尘埃粒径约为0.1毫米，停留在大气中最多也就1周左右，阳光仅被阻挡1周的环境变化不至于引起生物灭绝", "在加拿大西部艾伯塔省的一个地区，发现大约8000万年前生活于此的恐龙有45种，但就在陨石撞击之前不久，种类已减少到只有6种", "白垩纪末期的印度地区发生了大规模火山运动，在全球范围内带来了巨大的环境变化", "目前尚不确定6600万年前在地球上撞出巨大陨石坑的是哪一颗小行星，因此也不清楚造成恐龙灭绝的始作俑者"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：目前认为造成白垩纪末期（约6600万年前）包括恐龙在内的大量生物灭绝的原因是，一颗直径约10千米的巨大陨石撞击了地球。\n论据：陨石撞击地球后，岩石等产生的尘埃造成植物无法进行光合作用，气候变得寒冷，恐龙等生物无法适应这种环境变化，从而灭绝。\n本题论点论据讨论的都是陨石撞击地球与造成恐龙等生物的灭绝之间的关系，论点论据话题一致，削弱可以优先考虑削弱论点，即指出陨石撞击地球不会造成恐龙等生物的灭绝。\n第二步：逐一分析选项。\nA项：该项说的是陨石撞击最多只会产生1周的环境变化，而这不至于引起生物灭绝，说明陨石撞击带来的影响很快就会结束，不会造成恐龙等生物的灭绝，削弱论点，可以削弱，当选；\nB项：该项说的是8000万年前某一地区的恐龙种类在陨石撞击之前就已减少，而题干讨论的是白垩纪末期（约6600万年前）恐龙等生物灭绝的原因，话题不一致，无法削弱，排除；\nC项：该项说的是白垩纪末期的印度地区发生的大规模火山运动给全球带来了巨大的环境变化，而题干讨论的是陨石撞击地球是否会造成恐龙等生物灭绝，话题不一致，无法削弱，排除；\nD项：该项说的是目前尚不清楚造成恐龙灭绝的始作俑者，不明确项，无法削弱，排除。\n⇒ 正确答案为A。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2024年浙江省公务员录用考试《行测》题（C类）（网友回忆版） 第30 题", "qid": 5911224, "level": "中等", "stem": "体温调节模式假说认为，变温动物因为需要吸收外部热量调节体温，因此代谢率通常较低，而恒温动物由内部产生热量，代谢率较高，因此变温动物比恒温动物衰老速度慢。就像人们觉得老鼠衰老快，是因为它们新陈代谢率很高，而海龟衰老慢，是因为它们新陈代谢率很低。\n以下哪项如果为真，最能削弱上述假说?", "options": ["有壳这种物理特征保护，海龟的衰老速度较慢，寿命更长", "研究显示，变温动物的衰老率远高于或远低于相似体型恒温动物的衰老率", "得出上述假说的研究主要集中在动物园的动物或少数野生动物中，且获得的证据参差不齐", "部分变温动物的衰老可忽略不计，包括青蛙、海龟等，一旦过了繁殖期，它们死亡的可能性不会随着年龄的增长而改变"], "answer": ["B"], "explain": "第一步：找出论点和论据。论点：变温动物比恒温动物衰老速度慢。论据：①变温动物因为需要吸收外部热量调节体温，因此代谢率通常较低，而恒温动物由内部产生热量，代谢率较高。②人们觉得老鼠衰老快，是因为它们新陈代谢率很高，而海龟衰老慢，是因为它们新陈代谢率很低。本题论点和论据都在讨论变温动物比恒温动物的衰老速度慢，二者话题一致，削弱优先考虑削弱论点。第二步：逐一分析选项。A项：该项指出海龟衰老速度较慢是因为有壳的保护，说明海龟衰老速度较慢的原因并不是新陈代谢率低，削弱论据，保留；B项：该项指出变温动物的衰老率远高于或远低于相似体型恒温动物的衰老率，也就是说变温动物的衰老率不一定比恒温动物衰老速度慢，而论点是说变温动物比恒温动物衰老速度慢，削弱论点，保留；C项：该项指出得出体温调节模式假说的研究涉及的动物样本数量较少，且获得的证据参差不齐，说明该研究结果可能无法真实地反映总体情况，可以削弱，保留；D项：该项指出部分变温动物的衰老可忽略不计，说明部分变温动物的衰老速度非常慢，且未与恒温动物的衰老速度进行比较，无法削弱，排除。对比A、B、C三项，A项为削弱论据，B项是直接削弱论点，C项是通过质疑得出论点的研究样本来削弱论点，但论点和论据中都并未直接说明研究过程，且结合下面原文来看，作者先提及了C项，后又提及了B项来削弱前面的观点，因此出题时可能更倾向于B项力度更强，所以小粉笔择优把答案定为B项。原文内容：⇒ 正确答案为B。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2025年深圳市考公务员录用考试《行测》试题（网友回忆版） 第16 题", "qid": 13432360, "level": "中等", "stem": "微型塑料是指粒径小于5毫米的塑料颗粒，其理化性质稳定、来源广泛，在海洋、大气及土壤等环境中普遍存在，进入人体后，可能在消化系统、呼吸系统、循环系统等部位蓄积。卫生领域权威国际组织发布报告指出，目前还没有足够数据来全面了解微型塑料对人类健康的影响。因此，一些媒体宣称微型塑料不会对人体产生危害。\n以下选项如果为真，最能反驳上述结论的是（    ）。", "options": ["许多国家和地区已在限塑禁塑方面展开积极行动，未来将加速推进全球塑料条约谈判", "人们无时无刻不暴露在微型塑料环境中，人口密集和活动频繁的地区，微型塑料浓度更高", "动物研究表明，海洋高等哺乳动物脏器内偶见微型塑料颗粒，其肠道菌群发生显著改变", "微型塑料吸附环境中的其他分子后形成稳定的化合物，成为有害物质进入人体的重要载体"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：微型塑料不会对人体产生危害。\n论据：卫生领域权威国际组织发布报告指出，目前还没有足够数据来全面了解微型塑料对人类健康的影响。\n本题论点讨论的是微型塑料不会对人体产生危害，论据讨论的是没有足够数据来全面了解微型塑料对人类健康的影响，因为没有足够的数据了解微型塑料对人类影响，所以它不会对人体产生危害，论点论据话题一致，削弱优先考虑削弱论点，即微型塑料会对人体产生危害。\n第二步：逐一分析选项。\nA项：指出各地在限塑禁塑方面展开积极行动，但没有体现限塑的原因是否与微型塑料对人体的影响有关，话题不一致，不能削弱，排除；\nB项：指出人们暴露在浓度较高的微型塑料环境中，与微型塑料是否会对人体产生危害无关，话题不一致，不能削弱，排除；\nC项：指出微型塑料会改变海洋高等哺乳动物的肠道菌群，而论点说的是微型塑料对人体的危害，主体不一致，不能削弱，排除；\nD项：指出微型塑料是有害物质进入人体的重要载体，说明微型塑料会对人体产生危害，削弱论点，可以削弱，当选。\n⇒ 正确答案为D。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2021年新疆公务员录用考试《行测》试题（网友回忆版） 第21 题", "qid": 4630396, "level": "中等", "stem": "最近，某国医学协会发布了新版高血压防控指南，新版指南中将高血压“门槛”由以往的140/90毫米汞柱下调为130/80毫米汞柱。这意味着该国近半数人民可能血压超标，需改变生活习惯或吃药进行控制。有媒体认为，这是协会与医药公司的一场联合“阴谋”，为了售卖更多的降压药从而获取巨额利润。\n以下如果哪项为真，最能反驳该媒体的观点？", "options": ["该协会在世界范围内享誉盛名，曾多次在心血管疾病方面有重大的科学发现", "指南中认为因为标准改变而被判断成高血压的人无需服用药物", "该国的医药公司并未有计划加大降压药的生产", "该国人民普遍并不关注自己的血压状况"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：某国医学协会发布的新版高血压防控指南是协会与医药公司的一场联合“阴谋”，为了售卖更多的降压药从而获取巨额利润。\n论据：无。\n本题只有论点，没有论据，削弱优先考虑削弱论点，即证明此防控指南的发布不是一场“阴谋”，不能达到获取巨额利润的目的。\n第二步：逐一分析选项。\nA项：该项说的是该协会的地位和曾经的成就，而论点说的是防控指南的发布是为了获取巨额的利润，话题不一致，无法削弱，排除；\nB项：该项指出因指南中标准的改变而确定为高血压的人无需服用药物，说明新版高血压防控指南的发布不会让更多的人去购买药物，也就无法因此获取巨额利润，削弱论点，当选；\nC项：该项说的是医药公司没有计划加大降压药的生产，但产量不增加不代表销量不能增加，无法证明防控指南的发布不是为了获取巨额的利润，无法削弱，排除；\nD项：该项说的是该国人是否关注自己的血压状况，而论点说的是该防控指南发布的目的，话题不一致，无法削弱，排除。\n⇒ 正确答案为B。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}, {"type": "削弱论证", "from": "2016年423联考《行测》题（新疆兵团网友回忆版） 第28 题", "qid": 1796110, "level": "中等", "stem": "人们在社会生活中常会面临选择，要么选择风险小，报酬低的机会；要么选择风险大，报酬高的机会。究竟是在个人决策的情况下富于冒险性，还是在群体决策的情况下富于冒险性？有研究表明，群体比个体更富有冒险精神，群体倾向于获利大但成功率小的行为。\n以下哪项如果为真，最能支持上述研究结论？", "options": ["在群体进行决策时，人们往往会比个人决策时更倾向于向某一个极端偏斜，从而背离最佳决策", "个体会将其意见与群体其他成员相互比较，因其想要被其他群体成员所接受及喜爱，所以个体往往会顺从群体的一般意见", "在群体决策中，很可能出现以个体或子群体为主发表意见、进行决策的情况，使群体决策为个体或子群体所左右", "群体决策有利于充分利用其成员不同的教育程度、经验和背景，他们的广泛参与有利于最高决策的科学性"], "answer": ["A"], "explain": "第一步：找到论点论据。\n论点：群体比个体更具有冒险精神，群体倾向于获利大但成功率小的行为。\n本题没有论据。\n第二步：逐一分析选项。\nA选项：群体作决策时比个人更容易走极端，将群体决策和个人决策做比较，解释了群体决策与个人决策之间存在差距的原因，可能会导致群体倾向于获利大但成功率小的行为，有一定的加强作用；\nB选项：说的是在群体中个体会偏向于群体的一般意见，论证的是个体在群体中是坚持自己独特意见还是屈众，跟论题不一致，所以排除；\nC选项：群体决策可能会被个体或者子群体所主导，也就是说群体决策可能和个体决策是一样的，而不是比个体决策更具有冒险精神，有削弱的意思，排除；\nD选项：题干中没有涉及到决策的科学性与成功率，为无关选项，排除。\nB、D两项为无关选项，C项有削弱的意思，只有A项有一定的加强作用，比较而言只能选A。\n⇒ 正确答案为A。", "point": "考论点与论据之间的缺口；削弱 = 让结论更不可能成立。最强的是「拆桥」——切断论据与论点之间的联系。", "method": "先找论点和论据；优先看能不能切断二者联系，其次看能不能举反例、否定论据。", "tip": "注意分清「削弱论点」与「削弱论据」；话题不一致的选项是无关项，不能选。"}]}, {"set": 106, "cat": "前提假设", "title": "专项挑战 · 前提假设", "date": "", "session": "", "items": [{"type": "前提假设", "from": "2017年上海市行政执法类考试《行测》试题（网友回忆版） 第22 题", "qid": 5690294, "level": "中等", "stem": "近来，网络订餐平台上频频出现问题。对此，北京、上海、浙江等地出台了网络餐饮监管规定，严格审查食品经营者许可证和送餐人员健康情况。这些规定的出台将使这些地区网络订餐平台存在的问题获得有效解决。\n得出上述结论需要以        项为前提。", "options": ["只要有了监管规定，就一定能够严格执行", "网络订餐平台作为新生事物，难免会出现一些问题", "与传统餐饮业相比，对网络订餐平台的监管难度更大", "网络订餐平台存在的问题主要是食品经营者许可证和送餐人员健康情况的问题"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：北京、上海、浙江等地出台了网络餐饮监管规定，严格审查食品经营者许可证和送餐人员健康情况。这些规定的出台将使这些地区网络订餐平台存在的问题获得有效解决。\n论据：无。\n本题只有论点，没有论据，且提问为“前提”，加强优先考虑必要条件。\n第二步：逐一分析选项。\nA项：只要有了监管规定，就一定能够严格执行，但由于不确定网络订餐平台存在的问题具体是什么，进而无法判断严格审查食品经营者许可证和送餐人员健康情况，能否有效解决问题，无法加强，排除；\nB项：网络订餐平台作为新生事物，难免会出现一些问题，没有提及出台的规定能否解决问题，为无关项，无法加强，排除；\nC项：对网络订餐平台的监管难度更大，没有提及出台的规定能否解决问题，为无关项，无法加强，排除；\nD项：如果该项不成立，即网络订餐平台存在的问题并不在于食品经营者许可证和送餐人员的健康情况，那么尽管出台了审查食品经营者许可证和送餐人员健康情况的规定，也是无法解决问题的，因此该项是论点成立的必要条件，可以加强，当选。\n⇒ 正确答案为D。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2018年四川省公务员录用考试《行测》题（下半年）（网友回忆版） 第25 题", "qid": 2280985, "level": "中等", "stem": "为了解对学校食堂的满意度，某大学进行了一项“我最满意的食堂”评比活动。通过让学生对食堂的饭菜质量、价格、服务态度、卫生状况等10项指标进行评分来反映其对食堂的满意度，学生给每个评分指标赋以1到10分的某一个分值，然后计算出10项评分指标的平均得分，从而得出学生对食堂的满意度。\n实施这一项评比活动需要假设的前提是：\nⅠ.对饭菜质量、服务态度等指标的评价可以用数字来表达\nⅡ.上述10项指标对学生来说同等重要\nⅢ.该大学的每个学生都参与了这次评比活动", "options": ["仅Ⅰ", "仅Ⅱ", "仅Ⅰ和Ⅱ", "Ⅰ、Ⅱ和Ⅲ"], "answer": ["C"], "explain": "第一步：找出论点和论据。\n论点：通过让学生对食堂的饭菜质量、价格、服务态度、卫生状况等10项指标进行评分，计算出10项评分指标的平均得分，从而得出学生对食堂的满意度。\n论据：无。\n第二步：逐一分析选项。\nⅠ：对饭菜质量、服务态度等指标的评价可以用数字来表达，是使得评价可以量化的前提条件，若指标评价不能用数字表达，那么题干论点提到的通过指标的平均得分得到学生对食堂的满意度就无法实现，该项是评比活动需要假设的前提。\nⅡ：10项指标同等重要，这使得学生的评判可以公平公正进行，若10项指标不是同等重要，那么通过评价指标的平均分得到对食堂的评价就不科学，也无意义，该项是评比活动需要假设的前提。\nⅢ：参加评比活动的学生人数和评比最后得到的结果无必然联系，不是该评比活动需要假设的前提。\n实施这一项评比活动需要假设的前提是Ⅰ和Ⅱ。\n⇒ 正确答案为C。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2019年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第24 题", "qid": 2374756, "level": "中等", "stem": "某研究机构对3个品牌的老年代步车进行安全性碰撞实验。实验表明，这3个品牌的代步车都无法在发生交通事故时保护驾驶人。该机构因此认为：老年代步车十分危险，政府应该禁止代步车上路，引导老年人驾驶普通汽车。\n以下选项最无法支持上述论断的是（    ）。", "options": ["代步车的价格一般低于普通汽车", "这3个品牌的代步车市场占有率极高", "使用代步车的老人普遍拥有汽车驾驶资格", "安全性是决定代步车能否上路行驶的首要因素"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：老年代步车十分危险，政府应该禁止代步车上路，引导老年人驾驶普通汽车。\n论据：某研究机构对3个品牌的老年代步车进行安全性碰撞实验。实验表明，这3个品牌的代步车都无法在发生交通事故时保护驾驶人。\n本题论据为一个对3个品牌的老年代步车的实验结果，论点是老年代步车十分危险以及政府应该如何去做，论据论点话题不一致，那么加强方式可以用搭桥，另外，也可以围绕论点中“引导老年人驾驶普通汽车”这个话题进行补充论据加强，还可以对于题干实验的有效性进行说明。\n第二步：逐一分析选项。\nA项：代步车的价格在论据论点均未提及，属于无关选项，无法加强，当选；\nB项：说明实验中选取的品牌具有代表性，可以得到论点中老年代步车十分危险的普遍性结论，搭桥进行加强，可以加强，排除；\nC项：若使用代步车的老人普遍没有汽车驾驶资格，说明这些老年人无法驾驶汽车，也就不能得出政府应该引导老年人驾驶普通汽车，为使论点成立的必要条件，可以加强，排除； \nD项：指出安全性和代步车能否上路行驶之间有必然联系，即可以得到代步车安全性不好，应该禁止上路行驶，在论点和论据之间搭桥，可以加强，排除。\n本题为选非题，⇒ 正确答案为A。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第17 题", "qid": 5510276, "level": "中等", "stem": "分散的农户经营不成规模，已经远远不能适应各个城市群规模化、批量化的农产品需求，也限制了农民收入的提高。如果不解决农户的组织化这个问题，就无法推广农业机械化、规模化，也无法降低农业的经营成本。因此，可以通过推进农户的组织化，让现有的农民实现增产增收。\n以下选项如果为真，最能支持上述论断的是（    ）。", "options": ["当前分散的农户是农村的农业经营主体", "机械化、规模化种植能有效实现农业增产", "推广农业机械化、规模化不需要花费较长时间", "实现农业机械化生产后，劳动力投入将有所减少"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：可以通过推进农户的组织化，让现有的农民实现增产增收。\n论据：如果不解决农户的组织化这个问题，就无法推广农业机械化、规模化，也无法降低农业的经营成本。\n论据讨论的是实现农户的组织化有利于推广农业机械化，规模化，降低农业的经营成本，论点说的是推进农户的组织化，让现有的农民实现增产增收，论据和论点话题不一致，加强优先考虑搭桥，即在“推广农业机械化、规模化，降低农业的经营成本”和“让农民实现增产增收”之间建立联系。\n第二步：逐一分析选项。\nA项：论点讨论的是农户的组织化与农民增产增收的关系，而该项说的是分散的农户是农村的农业经营主体，不明确推进农户的组织化后是否可以让农民增产增收，无法加强，排除；\nB项：该项说的是机械化、规模化种植能有效实现农业增产，即在推广农业机械化、规模化和让农民实现增产之间建立联系，为搭桥项，可以加强，当选；\nC项：论点讨论的是农户的组织化与农民增产增收的关系，该项说的是推广农业机械化、规模化不需要花费较长时间，话题不一致，无法加强，排除；\nD项：论点讨论的是农户的组织化与农民增产增收的关系，该项说的是实现农业机械化生产后对于劳动力投入的影响，话题不一致，无法加强，排除。\n⇒ 正确答案为B。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2016年吉林省公务员录用考试《行测》题（甲级） 第24 题", "qid": 2021872, "level": "中等", "stem": "所有工作都是有报酬的，而任何有报酬的工作都是可以用金钱衡量的。因此，公益劳动不是工作。\n上述论证的成立，必须补充以下哪项前提？", "options": ["公益劳动不可以用金钱衡量", "有报酬的工作不是公益劳动", "公益劳动不是有报酬的工作", "一切有报酬的工作都是工作"], "answer": ["A"], "explain": "第一步：找出论点和论据。论点：公益劳动工作。论据：①工作报酬；②报酬金钱衡量。第二步：论点和论据之间存在跳跃，需要搭桥补充前提条件。A项：公益劳动金钱衡量，根据①和②进行逆否等价推理，即金钱衡量报酬工作，可以得出结论：公益劳动工作，保留；B项：报酬公益劳动，即公益劳动报酬，根据①进行逆否等价推理，即报酬工作，可以得出结论：公益劳动工作，保留；C项：公益劳动报酬，根据①进行逆否等价推理，即报酬工作，可以得出结论：公益劳动工作，保留；D项：报酬工作，没有提到公益劳动，排除。对比A、B、C三项，题干的论证包括两个推理即“工作报酬；报酬金钱衡量”A项是这两个推理存在的必要条件，而B项和C项只是一部分推理的必要条件（忽略了“报酬金钱衡量”），因此A项更加符合题意，当选。而且，B项和C项属于同构选项，表述的意思完全一致，即B项对C项就对，C项对B项就对，因此同构选项应该排除。⇒ 正确答案为A。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2019年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第23 题", "qid": 2374755, "level": "中等", "stem": "近几年，“痕迹管理”在基层工作中被广泛应用。其优势在于通过保留下来的文字、图片等工作资料，有效还原服务群众的工作情况，供日后查证。某地基层单位为了强化“痕迹管理”，极大增加了工作资料在考核分值中的比重。显然，这样的做法会使当地基层干部将大量精力耗费在保留工作痕迹上。\n以下最可能是上述论证潜在假设的是（    ）。", "options": ["基层干部对于考核分值十分重视", "有些基层干部对群众缺少服务意识", "“痕迹管理”要求保留所有工作痕迹", "绝大多数基层干部缺少“留痕”条件"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：这样的做法（增加工作资料在考核分值中的比重）会使当地基层干部将大量精力耗费在保留工作痕迹上。\n论据：无。\n提问为“假设”，且不存在论据，优先考虑必要条件。\n第二步：逐一分析选项。\nA项：指出基层干部对于考核分值十分重视，如果基层干部对于考核分值不重视，那么增加工作资料在考核分值中的比重并不会使得基层干部耗费大量精力来保留工作痕迹，因此是论点成立的必要条件，当选；\nB项：基层干部对群众缺少服务意识和论点中基层干部将大量精力耗费在保留工作痕迹上无关，属于无关项，并不是论点成立的必要条件，排除；\nC项：保留所有工作痕迹是在说“痕迹管理”的要求，说明这一做法的复杂性，但无法说明基层干部是否会将大量精力耗费在保留工作痕迹上，并不是论点成立的必要条件，排除；\nD项：绝大多数基层干部缺少“留痕”条件，那么可能不会耗费精力在保留工作痕迹上，有一定的削弱力度，并不是论点成立的必要条件，排除。\n⇒ 正确答案为A。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2019年山东省选调应届优秀高校毕业生到基层工作考试《行测》试卷（网友回忆版） 第37 题", "qid": 2376912, "level": "中等", "stem": "在考古学研究中判断人类遗骸的性别对于了解古代社会结构具有重要意义。科学家发现牙釉质中含有釉原蛋白，编码这种蛋白的基因恰好位于性染色体——X染色体和Y染色体上，研究者认为，用牙齿判定遗骸性别的方法可用于考古研究。\n以下哪项如果为真，最能支持上述论证？", "options": ["牙齿是古人类遗骸中最容易找到并且保存最完好的部分", "儿童遗骸的骨骼没有明显的性别差异", "人类遗骸的性别比例与当时人类社会的性别比例大致相同", "测量某些骨骼特征如骨盆的结构通常可以直接判定性别"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：用牙齿判定遗骸性别的方法可用于考古研究。\n论据：科学家发现牙釉质中含有釉原蛋白，编码这种蛋白的基因恰好位于性染色体——X染色体和Y染色体上。\n问最能支持上述论证，优先考虑搭桥，其次考虑必要条件。论点讨论的是用牙齿判断遗骸的性别，论据讨论的是牙齿相关的基因在性染色体上，论点论据说的是一回事，所以考虑必要条件。\n第二步：逐一分析选项。\nA项：牙齿是古人类遗骸中最容易找到并且最完整的部分，是科学家对可以通过牙齿判定遗骸性别的必要条件，可以加强，当选；\nB项：论点讨论的是牙齿，B项说的是儿童骨骼，牙齿不是骨骼，为无关选项，排除；\nC项：遗骸的性别比例与当时人类社会的性别比例大致相同，不是牙齿是判定遗骸性别的方法的必要条件，排除；\nD项：论点说的是通过牙齿判断性别，而该项说的是通过骨盆的结构来判定性别，话题不一致，排除。\n⇒ 正确答案为A。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2018年浙江省公务员录用考试《行测》题（B类）（网友回忆版） 第37 题", "qid": 2144574, "level": "中等", "stem": "数百年来，人类一直想要对深海生物有更深的认识。各地流传的神话故事中，几乎都会讲到深海巨怪。希腊、挪威等国的许多有关人类探索海域的神话中，随处可见海蛇、大乌贼、巨鲨的存在。由此可见，在深海中，确实有不为人知的海底巨型生物。\n以下哪项如果为真，最能加强上述论证？", "options": ["深海是传说中动物的最佳住所", "神话有很多是虚构的，并不可信", "深海相机确实拍摄到了生活在深海中的生物", "不同地域神话中的相似内容往往是现实的真实反映"], "answer": ["D"], "explain": "第一步：找出论点和论据。\n论点：在深海中，确实有不为人知的海底巨型生物。\n论据：希腊、挪威等国的许多有关人类探索海域的神话中，随处可见海蛇、大乌贼、巨鲨的存在。\n第二步：逐一分析选项。\nA项：深海是传说中动物的最佳住所，“传说中”并不能说明在深海中是否真的有这些动物，不能加强，排除；\nB项：神话有很多是虚构的，并不可信，说明不能由论据中的神话传说推出论点中的真实情况，可以削弱，无法加强，排除；\nC项：深海相机确实拍摄到了生活在深海中的生物，这些生物是否是“不为人知的海底巨型生物”不确定，不能加强，排除； \nD项：不同地域神话中的相似内容往往是现实的真实反映，也就是说由希腊、挪威等国的神话中都有海蛇、大乌贼、巨鲨，可以推出现实深海中很可能有这些不为人知的海底巨型生物，将论点和论据进行了搭桥，可以加强，当选。\n⇒ 正确答案为D。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2018年新疆生产建设兵团面向社会招录公务员考试《行测》题（网友回忆版） 第24 题", "qid": 2247199, "level": "中等", "stem": "有科学家对澳大利亚约35亿年前的一块岩石中的微化石进行了分析，他们用二次离子质谱仪，从每个微化石中的碳-13中分离出碳-12，并测量出两者比例，他们发现这些化石包含一个原始生物群体。因此，他们推测生命早在35亿年前就已在地球上出现。\n要得到上述结论，需要补充的前提是：", "options": ["早在43亿年前，地球上就有液态水存在", "微化石的碳-13和碳-12比例具有生物学和代谢功能的特征", "甲烷是氧气出现之前地球早期大气的重要成分，是简单有机物", "在格陵兰和加拿大都发现了三十几亿年前的疑似生物遗迹的石头"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：生命早在35亿年前就已经在地球上出现。\n论据：科学家从35亿年前微化石中的碳-13中分离出碳-12，并测量出两者比例，发现这些化石包含一个原始生物群体。\n论点论据话题一致，都在说35亿年前存在生命/生物群体，要支持可以优先考虑找一个必要条件，即没他不行的条件。\n第二步：逐一分析选项。\nA项：该项说的是43亿年前出现了液态水的存在，题干讨论的是碳-13和碳-12的比例与生命是否存在之间的关系，话题不一致，无法加强，排除；\nB项：假如微化石中的碳-13和碳-12比例不具有生物学和代谢功能的特征，就不能通过二者的比例得出微化石中有原始生物群体，因此是题干成立的必要条件，当选；\nC项：该项说的是甲烷的出现时间和特性，题干讨论的是碳-13和碳-12的比例与生命是否存在之间的关系，话题不一致，无法加强，排除；\nD项：该项说的是三十几亿年前出现疑似生物遗迹的石头，到底是不是35亿年以前不确定，且只是疑似，并不能够证明一定存在生命，无法加强，排除。\n⇒ 正确答案为B。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2022年国家公务员录用考试《行测》题（副省级网友回忆版） 第35 题", "qid": 4637420, "level": "中等", "stem": "不同的读者在阅读时，会对文章进行不同的加工编码，一种是浏览，从文章中收集观点和信息，使知识作为独立的单元输入大脑，称为线性策略；一种是做笔记，在阅读时会构建一个层次清晰的架构，就像用信息积木搭建了一个“金字塔”，称为结构策略。做笔记能够对文章的主要内容进行标注，因此与单纯的浏览相比，做笔记能够取得更优的阅读效果。\n要使上述论证成立，还需基于以下哪一前提？", "options": ["阅读效果的好坏取决于能否在阅读时抓住要点", "用浏览的方式进行阅读属于知识加工的线性策略", "做笔记涉及到了更加复杂的认知加工过程", "与线性策略相比，结构策略能够让学习提升速度"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：与单纯的浏览相比，做笔记能够取得更优的阅读效果。\n论据：做笔记能够对文章的主要内容进行标注。\n本题提问为“基于以下哪一前提”，优先考虑搭桥和必要条件。论点讨论的是做笔记能够取得更优的阅读效果，而论据讨论的是做笔记是在标注文章的主要内容，二者话题不一致，优先考虑搭桥，即建立“标注文章主要内容”和“阅读效果”的联系。\n第二步：逐一分析选项。\nA项：该项说阅读效果的好坏取决于能否在阅读时抓住要点，将“标注文章主要内容（抓住要点）”和“阅读效果”建立了联系，属于搭桥项，可以加强，当选；\nB项：该项说的是浏览阅读属于知识加工的线性策略，而论点讨论的是笔记阅读的效果，话题不一致，无法加强，排除；\nC项：该项说做笔记涉及到了更加复杂的认知加工过程，但通过这个复杂的认知加工过程能否取得更优的阅读效果并不明确，属于不明确项，无法加强，排除；\nD项：该项说结构策略比线性策略更能提升学习速度，强调的是两种阅读方式在提升学习速度方面的差异，而论点讨论的是阅读效果，话题不一致，无法加强，排除。\n⇒ 正确答案为A。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2018年北京市公务员录用考试《行测》题（网友回忆版） 第8 题", "qid": 2137038, "level": "中等", "stem": "高栓患有假性近视。为了使其视力恢复到正常状态，李大夫要求高栓停止打网络游戏。\n为使李大夫的要求具有说服力，必须假设以下哪项？", "options": ["假性近视患者打网络游戏，将严重影响其视力恢复到正常状态", "打网络游戏是引起假性近视的主要原因", "李大夫经验丰富，他治愈了90%以上前来就诊的假性近视患者", "假性近视如果不及时缓解将导致真性近视"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：李大夫要求高栓停止打网络游戏。\n论据：高栓患有假性近视，想要恢复到正常状态。\n第二步：逐一分析选项。\nA项：说明假性近视患者打网络游戏会影响视力的恢复，即在网络游戏和恢复视力之间进行搭桥，当选；\nB项：说明打网络游戏是引起假性近视的原因，但是并不意味着不打游戏就能使视力恢复到正常情况，排除；\nC项：只说到李大夫经验丰富，治愈率高，但是并没有说明网络游戏和恢复视力之间的关系，不是必须的假设，排除； \nD项：只说到假性近视不及时治疗所带来的后果，但是并没有说明网络游戏和恢复视力之间的关系，属于无关选项，排除。\n⇒ 正确答案为A。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2019年上海市公务员录用考试《行测》题（B类）（网友回忆版） 第28 题", "qid": 2295282, "level": "中等", "stem": "爱因斯坦对人类最大的贡献就是相对论的提出，它是人类研究宇宙强有力的工具。爱因斯坦通过相对论进行过宇宙质量的计算，结果发现宇宙的质量总和竟然为零。爱因斯坦认为，宇宙在大爆炸后产生的物质有正反两种形式，反物质和正物质完全相反，而且正、反物质质量相等。但科学家在宇宙中只发现了很小量的反物质，那大部分的反物质去哪里了？如果它们不存在于宇宙中，爱因斯坦通过相对论的计算也不会发现宇宙质量总和为零。但是宇宙的质量为零，这说明反物质应该还是存在于宇宙当中。\n下列      项是以上论述所假设的前提。", "options": ["只存在一个宇宙", "爱因斯坦通过相对论的计算是正确的", "人类如果不能利用反物质的巨大能量，就不能进行星际探索", "科学家在实验室中发现了反物质，而且现在也可以在实验室制造一部分反物质"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：大部分的反物质应该还是存在于宇宙当中。\n论据：爱因斯坦通过相对论进行过宇宙质量的计算，结果发现宇宙的质量总和竟然为零。爱因斯坦认为，宇宙在大爆炸后产生的物质有正反两种形式，反物质和正物质完全相反，而且正、反物质质量相等。但科学家在宇宙中只发现了很小量的反物质。\n第二步：逐一分析选项。\nA项：该项说的是宇宙的数量，与论点说的大部分的反物质是否存在于宇宙中无关，是无关项，排除；\nB项：只有爱因斯坦相对论的计算是正确的，才能通过宇宙的质量总和为零，得知反物质应大量存在，是结论成立的必要条件，当选；\nC项：该项说的是反物质能力的作用与应用，与论点说的大部分的反物质是否存在于宇宙中无关，是无关项，排除；\nD项：科学家可以在实验室发现、制造出反物质，说明反物质是存在的，但无法证明宇宙中是否存在大部分的反物质，无法加强，排除。\n⇒ 正确答案为B。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2018年广东省公务员录用考试《行测》题（县级、乡镇统一卷）（网友回忆版） 第23 题", "qid": 2185092, "level": "中等", "stem": "近年来，某公司生产的汽车发生了几起严重的交通事故，有人认为这是因为该汽车在设计上存在缺陷导致的。对此，该公司坚决否认设计上存在缺陷，理由是根据这几起交通事故的分析报告，发生事故时，司机都存在酒后驾驶或疲劳驾驶的情况。\n以下哪项为真，最不能支持该公司的观点？", "options": ["该公司一直宣称自己的产品安全性能良好", "该公司所依据的交通事故分析报告真实可靠", "喝酒和疲劳都会严重影响司机驾驶时的判断力", "经过对事故车辆的检测，并没有发现存在设计缺陷"], "answer": ["A"], "explain": "第一步：找出论点和论据。\n论点：该公司汽车设计上不存在缺陷。\n论据：根据这几起交通事故的分析报告，发生事故时，司机都存在酒后驾驶或疲劳驾驶的情况。\n第二步：逐一分析选项。\nA项：公司一直宣称自己产品安全性能良好，但是无法判断设计是否存在缺陷，属于无关选项，无法加强，当选；\nB项：该报告真实可靠是得出论点的必要条件，补充论据，可以加强，排除；\nC项：喝酒和疲劳驾驶会影响驾驶人的判断力，解释了造成交通事故的原因不是设计问题而是酒驾，补充论据，可以加强，排除； \nD项：对事故车辆检测之后发现没有设计缺陷，补充论据，可以加强，排除。\n本题为选非题，⇒ 正确答案为A。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2017年422联考《行测》题（江西卷） 第33 题", "qid": 2050904, "level": "中等", "stem": "广告的目的是为了说服消费者相信他们购买的商品物有所值，没有哪个商家会故意强调自己的产品价格高。以下哪项如果为真，最能加强上述论断？", "options": ["消费者认为便宜无好货，好货不便宜", "广告能激发消费者的购买欲", "广告能说服消费者去购买价格便宜的商品", "广告能说服消费者去购买质量好的商品"], "answer": ["D"], "explain": "本题论点重点强调的是：广告的目的是为了让消费者认为物有所值，弱化了价格问题。本题只有论点没有论据，无法搭桥，因此要通过补充论据的方式来加强，找一个能够解释为什么广告会让消费者认为商品物有所值的选项，或者举例子说明广告的目的确实如论点所说，因此正确答案应该跟物有所值紧密相关，而不侧重价格问题。\n第一步：找出论点和论据。\n论点：广告的目的是为了说服消费者相信他们购买的商品物有所值，没有哪个商家会故意强调自己的产品价格高。\n论据：无。\n第二步：逐一分析选项。\nA项：论点讨论的是广告的目的是什么，而A选项是消费者个人的消费观念，与广告的目的无关，不能加强，排除；\nB项：广告能激发消费者的购买欲，“购买欲”与“物有所值”无明显关联性，属于无关选项，不能加强，排除；\nC项：广告能说服消费者去购买价格便宜的商品，但是不能确定这些商品是否物有所值，不能加强，排除；\nD项：题干中的观点是让消费者买物有所值的商品，本质就是在说服消费者买质量好的商品，该选项补充了论据，进一步解释说明了“物有所值”的意义，可以加强，当选。\n⇒ 正确答案为D。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}, {"type": "前提假设", "from": "2019年四川省选调优秀大学毕业生到基层工作《行测》试题（网友回忆版） 第30 题", "qid": 2377241, "level": "中等", "stem": "从老百姓反映的情况来看，我国各区域的民生服务水平有了很大提高。在民生服务中，树立了尊重人、理解人、关心人、依靠人的治理理念，将“为民作主”转变为“由民作主”；同时形成了普惠民生的治理格局，让民生工作惠及到千家万户。可见，我国的区域治理能力和成效大幅度提高。\n上述论证成立需要补充以下哪项作为前提？", "options": ["精准服务是提升民生服务水平的切入点", "民生服务水平是衡量我国区域治理能力和成效的重要指标", "区域治理能力和成效的提升是国家治理体系和治理能力现代化的重要内容", "“由民作主”机制的形成标志着政府从注重“管理能力”向注重“治理能力”转变"], "answer": ["B"], "explain": "第一步：找出论点和论据。\n论点：我国的区域治理能力和成效大幅度提高。\n论据：从老百姓反映的情况来看，我国各区域的民生服务水平有了很大提高。在民生服务中，树立了尊重人、理解人、关心人、依靠人的治理理念，将“为民作主”转变为“由民作主”；同时形成了普惠民生的治理格局，让民生工作惠及到千家万户。\n本题提问为“前提”，论点讨论的是区域治理能力和成效，而论据讨论的是各区域的民生服务水平提高，所以论点论据话题不一致，要想加强，优先考虑搭桥，即在区域治理能力和成效与民生服务水平之间建立联系。\n第二步：逐一分析选项。\nA项：论点说的是区域治理能力和成效大幅度提高，该项说的是精准服务是提升民生服务水平的切入点，话题不一致，无法加强，排除；\nB项：民生服务水平是衡量我国区域治理能力和成效的重要指标，说明民生水平提高，我国的区域治理能力和成效也会提高，在论点和论据之间建立联系，属于搭桥项，当选；\nC项：强调区域治理能力和成效的提升是国家治理体系和治理能力现代化的重要内容，并没有提及论点中区域治理能力和成效是否提高，话题不一致，无法加强，排除；\nD项：强调“由民作主”机制的形成标志着政府从注重“管理能力”向注重“治理能力”转变，没有提及论点中的区域治理能力和成效，属于无关选项，排除。\n⇒ 正确答案为B。", "point": "前提假设是加强的特殊题型：问「还需假设什么」，正确答案是论证成立必需的「隐含前提」（往往是搭桥）。", "method": "用「否定代入法」：把选项否定后代入，若结论不成立，则该选项就是必要前提。", "tip": "前提不等于加强，前提必须「没它不行」；太强或太弱的选项都排除。"}]}, {"set": 107, "cat": "原因解释", "title": "专项挑战 · 原因解释", "date": "", "session": "", "items": [{"type": "原因解释", "from": "2019年420联考《行测》题（吉林乙级）（网友回忆版） 第22 题", "qid": 2376639, "level": "中等", "stem": "一直以来，人们都认为工作与家庭的冲突主要困扰的是女性。但最近一项匿名问卷调查的结果显示，男性和女性在工作与家庭冲突的困扰方面，几乎不存在差异，这和大众的认知截然相反。\n下列哪项如果为真，不能解释上述矛盾现象：", "options": ["相对于女性，男性更希望展示强者面貌，更不愿公开谈论自己的困扰", "相对于女性，男性更可能会在匿名的调查问卷中坦率描述自己的困扰", "相对于男性来说，女性更愿意向他人倾诉自己的困扰，从而缓解压力", "相对于没有孩子的女性，有孩子的女性家庭事务干扰工作的程度更高"], "answer": ["D"], "explain": "第一步，找出题干矛盾。\n大众认知中都认为工作与家庭的冲突主要困扰的是女性，但匿名调查问卷结果显示男性与女性在工作与家庭冲突的困扰方面几乎不存在差异。\n第二步，逐一分析选项。\nA项：说明相对于女性，男性即使有困扰也不愿意公开谈论，导致在大众认知中会认为在工作与家庭的冲突中男性受到的困扰较少，可以解释题干矛盾，排除；\nB项：说明在匿名调查问卷中，男性更有可能会坦率说出自己的困扰，所以问卷结果会显示出男性与女性在工作与家庭的冲突困扰方面的差异较小，可以解释题干矛盾，排除；\nC项：说明女性会比男性更愿意向他人倾诉自己的困扰，导致在大众认知中会认为在工作与家庭的冲突中女性受到的困扰较多，可以解释题干矛盾，排除；\nD项：对比的是有没有孩子的女性之间的家庭与工作的困扰程度，没有提到男性与女性之间的比较，无法解释题干矛盾，当选。\n本题为选非题，⇒ 正确答案为D。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2025年天津市公务员录用考试《行测》题（网友回忆版） 第27 题", "qid": 10297131, "level": "中等", "stem": "为了解市民对话剧的爱好程度，J市连续三年进行了网络调查。调查结果表明，近三年，宣称自己每月都会去看话剧演出的市民人数占市民总人数的比例不断增加，由5%增加到15%。然而，分析J市大剧院的票房数据，却发现近三年来，来剧院观看话剧的观众人数其实是减少的。\n以下哪项如果为真，不能解释上述现象？", "options": ["近三年里，市民当中不是每月都会去看话剧的人数量在减少", "为了吸引更多的观众，该市的话剧演出票价比之前调低了一些", "J市有很多年轻人会选择去小剧场或学校的礼堂观看话剧", "剧本杀、密室逃脱等新兴娱乐项目在一定程度上分流了话剧的观众"], "answer": ["B"], "explain": "第一步：找出题干矛盾。\n近三年，宣称自己每月都会去看话剧演出的市民人数占市民总人数的比例不断增加。然而，分析J市大剧院的票房数据，却发现近三年来，来剧院观看话剧的观众人数其实是减少的。\n第二步：逐一分析选项。\nA项：选项指出近三年里，市民当中不是每月都会去看话剧的人数量在减少，也就是说，近三年，虽然每月都会去看话剧的人数量在增加，但看话剧的人员构成还包括“不是每月都会去看话剧的人”，这些人的数量在减少，可以解释为什么宣称自己每月都会去看话剧演出人数的比例增加，但来剧院观看话剧的观众人数其实是减少的，可以解释题干矛盾，排除；\nB项：选项指出为了吸引观众，该市的话剧演出票价比之前调低了，调低价格理论上应该吸引更多的顾客，不能解释为什么宣称自己每月都会去看话剧演出人数增加，但去剧院看话剧的观众人数其实是减少的，不能解释题干矛盾，当选；\nC项：选项指出J市很多年轻人会选择去小剧场或学校的礼堂观看话剧，说明小剧场和礼堂分流了来大剧院看话剧的观众，解释了为什么宣称自己每月都会去看话剧演出人数的比例增加，但来“大剧院”观看话剧的观众人数却在减少，可以解释题干矛盾，排除；\nD项：选项指出剧本杀、密室逃脱等新兴娱乐项目在一定程度上分流了话剧的观众，解释了为什么来剧院观看话剧的观众是减少的，相比较AC项，D项解释得比较片面，但是B项更不能解释，对比择优，D项优于B项。\n本题为选非题，⇒ 正确答案为B。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2017年广州市公务员录用考试《行测》题（单考区卷） 第17 题", "qid": 2045642, "level": "中等", "stem": "为解决城市交通拥堵问题，某地政府不断拓宽和新建公路，但是这些新拓建的路面很快就被车流淹没，交通拥堵状况不但没有缓解，反而越来越严重。\n以下哪项如果为真，则最无助于解释这一现象？（  ）", "options": ["新拓建公路的最低限速比其他公路要高一些", "新拓建公路会诱使人们更多地购买和使用汽车", "新拓建公路会导致沿线居民区和商业区增加", "人们偏向于在新拓建的公路上行驶"], "answer": ["A"], "explain": "第一步：找出题干矛盾。\n此题属于现象解释类题目，需要解释的矛盾现象为某地政府为解决城市交通问题不断拓宽和新建公路，但是交通拥堵状况不但没有缓解，反而越来越严重。即拓宽和新建公路为什么不能缓解交通问题。\n第二步：逐一分析选项。\nA项：新拓建公路的最低限速比其他公路要高一些，指明速度的问题，到底最低限速是多少也不明确，最低限速和交通拥堵之间的关系也不明确，不能解释题干矛盾现象，为正确答案，当选；\nB项：新拓建公路会诱使人们更多地购买和使用汽车，说明路增加了汽车也增加了，可能会导致交通拥堵，能解释题干矛盾现象，排除；\nC项：指出新建公路使得沿线居民区和商业区增加，住的人多，人流量大，可能导致交通拥堵，能解释题干矛盾现象，排除；\nD项：人们偏向于在新拓建的公路上行驶，说明新拓建公路上的车流量大，可能会导致交通拥堵，能解释题干矛盾现象，排除。\n本题为选非题，⇒ 正确答案为A。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2019年上海市公务员录用考试《行测》题（B类）（网友回忆版） 第27 题", "qid": 2295280, "level": "中等", "stem": "当今社会，二维码支付方式在餐饮门店、超市、便利店等线下小额支付场景中得到了广泛的应用。但在条码生成机制和传输过程中仍存在风险隐患，也引发了不少涉及支付安全风险的案件。\n下列      项能够对题干中的结论起到解释的作用。", "options": ["静态条码容易被篡改或变造，容易携带木马或病毒", "线下扫码支付为用户带来了便捷的消费体验", "商家利用线下扫码支付可以帮助自身提高经营收益", "采用先进的令牌技术进行变异处理后，可以保护真实卡号信息"], "answer": ["A"], "explain": "第一步：找出题干结论。\n “在条码生成机制和传输过程中仍存在风险隐患，引发了不少涉及支付安全风险的案件。”\n第二步：逐一分析选项。\nA项：该项解释了二维码支付隐患是由于静态条码容易被篡改或变造，容易携带木马或病毒，可以解释题干结论，当选；\nB项：该项讨论的是线下扫码支付为用户带来了便捷的消费体验，题干讨论的是二维码支付会带来安全隐患，讨论话题不一致，不能解释题干结论，排除；\nC项：该项讨论的是商家利用线下扫码支付可以帮助自身提高经营收益，题干讨论的是二维码支付会带来安全隐患，讨论话题不一致，不能解释题干结论，排除；\nD项：该项讨论的是提高移动支付安全性的方法，不能解释为什么存在风险隐患，不能解释题干结论，排除。\n⇒ 正确答案为A。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2016年吉林省公务员录用考试《行测》题（甲级） 第27 题", "qid": 2021894, "level": "中等", "stem": "最近，上海长宁区开了一个新超市。从外表看，这是一间典型的中国连锁超市。满满当当的货架塞满了各种食品和日用品。然而所有店内商品，虽然外观与普通商品没有分别，里面却是空的，包装上找不到拆封的痕迹，来访者也无处得知商品是如何被“掏空”的。虽然这是一家卖空的超市，却人气爆棚。\n以下哪项如果为真，最能解释上述现象：", "options": ["部分购买者不知道里面是空的", "空包装实际上是一种艺术商品", "有一些空包装是恶作剧的道具", "超市引发日常消费文化的探讨"], "answer": ["B"], "explain": "此题属于原因解释类题目，需要解释的现象为：超市内塞满了各种被“掏空”的食品和日用品，但是却人气爆棚。\nA 项：解释了部分购买者不知道里面是空的，出现了购买行为，但是不能解释为什么人气爆棚，排除。\nB 项：空包装实际上是一种艺术商品，既解释了超市内塞满了各种被“掏空”的食品和日用品，是艺术品超市，又解释了人气爆棚的原因，是因为大家都来购买艺术品，解释了矛盾的两个方面，当选。\nC 项：有一些空包装是恶作剧的道具，无法解释题干中矛盾，排除。\nD 项：超市引发日常消费文化的探讨，无法解释题干中矛盾，排除。\n⇒ 正确答案为B。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2023年深圳市考公务员录用考试《行测》试题（网友回忆版） 第12 题", "qid": 5521264, "level": "中等", "stem": "每年的夏秋之际，大草原上的牛羚都会成群结队向北方迁徙，形成非常壮观的画面。研究表明，生物运动受生存和繁殖驱动，而牛羚并非是出于繁衍的目的进行大规模迁徙，因为迁徙途中危险重重，不是被狮子猎豹追击，就是被鳄鱼埋伏，幼小牛羚往往是第一目标，非洲大草原干湿季分明，促成了特别显著的草类生长的季节性分布，显然，追逐肥美的草木和丰富的水源才是牛羚一年一度迁徙活动的推动力。\n上述论证采用的论证方法是（    ）。", "options": ["论证一个普遍规律，并用来说明某一种特殊情况", "通过反例推翻一个一般性结论", "在对某种现象的两种可供选择的解释中，通过排除其中的一种，来确定另一种", "通过对发生机制的适当描述，支持关于某个可能发生现象的假说"], "answer": ["C"], "explain": "第一步：分析题干论证过程。\n题干先是指出了牛羚迁徙的现象，提出了“生物运动受生存和繁殖驱动”的理论，其中有两个因素。紧接着又论述“牛羚并非是出于繁衍的目的进行大规模迁徙”，并解释了为什么不是出于繁衍的目的，最后得出“追逐肥美的草木和丰富的水源才是牛羚一年一度迁徙活动的推动力”，即牛羚迁徙是受生存驱动。\n第二步：逐一分析选项。\nA项：题干给的普遍规律是“生物运动受生存和繁殖驱动”，但题干并没有去论证这个规律，而是直接默认它是正确的，与题干论证结构不一致，排除；\nB项：题干并没有举反例，与题干论证结构不一致，排除；\nC项：由第一步的分析可知，题干采用的论证方法是，在对某种现象的两种可供选择的解释（生存和繁殖）中，通过排除其中的一种（繁殖），来确定另一种（生存），与题干论证结构一致，当选；\nD项：题干并不是一个可能发生的现象，牛羚迁徙是实际发生的现象，与题干论证结构不一致，排除。\n⇒ 正确答案为C。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2026年广东省公务员录用考试《行测》题（网友回忆版） 第8 题", "qid": 18643985, "level": "中等", "stem": "某种水毛茛是A市特有的野生植物，对水质要求极高，其仅生长于清澈、流动的水体中，因此被誉为优良水质的“指示物种”。2023年受特大暴雨影响，A市某自然保护区内的水毛茛大面积消失，其所依赖的自然条件难以自行恢复，因而面临灭绝的风险。但在今年春季，有人发现，该自然保护区内重新出现了这种水毛茛，且群落规模远超以往。\n下列选项如果为真，最能解释上述现象的是（    ）。", "options": ["这种水毛茛的分布范围已扩展至与自然保护区相邻的多处水域", "即使经历了暴雨，该自然保护区的水质仍然优于周边河流水域", "这种水毛茛同时具备有性繁殖和无性繁殖的能力，繁殖能力较强", "近两年，通过水系修复等人工措施，该自然保护区的水质大幅提高了"], "answer": ["D"], "explain": "第一步：找出题干矛盾。\n水毛茛对水质要求极高，2023年受特大暴雨影响，A市某自然保护区内的水毛茛大面积消失，其所依赖的自然条件难以自行恢复，因而面临灭绝的风险。但在今年春季，有人发现，该自然保护区内重新出现了这种水毛茛，且群落规模远超以往。\n第二步：逐一分析选项。\nA项：选项指出水毛茛的分布范围已扩展至与自然保护区相邻的多处水域，而题干讨论的是本该灭绝的水毛茛为何又重新出现在了该自然保护区内，无法解释题干矛盾，排除；\nB项：选项指出该自然保护区的水质优于周边河流水域，即使该自然保护区的水质比周边好，但如果未达到水毛茛生存的最低要求，水毛茛仍然无法存活，无法解释题干矛盾，排除；\nC项：选项指出水毛茛繁殖能力较强，但如果未改善水质，再强的繁殖能力也无法让已濒临灭绝的水毛茛重新出现，无法解释题干矛盾，排除；\nD项：选项指出近两年，通过水系修复等人工措施，该自然保护区的水质大幅提高，而水质大幅提高不仅能让水毛茛重现，还能为其提供更优越的生长环境，使得群落规模远超以往，可以解释题干矛盾，当选。\n⇒ 正确答案为D。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2018年广东省公务员录用考试《行测》题（县级、乡镇统一卷）（网友回忆版） 第21 题", "qid": 2185085, "level": "中等", "stem": "某市举行春季音乐节系列活动，其中一项活动首次邀请了某知名交响乐团前来该市演出，该市交响乐爱好者对此十分期待。考虑到该乐团的影响力，主办方预计为期两天的交响乐团演出将“一票难求”。但开始售票后发现，实际情况并非如此。\n以下哪项为真，最能解释这一情况？", "options": ["音乐节的其他活动吸引了许多观众", "交响乐未能被该市大部分群众所接受", "音乐节活动期间该市一直为阴雨天气", "此次交响乐团演出门票价格过高"], "answer": ["D"], "explain": "第一步：找出题干矛盾。\n该市交响乐爱好者十分期待某知名交响乐团前来演出，预计交响乐团演出将“一票难求”，但开始售票后发现实际情况并非如此。\n第二步：逐一分析选项。\nA项：音乐节的其他活动吸引了许多观众，可能会影响交响乐团演出门票的销售，可以解释题干的矛盾，保留；\nB项：交响乐未能被该市大部分群众所接受，说明该市喜欢交响乐的人少，但是题干已明确指出“交响乐爱好者”对此十分期待，与不接受交响乐的群众占比无关，排除；\nC项：阴雨天气可能会对交响乐的售票有一定的影响，可以解释题干的矛盾，保留；\nD项：演出门票价格过高在一定程度上会影响到门票的销售，可以解释题干的矛盾，保留。\n比较A、C、D三项，D项从交响乐团演出自身的角度解释了原因；\nA项中的音乐节其他活动吸引了许多观众，但是题干中说该市交响乐爱好者对交响乐团的演出十分期待，所以其他活动对于交响乐团演出门票的销售影响并不明确，排除；\nC项中的阴雨天气只是可能对售票情况产生一定的影响，但是题干并没有明确的说明交响乐的爱好者会因为阴雨天气而放弃看演出，不明确项，排除；\nD项是从交响乐团演出自身的角度出发，门票价格过高这一因素会影响到门票销量，一部分交响乐爱好者自然会因为门票价格过高而放弃观看演出，因此相比之下，D项解释力度更强，当选。\n⇒ 正确答案为D。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2021年国家公务员录用考试《行测》题（副省级网友回忆版） 第38 题", "qid": 2719409, "level": "中等", "stem": "近年来，国家从药品生产、流通和销售各环节发力，频频出台降低药价的相关政策。但是，让不少患者感到疑惑的是，一方面是国家降低药价的政策不断出台，另一方面却是诸多常用药价格不断上涨。\n以下哪项如果为真，最能解释上述现象？", "options": ["价格下降的药品占大多数，价格上涨的药品占少数，因此从整体上来说，药品价格仍然是下降了", "常用进口药的需求增多，相关政策无法控制此类药品的价格上涨", "国家虽然出台了降低药价的政策，但是其影响要经过―段时间才能显现出来", "降低药价的政策可以有效控制药品市场中因制药原料涨价而导致的药价上涨"], "answer": ["B"], "explain": "第一步：找出题干矛盾。\n一方面是国家降低药价的政策不断出台，另一方面却是诸多常用药价格不断上涨。\n第二步：逐一分析选项。\nA项：指出整体来说药品价格下降，没有说明为什么政策出台的同时诸多常用药价格却上涨，不能解释题干矛盾，排除；\nB项：指出国家降低药价的政策无法控制常用进口药的价格上涨，又因为这些药的需求在增多，所以这些药物的价格在国家降低药价的政策不断出台时却不断上涨，可以解释题干矛盾，当选；\nC项：指出降低药价的政策影响要经过一段时间才能显现，可以解释政策出台后短时间药价不下降的情况，但不能解释为什么政策出台的同时诸多常用药价格却上涨，不能解释题干矛盾，排除；\nD项：指出降价政策可以有效控制因原料涨价而涨价的现象，说明政策有效，不能解释为什么政策出台的同时诸多常用药价格却上涨，不能解释题干矛盾，排除。\n⇒ 正确答案为B。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2026年甘肃公务员录用考试《行测》题（网友回忆版） 第33 题", "qid": 16070027, "level": "中等", "stem": "儿童安全座椅可以在碰撞发生或急停时防止或最大限度减轻对儿童的伤害，同时还能有效降低非碰撞场景下的伤害风险，例如车辆突发制动、行驶过程中车门意外开启等。在2021年修订的《中华人民共和国未成年人保护法》中，儿童安全座椅首次被写入全国性法律。然而，该法实行至今，儿童安全座椅的配备情况仍不容乐观。\n以下哪项如果为真，最能解释上述现象？", "options": ["目前，在0至6岁儿童的家长中，仅有67.53%的受访者为儿童配备了儿童安全座椅", "有调查显示，大部分已配备儿童安全座椅的家庭，仅在长途出行时才会使用该座椅", "行车时“大人抱着孩子最安全”“车速慢就没事”等错误观念在人们心目中根深蒂固", "上述法律规定应当配备儿童安全座椅，这是当前对未使用儿童安全座椅的行为作出处罚的主要依据"], "answer": ["C"], "explain": "第一步：找出题干矛盾。\n儿童安全座椅能有效保护儿童，且已被写入全国性法律，但儿童安全座椅的配备情况仍不容乐观。\n第二步：逐一分析选项。\nA项：指出儿童安全座椅的配备比例数据，仅说明配备情况不容乐观，并未解释出现这一现象的原因，不能解释题干矛盾，排除；\nB项：指出大部分已配备儿童安全座椅的家庭，仅在长途出行时才会使用该座椅，讨论的是已配备儿童安全座椅的家庭的使用情况，而题干讨论的是儿童安全座椅的配备情况，话题不一致，不能解释题干矛盾，排除；\nC项：指出行车时“大人抱着孩子最安全”“车速慢就没事”等错误观念在人们心目中根深蒂固，直接说明即使法律有规定、产品有作用，很多人仍因观念问题不主动配备，能够解释为何儿童安全座椅的配备情况仍不容乐观，可以解释题干矛盾，当选；\nD项：指出该法律是对未使用儿童安全座椅的行为作出处罚的主要依据，但不能解释为何该法实行至今，儿童安全座椅的配备情况仍不容乐观，不能解释题干矛盾，排除。\n‌⇒ 正确答案为C。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2022年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第28 题", "qid": 4673187, "level": "中等", "stem": "多年来，甲国居民消耗的主要粮食中，有80%以上由本国生产；而乙国居民消耗的主要粮食中有六成以上依赖进口。但经过调查发现，当国际大米价格出现上涨时，甲国国内的大米价格涨幅明显高于乙国。\n下列选项如果为真，最能解释这一现象的是（    ）。", "options": ["甲国主要粮食进口以大米为主，乙国主要粮食进口以小麦为主", "乙国居民对食物品质和口感的要求比甲国居民更高", "乙国的粮食产量比甲国更加稳定", "与甲国相比乙国人口少、收入高，粮食支出占其收入的比重更低"], "answer": ["A"], "explain": "第一步：找出题干矛盾。\n甲国的主要粮食80%由本国生产，乙国的主要粮食六成以上依赖进口，但当国际大米价格出现上涨时，甲国的大米价格涨幅明显高于乙国。\n第二步：逐一分析选项。\nA项：指出甲国主要进口大米，而乙国主要进口小麦，因此国际大米价格上涨对甲国的大米价格影响更大，解释了为什么当国际大米价格出现上涨时，甲国的大米价格涨幅明显高于乙国，可以解释题干矛盾，当选；\nB项：指出甲、乙两国对食物品质和口感的要求存在差别，与国际大米价格对两国大米价格的影响无关，不能解释题干矛盾，排除；\nC项：指出乙国的粮食产量比甲国稳定，即使甲国的粮食产量发生变化，也无法判断是增加还是减少，更无法判断变化幅度是多少，而乙国的主要粮食进口比例仍然很大，无法解释为什么当国际大米价格出现上涨时，甲国大米价格涨幅明显要高于乙国，不能解释题干矛盾，排除；\nD项：指出甲、乙两国居民的粮食支出占收入的比重情况，与国际大米价格对两国大米价格的影响无关，不能解释题干矛盾，排除。\n⇒ 正确答案为A。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2023年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第27 题", "qid": 5510273, "level": "中等", "stem": "小王经营着一家打印店，他发现，店内员工都很忙，大部分精力都花在了文件排版上。为了节省人力，他给店里的电脑安装了能自动完成常规排版操作的新款软件。然而，软件安装几个月后，店内员工反而更忙了。\n以下选项如果为真，最能解释这一现象的是（    ）。", "options": ["部分文档有特殊的排版要求，依然需要人工操作完成", "能自动排版文档后，该店的文印装订等业务量也因此大涨", "新软件操作有一定难度，员工需要接受培训才能熟练掌握", "安装软件后，该店并没有相应地调整排版和打印的收费标准"], "answer": ["B"], "explain": "第一步：找出题干矛盾。\n小王为了节省人力，给店里的电脑安装了能自动完成常规排版操作的新款软件，但软件安装几个月后，员工反而更忙了。\n第二步：逐一分析选项。\nA项：该项只能说明有些工作离不开人工操作，不能解释在安装了能自动完成常规排版操作的新款软件后，员工为什么变得更忙了，不能解释题干矛盾，排除；\nB项：该项说明能自动排版文档后，自动排版的工作效率虽然得到了提高，但该店文印装订等业务量大涨，增加了员工的工作量，进而能够解释员工更忙了的现象，可以解释题干矛盾，当选；\nC项：该项只能说明使用自动排版软件前需要对员工进行一定的培训，才能更好地使用，不能解释在安装了能自动完成常规排版操作的新款软件后，员工为什么变得更忙了，不能解释题干矛盾，排除；\nD项：该项说明安装了能自动完成常规排版操作的新款软件后，该店价格没有进行调整，与题干中的矛盾无关，不能解释题干矛盾，排除。\n⇒ 正确答案为B。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2019年国家公务员录用考试《行测》题（副省级网友回忆版） 第31 题", "qid": 2264333, "level": "中等", "stem": "所有的幼儿园都面临同一个问题：就是对于那些在幼儿园放学之后不能及时来接孩子的家长，幼儿园老师除了等待别无他法，因此许多幼儿园都向晚接孩子的家长收取费用。然而，有调查显示，收取费用后晚接孩子的家长数量并未因此减少，反而增加了。\n以下哪项如果为真，最能解释上述调查结果？", "options": ["收费标准太低，对原本经常晚来接孩子的家长没有太大的约束力", "有个别家长对收费行为不满，有时会故意以晚接孩子的行为来抗议", "有些家长因工作忙碌，常常不能及时来接孩子", "收费后，更多的家长认为即使晚来接孩子也不必愧疚，只要付费即可"], "answer": ["D"], "explain": "第一步：找出题干矛盾。\n通过收取费用的方式让家长早接孩子，但是收费后晚接孩子的家长数量不减反增。\n第二步：逐一分析选项。\nA项：收费低对原本晚接孩子的家长无影响，可以解释为什么人数没有减少，但是无法解释为什么人数增加，不能解释题干矛盾，排除；\nB项：该项说的是个别家长抗议收费而晚来接孩子，但是无法解释清楚为什么晚接孩子的家长数增加了，不能解释题干矛盾，排除；\nC项：该项解释了家长晚来接孩子的原因，与题干幼儿园收费无关，不能解释题干矛盾，排除；\nD项：该项说明幼儿园对晚接孩子进行收费后，将这种行为合理化，更多的家长心安理得的晚来接孩子，可以解释为什么晚接孩子的人不减反增，当选。\n⇒ 正确答案为D。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2021年广东省公务员录用考试《行测》题（县级卷）（网友回忆版） 第28 题", "qid": 3018792, "level": "中等", "stem": "某在线教育机构在网上推出了一个面向中小学生的直播课，这个直播课在试播时组织了很多中小学生和家长免费观看，获得了很高的评价，但是在正式播出后，在线收看的人数并不理想。\n下列选项最不能解释这一现象的是（    ）。", "options": ["正式的直播课程需要付费观看", "该直播课的正式播出时间不合理", "该直播课为系列课程，共计开设10节", "其他在线教育机构推出了许多同类型的直播课"], "answer": ["C"], "explain": "第一步：找出题干矛盾。\n某在线教育机构面向中小学生的直播课免费试播时获得了很高的评价，但是在正式播出后，在线收看的人数并不理想。\n第二步：逐一分析选项。\nA项：指出正式的直播课程需要付费观看，而试播是免费的，有些人只想观看免费课，不想付费观看，可以解释题干矛盾，排除；\nB项：指出直播课的正式播出时间不合理，有人会因此无法及时观看直播课程，导致正式播出后在线收看的人数并不理想，可以解释题干矛盾，排除；\nC项：指出直播课的数量是10节，但课程数量不能说明为什么正式直播的在线观看人数不理想，不能解释题干矛盾，当选；\nD项：指出其他机构推出同类型在线直播课，有一部分观看试播的用户可能会选择其他机构的课程，因此正式播出后，在线收看的人数并不理想，可以解释题干矛盾，排除。\n本题为选非题，⇒ 正确答案为C。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}, {"type": "原因解释", "from": "2019年青海省法院、检察院录用考试《行测》题 第28 题", "qid": 2440259, "level": "中等", "stem": "当前，银行面临着这样一个问题，就是对于那些在贷款后不能及时还贷的客户，银行除了不断通过各种形式催款别无他法。因此许多银行都向不能及时还贷的客户收取滞纳金。但有关调查表明，收取滞纳金后不能及时还贷的客户数量不但未减少，反而增加了。\n以下哪项如果为真，最能解释上述调查结果？", "options": ["收取滞纳金后，更多的客户认为即使不及时还贷也不必内疚，只要支付滞纳金就行", "有个别客户对收取滞纳金的行为不满，有时会故意不及时还贷来抗议", "有些客户因为生活压力大，常常不能及时还贷", "收取滞纳金的金额太低，对原本经常不及时还贷的客户没有太大的压力"], "answer": ["A"], "explain": "第一步:找出题干的矛盾之处。\n题干的矛盾之处在于银行向不能及时还贷的客户收取滞纳金，但收取滞纳金后不能及时还贷的客户数量不但未减少，反而增加了。\n第二步:逐一分析选项。\nA项:收取滞纳金后，客户认为不必内疚，所以更多的客户可能不及时还贷，可以解释，当选;\nB项:个别客户的不满并不能解释为何不能及时还贷的客户数量增加了，不能解释，排除;\nC项:有些客户不能及时还款，是一个长期性的行为，并不能解释这次收取滞纳金为何使得不能及时还贷的客户数量增加了，不能解释，排除;\nD项:对原本经常不能还贷的客户的影响，并不能解释为何不能及时还贷的客户数量增加了，不能解释，排除。\n⇒ 正确答案为A。", "point": "考用常识和逻辑找「表面上矛盾」现象背后的合理原因。", "method": "先明确矛盾的两端（为什么A却B）；正确选项须能同时解释两端，只解释一端的直接排除。", "tip": "选项必须能解释「全部的事实」；只说明一半的是典型陷阱。"}]}, {"set": 108, "cat": "结论推出", "title": "专项挑战 · 结论推出", "date": "", "session": "", "items": [{"type": "结论推出", "from": "2022年四川下半年公务员录用考试《行测》试题（网友回忆版） 第30 题", "qid": 5408577, "level": "中等", "stem": "一个人过去的生活和个人信息会形成长期记忆储存在脑中，当某个和往事相关的线索再次出现时，便会触发对该事件的回忆。有研究者做了这样的实验：分别展示某些气味、画面和文字，请受试者以此为线索回忆自己的往事，并说出这些往事发生时的年龄。统计结果发现，哪怕参与测试的人已经步入老年，他们通过气味回忆起的往事大部分发生在人生的头十年，而通过画面或文字回忆起的大多是10~20岁时发生的事。\n由此可以推出：", "options": ["受试者的嗅觉记忆比画面文字记忆更加久远", "受试者在回忆往事时会忽略20岁以后的记忆", "受试者在10岁以前对画面或文字缺乏感知力", "嗅觉所唤起的记忆更清晰、情感体验更浓烈"], "answer": ["A"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干中指出“通过气味回忆起的往事大部分发生在人生的头十年，而通过画面或文字回忆起的大多是10~20岁时发生的事”，“人生的头十年”要早于“10~20岁”，可以推出受试者的嗅觉记忆比画面文字记忆更久远，当选；\nB项：题干中没有涉及到20岁以后的记忆，无中生有，排除；\nC项：题干中指出“通过气味回忆起的往事大部分发生在人生的头十年，而通过画面或文字回忆起的大多是10~20岁时发生的事”，但是无法得到受试者10岁以前对画面或文字的感知力如何，无中生有，排除；\nD项：题干中没有涉及到嗅觉唤起的记忆与画面、文字唤起的记忆之间的清晰度和情感体验的比较，无中生有，排除。\n⇒ 正确答案为A。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2017年422联考《行测》题（山东卷） 第32 题", "qid": 2049922, "level": "中等", "stem": "车主信息会影响汽车保费，比如年龄较大、女性、高学历的车主，保费相对较低，25岁以下的年轻人保费较高，出过交通事故的车主保费高；另外，汽车价格、车型、车龄甚至颜色都会影响保险费用。高价新车不一定比低价旧车保费贵，因为新车、好车的防盗装置、安全装置多；特定车型颜色鲜艳的车保费贵，比如爱开红色跑车的人，性格比较奔放，开车时相对不太谨慎。\n根据上文，最有可能推出的是：", "options": ["有过交通事故的红色跑车的18岁男性车主所交的保费高", "开豪华跑车的女性要比开平价汽车的男性所交的保费高", "大龄、有研究生学历并购买新车的女性车主所交的保费低", "谨慎细致的车主要比奔放活泼的车主所交的保费低"], "answer": ["A"], "explain": "本题为日常结论题，题干中提到了几个会影响汽车保费的因素：车主年龄、性别、学历、是否出过交通事故、汽车价格、车型、车龄、颜色、车主性格。逐一分析选项：\nA项：有过交通事故、红色跑车、18岁、男性均是保费较高的因素，保留；\nB项：女性的保费较男性低，且豪华跑车的颜色不确定，因此豪华跑车和平价汽车保费高低不确定，不能推出，排除；\nC项：大龄、研究生学历、女性都是保费较低的因素，但新车的保费较高还是较低无法确定，因此不能推出，排除；\nD项：根据题干最后一句话可知，奔放活泼是保费较高的一个因素，保留。\n比较选项，A项涉及的因素最多，因此最有可能推出的是A项。\n⇒ 正确答案为A。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2016年天津选调生选拔考试 综合知识试卷（精选） 第9 题", "qid": 2262777, "level": "中等", "stem": "经验告诉我们：天空的薄云，往往是天气晴朗的象征；那些低而厚密的云层，常常是阴雨风雪的预兆。\n因此：", "options": ["天空的云总是由薄变厚，反复无常", "风雪来临之前总要给人以暗示", "从天空云层的变化就可以预料天气的变化", "经验是人们在实践中积累起来的，没有十分把握"], "answer": ["C"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干没有提到天空的云总是由薄变厚，反复无常，无中生有，排除；\nB项：题干提到了天气晴朗和阴雨风雪时两种云层的变化，而选项只提到风雪，且给人暗示的到底是什么，表意不明，无法推出，排除；\nC项：从天空云层的变化就可以预料天气的变化，是对题干的整体概括，可以推出，当选；\nD项：题干谈论的是不同云层的变化可预示天气，并未提到经验、实践及是否有把握的问题，无中生有，排除。\n⇒ 正确答案为C。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2020年黑龙江省公务员录用考试《行测》试题（网友回忆版） 第34 题", "qid": 2616160, "level": "中等", "stem": "一项心理学研究认为，出身经济层次最低家庭的人中年后出现代谢综合征的比例最高，无论他们获得多大成就都是如此。该研究同时发现代谢综合征虽与童年生活状况有关，但该群体中那些拥有慈母的人不容易出现该综合征。究其原因，慈母具有同情心，会告诉孩子如何应对压力并鼓励他们健康饮食，保持良好生活方式。因此，我们在现实中可以设计一套方案，指导母亲教育孩子如何应对压力、健康生活和掌控命运。\n由此可以推出：", "options": ["设计针对母亲的指导方案，有助于降低特定群体出现代谢综合征的比例", "因为缺少母爱，出身经济层次最低家庭的人出现代谢综合征的比例最高", "因为父亲不教导孩子保持良好生活方式，所以父亲对孩子的健康没影响", "出身经济层次最低家庭的人，童年如受到慈母呵护，中年后身体很健康"], "answer": ["A"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：根据题干可知拥有慈母的人不容易出现代谢综合征，慈母可以教育孩子如何应对压力、健康生活和掌握命运，因此，设计一套方案指导母亲，可帮助出身经济最低的人群降低出现代谢综合征的几率，当选；\nB项：由文段可以得出，出身经济层次最低家庭的人中年后出现代谢综合征的比例最高，慈母可以降低这一比例，但是并没有提到出现代谢综合征是否是因为缺少母爱，无法推出，排除；\nC项：父亲不教导孩子保持良好生活方式，题干中并未出现父亲相关描述，属于无中生有，排除；\nD项：出身经济层次最低的人群，受到慈母呵护，只能得出代谢综合征的情况不易出现，并不能说明身体整体的健康情况，属于偷换概念，排除。\n⇒ 正确答案为A。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2018年黑龙江省公务员考试（公检法）题（网友回忆版） 第30 题", "qid": 2188418, "level": "中等", "stem": "月球潮汐力与地球上的地震、海啸、火山爆发等自然灾害存在明显相关性的说法是可疑的，因为每年自然灾害很多，而“超级月亮”每14个月才一次，即便考虑月球经过近地点，每个月也只有一次。部分学者会找出一些和“超级月亮”出现时间相隔不远的灾害来论证，这显然缺乏证据支撑。也忽略了大量事例，比如月球在远地点前后发生的灾害。基于大量关于地震和月球关系数据的研究表明，地震发生频率和月球经过近地点没有统计上的相关性，因此说月球潮汐力会引发地震显然缺乏可靠证据。\n由此可以推出：", "options": ["月球潮汐力与月球在远地点前后发生的地震具有相关性", "月球潮汐力与月球经过近地点发生的地震具有因果关系", "月球潮汐力与地震之间的关系需要在时间和空间上综合分析", "地震触发机制有多种因素，但月球潮汐力的作用效果较明显"], "answer": ["C"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干中指出“部分学者会找出一些和‘超级月亮’出现时间相隔不远的灾害来论证”，这显然缺乏证据支撑。也忽略了大量事例，比如“月球在远地点前后发生的灾害”，说明月球潮汐力与月球在远地点发生地震之间没有必然关系，无法推出，排除；\nB项：题干中指出“地震发生频率和月球经过近地点没有统计上的相关性”，而选项中说二者是因果关系，无法推出，排除；\nC项：题干中指出“‘超级月亮’每14个月才一次”，“地震发生频率和月球经过近地点没有统计上的相关性”，分别从时间和空间的角度说明月球潮汐力与地震等灾害之间没有相关性，那么要想证明月球潮汐力与地震之间的关系也需要在时间和空间上综合分析，可以推出，当选；\nD项：题干中指出“月球潮汐力会引发地震显然缺乏可靠证据，”而选项中说明月球潮汐力是地震的触发机制效果较明显,与题干意思相反，无法推出，排除。\n⇒ 正确答案为C。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2016年江苏省公务员录用考试《行测》题（C类） 第25 题", "qid": 1791836, "level": "中等", "stem": "城市是一个生命体，一座历史文化名城，她的寿命长达千百年，印证她寿命的年轮也定会有千百条。作为城市年轮的历史文化遗产是绝对不能破坏或丢弃的，破坏或丢弃城市的年轮，就是自毁城市特色。而一座城市只有保持其固有特色，才能拥有核心竞争力。\n根据以上陈述，可以得出以下哪项？", "options": ["只有保护好历史文化遗产，历史文化名城才能拥有核心竞争力", "只有拥有核心竞争力，一座城市才能保护好其历史文化遗产", "如果保护好历史文化遗产，一座城市就能拥有其核心竞争力", "如果历史文化遗产被破坏或丢弃，历史文化名城就会失去其生命力"], "answer": ["A"], "explain": "第一步：翻译题干。①破坏或丢弃历史文化遗产自毁城市特色；②拥有核心竞争力保持其固有特色。根据递推规则，得出：③破坏或丢弃历史文化遗产自毁城市特色核心竞争力。第二步：逐一分析选项。A项：拥有核心竞争力保护历史文化遗产，与题干命题③的逆否命题一致，可以推出，当选；B项：保护历史文化遗产拥有核心竞争力，是对条件①的否前，无法推出确定结论，排除；C项：保护历史文化遗产拥有核心竞争力，是对条件①的否前，无法推出确定结论，排除；D项：破坏或丢弃历史文化遗产历史文化名城就会失去其生命力，“生命力”在题干中没有提到，无法推出，排除。⇒ 正确答案为A。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2016年北京市公务员录用考试《行测》题 第7 题", "qid": 1752836, "level": "中等", "stem": "某国议员认为：“只要提高工人工资就会导致通货膨胀。如果发生通货膨胀，那么人民就会遭受损失。人民遭受损失，就会使政府失去人心。政府只有得人心，国家才能和谐稳定。”\n根据该议员的观点，以下除了哪项，均可以推出？", "options": ["只要提高工人工资，政府就会失去人心", "如果发生通货膨胀，政府就会失去人心", "提高工人工资，且政府得人心", "国家和谐稳定与提高工人工资不能并存"], "answer": ["C"], "explain": "第一步：翻译题干。①只要提高工资就通货膨胀：只要······就······，前推后：提高工资通货膨胀；②如果通货膨胀那么遭受损失：如果······那么······，前推后：通货膨胀遭受损失；③遭受损失就失去人心：······就······，前推后：遭受损失失去民心；④只有得民心国家才和谐稳定：只有······才······，后推前：和谐稳定得人心，根据逆否定理，可以得出：⑤失去人心不和谐稳定。第二步：逐一分析选项。A项：由①②③可得提高工资推出失去人心，正确；B项：由②③可得通货膨胀推出失去人心，正确；C项：由①②③可得提高工资推出失去人心，因此提高工资与得人心不可能同时出现，错误；D项：由①②③⑤可得提高工资不和谐稳定，故提高工资与和谐稳定不能共存，正确。本题为选非题，⇒ 正确答案为C。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2016年吉林省公务员录用考试《行测》题（乙级） 第19 题", "qid": 2022010, "level": "中等", "stem": "你为什么总是不高兴？因为你缺失信仰，人生失去了方向。也就失去了驾驭快乐的手段。导致很多人在幸福中选择了不快乐。同时，没有信仰就容易把价值观建立在一些外在事物上，甚至是相互比较上，仰望别人的成功，感觉自己的卑微；仰望别人的幸福，慨叹自己的不幸。比较别人的得志，愤然自己的失意；比较别人的快乐，放大自己的痛苦。\n如果以上陈述为真，则可以推出：", "options": ["不缺失信仰，就不会总是不高兴", "总是不高兴，说明一定缺失信仰", "有信仰，就不会把价值观建立在一些外在的事物上", "不把价值观建立在一些外在事物上，代表你有信仰"], "answer": ["D"], "explain": "本题为关联词推导题型。\n第一步，翻译题干。\n①缺失信仰（-信仰）→失去方向→失去快乐；②-信仰→价值观建立在一些外在事物上。\n第二步，逐一翻译选项并得出答案。\nA项：不缺失信仰→不会总是不高兴，即不缺失信仰→高兴，不缺失信仰是对①中前件的否定，否定前件无法得出任何确定性的结论，无法推出，排除；\nB项：不高兴→缺失信仰，不高兴即失去快乐，失去快乐是对①的肯后，肯定后件无法得出任何确定性的结论，无法推出，排除；\nC项：信仰→不会把价值观建立在一些外在事物上，此句与②有关联，是对②的前件的否定，否定前件无法得出任何确定性结论，无法推出，排除；\nD项：—价值观建立在一些外在事物上→信仰，是对②的后件的否定，否后必否前，能够从题干中推出，当选。\n⇒ 正确答案为D。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2019深圳市公务员录用考试《行测》题（网友回忆版） 第16 题", "qid": 2385155, "level": "中等", "stem": "世界近代三大数学猜想是费马猜想、四色猜想和哥德巴赫猜想。费马猜想的证明于1994年由英国数学家安德鲁·怀尔斯完成，且得到了数学界的认可；四色猜想的证明于1976年由美国数学家阿佩尔与哈肯借助计算机完成，但1981年数学家施密特发现了其中的错误；哥德巴赫猜想尚未解决，目前最好的成果——陈氏定理，乃1966年由中国数学家陈景润取得。\n由此可知（    ）。", "options": ["哥德巴赫猜想比费马猜想和四色猜想更难证明", "中国数学家在世界近代三大数学猜想的证明工作中成就最高", "哥德巴赫猜想和四色猜想尚待严格证明", "世界近代三大数学猜想的证明一定都能完成，只是时间问题"], "answer": ["C"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干指出了三大数学猜想的证明情况，但并没有对它们的证明难度进行比较，无法推出，排除；\nB项：针对哥德巴赫猜想，目前最好的成果是陈氏定理，但是不能说明中国数学家在世界近代三大数学猜想的证明工作中成就最高，无法推出，排除；\nC项：数学家施密特发现了之前四色猜想的证明存在错误，而哥德巴赫猜想尚未解决，所以哥德巴赫猜想和四色猜想尚待严格证明，可以推出，当选；\nD项：哥德巴赫猜想和四色猜想还没有被证明，所以近代三大数学猜想的证明是否一定都能完成，无法推出，排除。\n⇒ 正确答案为C。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2020年青海省公务员录用考试《行测》试题（B卷）（网友回忆版） 第7 题", "qid": 2616033, "level": "中等", "stem": "越是身处浮华的地方，我们越是希望能遇到一块心灵栖息地。虽然我们生活在一个商业化社会，但书店仍然是灵魂的慰藉之地。大到城市，小到商场，若能有一家文化味浓郁的书店，一定能让人们感受到不一样的氛围。书店入驻商场，这不仅能给商场带来客流，也能提升商场的品位。以书店融合阅读、休闲和其他文化产品的类似“文化商场”模式，更是可以在商场内部构建一个特别的文化链。\n如果以上论断为真，则下列说法正确的是：", "options": ["城市让人们感受到不一样的氛围，是因为拥有文化味浓郁的书店", "想要在商场内部构建一个特别的文化链，就不应忽视书店这一环", "因为书店提升了商场的品位，所以书店给商场带来了客流", "即便不是身处浮华的地方，我们也能遇到一块心灵栖息地"], "answer": ["B"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干中指出文化味浓郁的书店可以推出让人们感受到不一样的氛围，选项中说是因为有文化味浓郁的书店所以让人们感受到不一样的氛围，推出关系不等于因果关系，无法推出，排除；\nB项：根据题干最后一句话可知，书店可以在商场内部构建一个特别的文化链，选项中说想要在商场内部构建一个特别的文化链，不应该忽视书店这一环，是文段的同义替换，可以推出，当选；\nC项：题干中指出书店既给商场带来客流也提升了商场的品位，选项中说是因为书店提升了商场的品位所以给商场带来了客流，无法推出，排除；\nD项：题干说的是我们希望遇到心灵栖息地，选项说的是我们能否遇到心灵栖息地，属于偷换概念，无法推出，排除。\n⇒ 正确答案为B。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2016年江苏省公务员录用考试《行测》题（A类） 第22 题", "qid": 1789566, "level": "中等", "stem": "某学院共有42名员工，他们或者做教学科研工作，或者做行政工作。在该学院中，教授都不担任行政工作，而30岁以下的年轻博士都在做行政工作，学院中有不少人是从海外招聘来的，他们都具有博士学位，李明是该学院最年轻的教授，他只有29岁。\n根据以上陈述，可以得出以下哪项？", "options": ["该学院从海外招聘来的博士大多是教授", "该学院从海外招聘来的博士都不做行政工作", "该学院教授大多是30岁以上的海外博士", "​该学院有的教授不是从海外招聘来的"], "answer": ["D"], "explain": "第一步：翻译题干。①科研或行政；②教授行政；③30岁以下博士行政；④海外博士；⑤李明29岁教授。将②逆否和③可以递推出⑥：30岁以下且博士行政教授。第二步：逐一分析选项。A项：（大多）有的海外博士教授，④与“海外”“博士”相关，并未提及年龄问题，因此不能根据⑥推出海外博士是否为教授，排除。B项：题干中和“海外”有关的只有④海外博士，没有说明年龄问题，无法推出海外招聘来的博士是否做行政工作，排除。C项：题干中和“海外”有关的只有④海外博士，没有说明他们的年龄或职务，无法推出“教授大多是30岁以上的海外博士”，排除。D项：已知⑤李明29岁教授，而③30岁以下博士行政，否后必否前可知，行政30岁以下或博士，29岁是对“30岁以下”的否定，或关系否一推一，可知“博士”成立，说明李明教授不是博士。④海外博士，李明不是博士，否后必否前，说明李明教授不是海外招聘的，因此“有的教授不是从海外招聘来的”表述正确，当选。⇒ 正确答案为D。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2016年上海市行政执法类考试《行测》试题（网友回忆版） 第22 题", "qid": 5702231, "level": "中等", "stem": "随着市场经济的发展，越来越多的行业出现了产品的同质化现象。有学者认为：当消费者感到不同公司的同种产品并无本质差别时，各公司为了拉拢顾客，相互竞争，相互压价，使产品价格跌至最低，公司所能获得的利润也将最少。\n如果该学者的观点正确，那么可以推测：当各公司不断追逐最大化利益时会出现        的景象。", "options": ["在激烈的竞争中，小的公司逐渐被淘汰，从而形成行业垄断的格局", "每个参与竞争的公司都会向消费者强调自己的产品多么得与众不同", "各公司更愿意依靠降价来增加销量，而极少创新产品和提升服务", "公司间组成行业联盟，让消费者难以区分不同的产品，从而提升价格"], "answer": ["C"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干指出产品价格跌至最低，公司所能获得的利润也将最少，但没有提及利润降低是否会导致小的公司被淘汰，从而形成行业垄断的格局，无中生有，无法推出，排除；\nB项：题干指出消费者感到不同公司的同种产品并无本质差别时，各公司为了拉拢顾客，相互竞争，相互压价，但没有提及公司是否会向消费者强调自己的产品与众不同，无中生有，无法推出，排除；\nC项：题干指出各公司为了拉拢顾客，相互竞争，相互压价，即通过价格战来获取竞争优势，所以当不断追逐最大化利益时，各公司更愿意依靠降价来增加销量，而极少创新产品和提升服务，可以推出，当选；\nD项：题干没有提及各公司不断追逐最大化利益时是否会组成行业联盟，无中生有，无法推出，排除。\n注：C项后半段的“极少创新产品和提升服务”题干也没有提及，但是由于A、B、D项完全是无中生有，而C项前半段是题干重点强调的内容，对比择优。\n⇒ 正确答案为C。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2017年河南省公务员录用考试《行测》题（网友回忆版） 第30 题", "qid": 2136700, "level": "中等", "stem": "某学生考试作弊被学院监考老师发现。如果老师将此事向学校上报，这个学生会被学校开除；如果这个学生被开除，学院的年终考核会被一票否决。如果老师未将此事向学校上报，学生考试作弊现象将愈演愈烈。\n由此可以推出：", "options": ["如果学院的年终考核未被一票否决，则学生考试作弊现象将愈演愈烈", "如果学院的年终考核被一票否决，作弊现象不会愈演愈烈", "如果该学生被开除，说明老师已将此事向学校上报", "如果作弊现象愈演愈烈，说明该学生没有被开除"], "answer": ["A"], "explain": "第一步：翻译题干。①老师上报学生被开除年终考核被一票否决；②老师未上报作弊愈演愈烈。第二步：逐一分析选项。A项翻译：年终考核未被一票否决作弊愈演愈烈，否定了①的箭头后，否定箭头后必否定箭头前，可以推出老师未上报；再根据②可得，作弊愈演愈烈，选项可以推出，当选；B项翻译：年终考核被一票否决作弊不会愈演愈烈，肯定了①的箭头后，肯定箭头后得不到确定性的结论，排除；C项翻译：学生被开除老师上报，肯定了①的箭头后，肯定箭头后得不到确定性的结论，排除；D项翻译：作弊愈演愈烈学生没被开除，肯定了②的箭头后，肯定箭头后得不到确定性的结论，排除。⇒ 正确答案为A。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2023年重庆市选调优秀大学生到基层工作考试《行测》题 第28 题", "qid": 13871464, "level": "中等", "stem": "研究人员开展的一项研究发现，太空中飞行超过3个月的宇航员，即使回到地球一年后，还可能出现骨恢复不完全的迹象，但在宇宙飞行期间增加更多基于抗阻的锻炼，有助于减少骨量损失。\n基于上述研究，最有可能推出下列哪一论断成立？", "options": ["执行飞行任务时长越长的宇航员其整体胫骨密度恢复得越不完全", "执行飞行任务时长越长的宇航员其骨恢复量在回到地球一年后会更少", "飞行期间完成了更多硬拉训练的宇航员其中位胫骨失效载荷变化不大", "跳跃抗阻锻炼对腿部提供了高冲击动态负荷，会促进空间飞行任务中的骨形成"], "answer": ["D"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干未提及“飞行任务时长”与“整体胫骨密度恢复”之间的关系，无中生有，无法推出，排除；\nB项：题干只是说太空飞行超过3个月的宇航员回地球一年后可能出现骨恢复不完全的迹象，并未提及“飞行任务时长”与“骨恢复量在回到地球一年后会更少”之间的关系，无中生有，无法推出，排除；\nC项：题干与选项均没有说明“硬拉训练”是否为“基于抗阻的锻炼”，且“减少骨量损失”不确定是否与“中位胫骨失效载荷”有关，无法推出，排除；\nD项：题干最后一句指出“宇宙飞行期间增加更多基于抗阻的锻炼，有助于减少骨量损失”，该项中的“跳跃抗阻锻炼”属于“基于抗阻的锻炼”，而“促进空间飞行任务中的‘骨形成’”即有助于减少骨量损失，最有可能推出，当选。\n⇒ 正确答案为D。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}, {"type": "结论推出", "from": "2016年上海市行政执法类考试《行测》试题（网友回忆版） 第24 题", "qid": 5702234, "level": "中等", "stem": "工业博览会等各类展会常在我国各大城市举办，这使我们能够衡量本国的工业发展水平，在与西方一些具有强大工业实力和科技水平的国家交流、比较中补足我们的弱项。在展会中，这些国家的展馆因为实力水平更高而具有较大的吸引力，往往得到更多的关注。\n以下各项能从上文推出的是        。", "options": ["工业博览会增加了经济负担", "工业博览会对如美国、德国等产品优于发展中国家的发达国家更有利", "工业博览会是以先进工业为中心的展场，对工业水平落后的国家帮助十分有限", "通过工业博览会与发达国家的分析比较，能够大幅促进本国产品质与量的提升"], "answer": ["D"], "explain": "日常结论题，根据题干信息逐一分析选项。\nA项：题干没有提及工业博览会是否会增加经济负担，无中生有，无法推出，排除；\nB项：根据题干可知，我国能够在交流、比较中补足我们的弱项，西方一些具有强大工业实力和科技水平的国家的展馆则往往得到更多的关注，即发展中国家和发达国家都能够通过工业博览会有所收获，但题干不涉及二者的比较，无法判断工业博览会对哪类国家更有利，无中生有，无法推出，排除；\nC项：题干指出我国能够在与西方一些具有强大工业实力和科技水平的国家交流、比较中补足我们的弱项，选项所说“对工业水平落后的国家帮助十分有限”与题干不符，无法推出，排除；\nD项：题干指出我国能够在与西方一些具有强大工业实力和科技水平的国家交流、比较中补足我们的弱项，即通过工业博览会与发达国家的分析比较，能够大幅促进本国产品质与量的提升，可以推出，当选。\n⇒ 正确答案为D。", "point": "考从题干信息严格推出必然结论（归纳推理），正确答案必须由题干直接推出、不需额外假设。", "method": "逐项比对，看是不是「一定成立」；越贴近题干、越保守的表述越对。", "tip": "别选「推得过远」或加了题干没有的信息的选项；注意「所有/有些」的量词范围。"}]}, {"set": 109, "cat": "论证推理", "title": "专项挑战 · 论证推理", "date": "", "session": "", "items": [{"type": "论证推理", "from": "2018年云南省选调生录用考试《行测》试题（网友回忆版） 第24 题", "qid": 2187573, "level": "中等", "stem": "少壮不努力，老大徒伤悲∶惜时∶奋斗", "options": ["假作真时真亦假，无为有处有还无∶清醒∶智慧", "天生我材必有用，千金散尽还复来∶自信∶豁达", "苔花如米小，也学牡丹开∶自我∶认真", "它山之石，可以攻玉∶谦虚∶谨慎"], "answer": ["B"], "explain": "第一步：判断题干词语间逻辑关系。\n少壮不努力，老大徒伤悲，是指年轻力壮的时候不奋发图强，到了老年，悲伤也没用了。这句诗表达了要惜时、奋斗的思想，诗句和后两个词是对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：假作真时真亦假，无为有处有还无，是指把假的当成真的，时间久了假的就被认为是真的，而真的被认为是假的，把不存在的东西说成是存在的东西时，那捏造的事实甚至比存在的事实更显得真实，反过来也是如此。这句诗说的是真实和虚假之间的关系，并没有表达出清醒、智慧的思想，与题干逻辑关系不一致，排除；\nB项：天生我材必有用，千金散尽还复来，是指上天生下我，一定有需要用到我的地方，金钱用尽了，这些散失去的东西以后依然会归来。这句诗表达了要自信、豁达的思想，诗句和后两个词是对应关系，与题干逻辑关系一致，当选；\nC项：苔花如米小，也学牡丹开，是指哪怕那如米粒一般微小的苔花，丝毫也不自惭形秽，依然像那美丽高贵的牡丹一样，自豪地盛开。这句诗表达的意思是自强、顽强，并没有表达出自我、认真的思想，与题干逻辑关系不一致，排除；\nD项：它山之石，可以攻玉，是指别的山上的石头，可以琢磨玉器。这句诗比喻能帮助自己改正缺点的人或意见，可以表达出谦虚的思想，但是和谨慎没有关系，与题干逻辑关系不一致，排除。\n⇒ 正确答案为B。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2017年北京市公务员录用考试《行测》题 第15 题", "qid": 2030994, "level": "中等", "stem": "雨果说：“多建一所学校，就少建一座监狱。”马克·吐温说：“你每关闭一所学校，你就必须开设一座监狱。”在他们看来，教育能够减少犯罪。有学者认为，近年来，随着教育的大规模扩大，学历程度越高，犯罪率越低。\n以下哪项如果为真，最能反驳该学者的观点？", "options": ["2015年，某高校一名本科生杀死自己的母亲，事后潜逃", "学历越高的人，对各项法律条文规定就越了解，就越容易钻法律的空子，实施犯罪", "近年来，大部分犯罪为经济犯罪，高学历人群的犯罪率明显高于低学历人群", "文化水平低的人，对法律了解相对较少，而且通常低学历者的生存状况较差，更容易铤而走险"], "answer": ["C"], "explain": "第一步：找到论点和论据。\n论点：近年来，随着教育的大规模扩大，学历程度越高，犯罪率越低。\n论据：雨果说：“多建一所学校，就少建一座监狱。”马克·吐温说：“你每关闭一所学校，你就必须开设一座监狱。”在他们看来，教育能够减少犯罪。\n第二步：逐一分析选项。\nA项：举某高校一名本科生杀死母亲的反面个例，不能说明学历程度与犯罪率之间的关系，为无关选项，排除；\nB项：说明学历高的人容易钻法律空子实施犯罪，但是是否去钻法律的空子实施犯罪，不明确，排除；\nC项：经济犯罪作为最主要的犯罪形式，经济犯罪中高学历人群犯罪率高于低学历人群，直接否定论点，当选；\nD项：说明学历程度低，越容易发生犯罪，但是否是真的去犯罪了，不明确，排除。\n⇒ 正确答案为C。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2016年吉林省公务员录用考试《行测》题（甲级） 第13 题", "qid": 2021828, "level": "中等", "stem": "犯罪目的是指犯罪人主观上通过犯罪行为所希望达到的结果，是以观念形态存在于犯罪人大脑中的犯罪行为所预期达到的结果。犯罪动机是刺激、促使犯罪人实施犯罪行为的内心起因或思想活动，它回答犯罪人基于何种心理原因实施犯罪行为。动机的作用是发动犯罪行为，说明实施犯罪行为对行为人的心理愿望具有什么意义。\n根据以上定义，下列说法中正确的是：", "options": ["甲为了报复乙，欲通过投毒的方式剥夺乙的生命，则甲的犯罪目的是报复", "甲担心乙对其实施打击报复，将乙非法拘禁数日，则甲的犯罪动机是恐惧", "甲投毒致乙死亡，经查明是因为其嫉妒乙的才华，则甲的犯罪目的是嫉妒", "甲贪图钱财，通过盗窃而非法占有乙的财物，则甲的犯罪动机是非法占有"], "answer": ["B"], "explain": "第一步：找出定义关键词。\n犯罪目的：“犯罪人主观上”、“希望达到的结果”。犯罪动机：“刺激、促使犯罪人”、“实施犯罪行为的内心起因或思想活动”。\n第二步：逐一分析选项。\nA项：甲希望达到的结果应该是剥夺乙的生命，因此甲的犯罪目的是剥夺乙的生命。而报复是实施犯罪行为的内心起因或思想活动，因此报复应该是犯罪动机，选项错误，排除；\nB项：担心乙对其打击报复，是甲对乙非法拘禁数日的内心起因和思想活动，因此甲的犯罪动机是恐惧，当选；\nC项：既然甲选择了投毒，那他所希望达到的结果肯定是乙死亡，因此甲的犯罪目的是剥夺乙的生命。而嫉妒是甲对乙投毒的内心起因或思想活动，属于犯罪动机，选项错误，排除；\nD项：甲是因为贪图钱财而盗窃的，促使甲实施犯罪行为的内心起因是贪图钱财，所以甲的犯罪动机是贪图钱财，选项错误，排除。\n⇒ 正确答案为B。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2018年上海市公务员录用考试《行测》题（A类）（网友回忆版） 第5 题", "qid": 2395205, "level": "中等", "stem": "一辆列车从长沙开往天津，当列车经过弯道时做匀速圆周运动，假设铁路的内轨和外轨高度一样，那么下列说法正确的是：", "options": ["列车通过弯道向心力的来源是外轨的水平弹力，所以外轨容易磨损", "列车通过弯道向心力的来源是外轨的水平弹力，所以内轨容易磨损", "列车通过弯道向心力的来源是列车的重力，所以内外轨道均不磨损", "列车通过弯道向心力的来源是列车的重力，所以内外轨道均磨损，且磨损程度一致"], "answer": ["A"], "explain": "列车在经过弯道时，做匀速圆周运动，此时水平方向受到的合力提供向心力，由于内轨和外轨高度一样，向心力只有可能来自外轨指向圆心的水平弹力，因而外轨容易磨损。\n⇒ 正确答案为A。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2017年北京市公务员录用考试《行测》题 第20 题", "qid": 2031012, "level": "中等", "stem": "张导演在为联欢会的最后三个节目进行排序，相邻的节目不能属于同一种类。张导演要从三个小品节目、三个歌曲节目、三个舞蹈节目中进行选择。要排好最后这三个节目，还要满足如下条件：\n（1）如第一个节目是小品，则第二个节目是舞蹈\n（2）如第二个节目是歌曲，则第一个节目是舞蹈\n（3）如第三个节目是小品或者舞蹈，则第二个节目是歌曲\n请问以下哪项是节目安排的可能次序？", "options": ["节目一：小品  节目二：舞蹈  节目三：舞蹈", "节目一：小品  节目二：歌曲  节目三：舞蹈", "节目一：歌曲  节目二：小品  节目三：舞蹈", "节目一：舞蹈  节目二：小品  节目三：歌曲"], "answer": ["D"], "explain": "选项信息充分，故可用代入排除法求解。\nA项代入（1）正确，（2）正确，（3）错误，不满足三个条件均正确，排除；\nB项代入（1）错误，（2）错误，（3）正确，不满足三个条件均正确，排除；\nC项代入（1）正确，（2）正确，（3）错误，不满足三个条件均正确，排除；\nD项代入（1）正确，（2）正确，（3）正确，满足三个条件均正确，当选。\n⇒ 正确答案为D。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2024年云南公务员录用考试《行测》题（网友回忆版） 第27 题", "qid": 10204511, "level": "中等", "stem": "地球生命已历经五次由极端自然现象引起的生物多样性大规模灭绝事件。现今，许多专家警告说。xxx人类可以饲养一些动物xxx，但这些举措并不能针对所有物种，由此可见其无法扭转物种灭绝的总体趋势。\n以下哪项如果为真，最能支持上述结论？", "options": ["植物灭绝速度远低于陆生动物，不会灭绝", "地球生物多样性的存在完全是为了人类利益需要", "人类可以饲养海量的各类动物，特别是哺乳动物", "人类需重点关注和保护最具生物多样性的热带雨林"], "answer": ["C"], "explain": "略。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2019年青海省公务员录用考试《行测》题省市州级（A类）（网友回忆版） 第34 题", "qid": 2394044, "level": "中等", "stem": "即将毕业时，某班要评选优秀毕业生，班级内部进行讨论中。\n班长：要么李雪被评为优秀毕业生，要么王磊被评为优秀毕业生。\n团支书：我不同意。\n以下哪项准确表达了团支书的意见？", "options": ["李雪和王磊都被评为优秀毕业生", "李雪和王磊都不能评为优秀毕业生", "要么李雪和王磊都被评为优秀毕业生，要么李雪和王磊都不能评为优秀毕业生", "李雪被评为优秀毕业生，王磊不能评为优秀毕业生"], "answer": ["C"], "explain": "第一步：翻译题干。\n班长：要么李雪，要么王磊\n团支书：我不同意\n团支书不同意的是班长的话，即否定了（要么李雪，要么王磊）这句话。要么，要么是二选一，否定要么，要么有两种情况：①两者都选，②两者都不选。\n第二步：逐一分析选项。\nA项：两个都选，只是团支书的话的其中一种情况，排除；\nB项：两个都不选，只是团支书的话的其中一种情况，排除；\nC项：包含了团支书的话的两种情况，正确；\nD项：不符合团支书的意见，排除。\n⇒ 正确答案为C。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2022年青海省公务员录用考试《行测》题（网友回忆版） 第19 题", "qid": 4817947, "level": "中等", "stem": "鹬蚌相争，渔翁得利", "options": ["兼听则明，偏信则暗", "塞翁失马，焉知非福", "户枢不蠹，流水不腐", "城门失火，殃及池鱼"], "answer": ["D"], "explain": "第一步：判断题干词语间逻辑关系。\n鹬蚌相争，渔翁得利，比喻双方争执不下，两败俱伤，让第三者占了便宜。鹬蚌相争为因，渔翁得利为果，二者为因果对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：兼听则明，偏信则暗，指听取双方或多方面的意见就能明辨是非，只相信单方面的话，必然会犯片面性的错误。二者均单独存在因果对应关系，但二者之间为并列关系，与题干逻辑关系不一致，排除；\nB项：塞翁失马，焉知非福，比喻一时虽然受到损失，反而因此能得到好处。二者间无明显逻辑关系，与题干逻辑关系不一致，排除；\nC项：户枢不蠹，流水不腐，指经常转动的门轴不会被虫蛀，流动的水不会腐臭，比喻经常运动的东西不易受腐蚀，二者为并列关系，与题干逻辑关系不一致，排除；\nD项：城门失火，殃及池鱼，指城门着了火，大家都用护城河的水救火，水用尽了，鱼也就干死了，比喻因牵连而受祸患或损失。城门失火为因，殃及池鱼为果，二者为因果对应关系，与题干逻辑关系一致，当选。\n⇒ 正确答案为D。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2019年江西省法检统一考录公务员笔试《行测》题（网友回忆版） 第30 题", "qid": 2444059, "level": "中等", "stem": "在一次国际会议上，来自英、法、中、德四国的甲、乙、丙、丁四位学者恰好相聚在一组讨论。他们每人除了会说自己本国语言外，还会说其他三国语言中的一种，有一种语言三个人都会说。这四位学者交谈的有关情况如下：\n（1）乙不会说英语，当甲与丙交谈时，他却能替他们作翻译；\n（2）甲是中国人，丁不会说汉语，但他俩却能毫无困难地交谈；\n（3）乙、丙、丁三人找不到一种共同的语言进行交谈；\n（4）在四人中，没有一人既能用汉语交谈，又能用法语交谈。\n据此，可以推出三个人都会说的那种语言是：", "options": ["汉语", "德语", "英语", "法语"], "answer": ["B"], "explain": "因为有一种语言三个人都会说，所以这三个人是能交流的，根据（3）乙、丙、丁三人找不到一种共同的语言进行交谈，说明有两个会说该种语言，一个不会说，而另一个会说的应该是甲，根据（1）可知甲和丙不能交流，所以会说该种语言的不能有丙，则应该是甲乙丁三人。根据（1）乙不会说英语，排除C；根据（2）丁不会说汉语，排除A；根据（4）没有一个人既能用汉语交谈，又能用法语交谈，说明甲不会说法语，排除D。\n⇒ 正确答案为B。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2018年重庆市公务员录用考试《行测》题（下半年） 第32 题", "qid": 2402441, "level": "中等", "stem": "喻洪，覃彬，曾智，一个是马拉松运动员，一个是跳水运动员，一个是举重运动员。跳水运动员比曾智年龄小，覃彬和跳水运动员不同龄，喻洪的年龄比举重运动员大。\n根据上述已知条件，可以推出：", "options": ["覃彬是马拉松运动员，曾智是跳水运动员，喻洪是举重运动员", "覃彬是跳水运动员，曾智是举重运动员，喻洪是马拉松运动员", "覃彬是举重运动员，曾智是马拉松运动员，喻洪是跳水运动员", "覃彬是跳水运动员，曾智是马拉松运动员，喻洪是举重运动员"], "answer": ["C"], "explain": "第一步：分析题干。\n（1）跳水运动员比曾智年龄小；\n（2）覃彬和跳水运动员不同龄；\n（3）喻洪的年龄比举重运动员大。\n第二步：逐一分析选项。\n由条件（1）可知曾智不是跳水运动员，排除A项；\n由条件（2）可知覃彬不是跳水运动员，排除B、D项。\n⇒ 正确答案为C 。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2018年广州市公务员录用考试 《行测》题（3月24日网友回忆版） 第1 题", "qid": 2172078, "level": "中等", "stem": "头发：理发剪 与（  ）在内在逻辑关系上最为相似。", "options": ["指甲：指甲钳", "橡皮：橡皮擦", "铅笔：铅笔盒", "蜜糖：蜜糖罐"], "answer": ["A"], "explain": "第一步：判断题干词语间逻辑关系。\n理发剪是修剪头发的工具，两者为对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：指甲钳是修剪指甲的工具，两者为对应关系。与题干逻辑关系一致，当选；\nB项：橡皮与橡皮擦是全同关系，与题干逻辑关系不一致，排除；\nC项：铅笔盒是用来装铅笔的盒子，不是修剪铅笔的工具，与题干逻辑关系不一致，排除；\nD项：蜜糖罐是盛放蜜糖的罐子，不是修剪蜜糖的工具，与题干逻辑关系不一致，排除。\n⇒ 正确答案为A。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2017年422联考《行测》题（山东卷） 第36 题", "qid": 2049718, "level": "中等", "stem": "水力压裂是一项有广泛应用前景的油气井增产措施，这种方法利用地面高压泵，通过井筒向油层挤注具有较高粘度的压裂液，将油层压开并产生裂缝，使油层与井筒之间建立起一条新的流体通道。压裂之后，油气井的产量一般会大幅度增长。但这种技术会给环境带来极大的破坏。\n补充以下哪项论据，可以得到以上结论？", "options": ["当注入压裂液的速度超过油层的吸收能力时，井底油层会形成很高的压力", "为保证已压开的裂缝不致于闭合，需要注入顶替液进入裂缝，将其支撑起来", "油气田的开发会影响附近居民的生活，居民用水的管道需要绕开井筒所在位置", "向地表以下注入高强度的压裂液，可能会激活休眠地质断层，从而引发地震"], "answer": ["D"], "explain": "第一步：找到论点论据。\n论点：利用水力压裂进行油气井增产这种措施之后，油气井的产量一般会大幅增长，但这种技术会给环境带来极大地破坏。\n论据：无明显论据。\n第二步：逐一分析选项。\nA项：井底油层会形成很高的压力，和题干提到的是否会对环境造成影响无关，排除；\nB项：需注入顶替液进入裂缝，将其撑起来，和题干提到的是否会对环境造成影响无关，排除；\nC项：油气田的开发会影响居民的生活，但是否影响环境不明确，排除；\nD项：注入压裂液会激活休眠地质断层引发地震，证明使用这种增产措施会导致发生地震，地震会给环境带来极大破坏，补充论据，能够支持题干观点，当选。\n⇒ 正确答案为D。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2018年广西选调生考试《行测》试题（网友回忆版） 第21 题", "qid": 2184634, "level": "中等", "stem": "报纸：读者：发行量", "options": ["论文：作者：引用率", "港口：货物：吞吐量", "影片：观众：票房", "比赛：主办方：赞助费"], "answer": ["C"], "explain": "第一步：判断题干词语间逻辑关系。\n“读者”是“报纸”的服务对象，“报纸”销售越多，“发行量”越大，“读者”越多。\n第二步：判断选项词语间逻辑关系。\nA项：“论文”的服务对象不是“作者”，而是读者，与题干逻辑关系不一致，排除。\nB项：“港口”用于存放运输“货物”，经水运输出或输入并经过装卸作业的“货物”越多，“吞吐量”越大，与题干逻辑关系不一致，排除。\nC项： “观众”是“影片”的服务对象，“影片”销售越多，“票房”越高，“观众”越多，与题干逻辑关系一致，当选。\nD项：“主办方”是主办“比赛”的主体，不是“比赛”的服务对象，与题干逻辑关系不一致，排除。\n⇒ 正确答案为C。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2017年福建省选调生考试《行政职业能力测验》 第6 题", "qid": 4733952, "level": "中等", "stem": "“洼地效应”就是利用比较优势，创造理想的经济和社会人文环境，使之对各类生产要素具有更强的吸引力，从而形成独特竞争优势，吸引外来资源向本地区汇聚、流动，弥补本地资源结构上的缺陷，促进本地区经济和社会的快速发展。简单地说，指一个区域与其他区域相比，环境质量更高，对各类生产要素具有更强的吸引力，从而形成独特竞争优势。\n根据以上定义，下面属于洼地效应的是:", "options": ["一些知名跨国公司跑到中国办公司", "天津静海地区传销比较多", "XX省假鞋泛滥", "某明星被曝光吸毒，于是微博粉丝纷纷取消关注"], "answer": ["A"], "explain": "第一步：找出定义关键词。\n“利用比较优势”、“形成独特竞争优势”、“吸引外来资源向本地区汇聚、流动”、“促进本地区经济和社会的快速发展”。\n第二步：逐一分析选项。\nA项：跨国公司来中国办公司，是中国对外来资源的吸引，符合“吸引外来资源向本地区汇聚、流动”，也可以促进中国的经济发展，符合“促进本地区经济和社会的快速发展”，符合定义，当选；\nB项传销、C项假鞋泛滥以及D项明星吸毒均属于违法行为，不符合“形成独特竞争优势”，也不符合“促进本地区经济和社会的快速发展”，不符合定义，排除。\n⇒ 正确答案为A。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}, {"type": "论证推理", "from": "2018年福建省选调生考试《行政职业能力测验》 第14 题", "qid": 4714941, "level": "中等", "stem": "对比是指故意把两个相反、相对的事物或同一事物相反、相对的两个方面放在一起，用比较的方法加以描述或说明以提示事物的本质，使好的显得更好，使坏的显得更坏，对比是表明对立现象的，两种对立的事物是平行的并列关系。\n根据以上定义，下列哪项没有运用对比：", "options": ["政之所兴，在顺民心；政之所废，在逆民心", "亲贤臣，远小人，此先汉所以兴隆也；亲小人，远贤臣，此后汉所以倾颓也", "有缺点的战士终究是战士，完美的苍蝇终究不过是苍蝇", "海鸥在大海上飞窜，轰隆隆的雷声把海鸥吓坏了，企鹅胆怯地把肥胖的身躯躲藏在悬崖底······只有那高傲的海燕，勇敢地、自由自在地在泛起白沫的大海上飞翔"], "answer": ["D"], "explain": "第一步：找出定义关键词。\n“两个相反、相对的事物”、“同一事物相反、相对的两个方面”、“用比较的方法”、“以提示事物的本质”、“使好的显得更好，使坏的显得更坏”。\n第二步：逐一分析选项。\nA项：选项将“政兴”和“政废”进行比较，从而得到“政权兴废的关键在于民心”，符合“同一事物相反、相对的两个方面”、“用比较的方法”、“以提示事物的本质”，符合定义，排除；\nB项：选项将“先汉兴隆”和“后汉倾颓”进行比较，从而得到“国家兴衰的关键在于对贤臣和小人的态度”，符合“两个相反、相对的事物”、“用比较的方法”、“以提示事物的本质”，符合定义，排除；\nC项：选项将“有缺点的战士”和“完美的苍蝇”进行比较，以此“颂扬战士，抨击苍蝇”，符合“两个相反、相对的事物”、“用比较的方法”、“使好的显得更好，使坏的显得更坏”，符合定义，排除；\nD项：选项将“吓坏的海鸥”、“胆怯的企鹅”和“勇敢的海燕”三者进行比较，以衬托出海燕的勇敢，这三者并不是相对的，不符合“两个相反、相对的事物”、“同一事物相反、相对的两个方面”，不符合定义，当选。\n本题为选非题，⇒ 正确答案为D。", "point": "考论点、论据与结论之间的推理关系是否成立。", "method": "先抓论点和论据，再判断选项在加强、削弱还是无关。", "tip": "话题是否一致，是判断选项能否成立的第一关。"}]}];
